def fetch_source_content(
    source_type: Optional[str] = None,
    fetch_hint: Optional[str] = None,
    source_ref: Optional[str] = None,
    ref_id: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Fetch full content for a source, using fetch_hint to determine how.

    Used by Phase A to load the complete email, meeting transcript,
    or comment thread for scanning beyond what Phase 0 captured.

    Can be called two ways:
    1. With explicit source_type + fetch_hint (original interface)
    2. With ref_id only — looks up the archival passage to extract source_type
       and fetch_hint automatically. Simpler for enrichment pipeline callers.

    Args:
        source_type: One of "email", "meeting", "slack", "google-docs-comment". Optional if ref_id provided.
        fetch_hint: Retrieval instruction from the spark record. Optional if ref_id provided.
            Format: "gmail:MESSAGE_ID" for email, "granola:MEETING_ID" for meetings.
            For slack/docs-comment, pass the reference_id instead.
        source_ref: Optional reference_id for additional context lookup.
        ref_id: The 8-char hex reference ID of the task. If provided, looks up the archival passage to extract source_type and fetch_hint automatically.

    Returns:
        Dictionary with status, content text, and metadata.
    """
    import json
    import os
    import re
    import subprocess
    import traceback
    import urllib.request
    import urllib.error

    try:
        LETTA_BASE = os.environ.get("LETTA_BASE_URL", "http://localhost:8283")
        AGENT_ID = os.environ.get("TASKS_AGENT_ID", "agent-dd15479e-6543-400e-8463-b2a48b13cd4a")

        # If ref_id provided, look up archival passage to extract source_type and fetch_hint
        if ref_id:
            search_url = f"{LETTA_BASE}/v1/agents/{AGENT_ID}/archival-memory/?search={ref_id}&limit=3"
            req = urllib.request.Request(search_url)
            try:
                with urllib.request.urlopen(req, timeout=15) as resp:
                    passages = json.loads(resp.read().decode("utf-8"))
            except urllib.error.HTTPError as e:
                if e.code in (301, 302, 307, 308):
                    req2 = urllib.request.Request(e.headers.get("Location", ""))
                    with urllib.request.urlopen(req2, timeout=15) as resp2:
                        passages = json.loads(resp2.read().decode("utf-8"))
                else:
                    raise
            if not isinstance(passages, list):
                passages = []

            task_passage = None
            for p in passages:
                if isinstance(p, dict) and f"REF_ID: {ref_id}" in p.get("text", ""):
                    task_passage = p
                    break

            if not task_passage:
                return {"status": "error", "error_message": f"No archival passage found for ref_id {ref_id}"}

            p_text = task_passage.get("text", "")

            # Extract source_type from passage
            type_match = re.search(r"- Type: (.+)$", p_text, re.MULTILINE)
            if type_match and not source_type:
                source_type = type_match.group(1).strip()

            # Extract fetch_hint from passage
            hint_match = re.search(r"FETCH HINT: (.+)$", p_text, re.MULTILINE)
            if hint_match and not fetch_hint:
                fetch_hint = hint_match.group(1).strip()

            # Extract reference_id as source_ref fallback
            ref_match = re.search(r"- Reference ID: (.+)$", p_text, re.MULTILINE)
            if ref_match and not source_ref:
                source_ref = ref_match.group(1).strip()

            # If no fetch_hint found, fall back to source text from passage
            if not fetch_hint and not source_ref:
                st_match = re.search(r"SOURCE TEXT\n(.+?)(?=\nFETCH HINT:|\nENRICH|\nPACKET INFO|\Z)", p_text, re.DOTALL)
                if st_match:
                    return {
                        "status": "ok",
                        "source_type": source_type or "unknown",
                        "content": st_match.group(1).strip(),
                        "metadata": {"source": "passage_text", "ref_id": ref_id},
                        "content_length": len(st_match.group(1).strip()),
                    }

        if not source_type:
            return {"status": "error", "error_message": "source_type required (provide directly or via ref_id)"}
        if not fetch_hint and not source_ref:
            return {"status": "error", "error_message": "fetch_hint or source_ref required (provide directly or via ref_id)"}

        content = ""
        metadata = {}

        if source_type == "email" and fetch_hint and fetch_hint.startswith("gmail:"):
            # Fetch full email via gws CLI
            message_id = fetch_hint.split(":", 1)[1]
            try:
                result = subprocess.run(
                    ["gws", "gmail", "users", "messages", "get",
                     "--params", json.dumps({"userId": "me", "id": message_id, "format": "full"}),
                     "--format", "json"],
                    capture_output=True, text=True, timeout=15,
                )
                if result.returncode == 0:
                    # Skip keyring line
                    raw = "\n".join(l for l in result.stdout.split("\n") if not l.startswith("Using keyring"))
                    msg = json.loads(raw)

                    # Extract headers
                    headers = {}
                    for h in msg.get("payload", {}).get("headers", []):
                        headers[h["name"]] = h["value"]
                    metadata = {
                        "subject": headers.get("Subject", ""),
                        "from": headers.get("From", ""),
                        "to": headers.get("To", ""),
                        "date": headers.get("Date", ""),
                        "thread_id": msg.get("threadId", ""),
                    }

                    # Extract body text
                    import base64

                    # Extract text body from MIME parts
                    payload = msg.get("payload", {})
                    body_data = None

                    # Walk MIME tree to find text/plain
                    parts_to_check = [payload]
                    while parts_to_check:
                        part = parts_to_check.pop(0)
                        if part.get("mimeType") == "text/plain" and part.get("body", {}).get("data"):
                            body_data = part["body"]["data"]
                            break
                        parts_to_check.extend(part.get("parts", []))

                    if body_data:
                        content = base64.urlsafe_b64decode(body_data).decode("utf-8", "replace")
                    else:
                        content = msg.get("snippet", "")

                    # Also fetch thread context if this is part of a thread
                    thread_id = msg.get("threadId", "")
                    if thread_id and thread_id != message_id:
                        try:
                            thread_result = subprocess.run(
                                ["gws", "gmail", "users", "threads", "get",
                                 "--params", json.dumps({"userId": "me", "id": thread_id, "format": "metadata",
                                                          "metadataHeaders": ["Subject", "From", "Date"]}),
                                 "--format", "json"],
                                capture_output=True, text=True, timeout=15,
                            )
                            if thread_result.returncode == 0:
                                t_raw = "\n".join(l for l in thread_result.stdout.split("\n")
                                                  if not l.startswith("Using keyring"))
                                thread = json.loads(t_raw)
                                thread_msgs = thread.get("messages", [])
                                if len(thread_msgs) > 1:
                                    # Cap at last 10 messages to avoid context overflow
                                    recent_msgs = thread_msgs[-10:]
                                    thread_context = []
                                    for tm in recent_msgs:
                                        tm_headers = {h["name"]: h["value"]
                                                      for h in tm.get("payload", {}).get("headers", [])}
                                        thread_context.append(
                                            f"[{tm_headers.get('Date','')}] "
                                            f"From: {tm_headers.get('From','')} — "
                                            f"{tm.get('snippet','')[:150]}"
                                        )
                                    prefix = f"({len(thread_msgs)} messages in thread, showing last {len(recent_msgs)})\n" if len(thread_msgs) > 10 else ""
                                    content += f"\n\n--- THREAD CONTEXT ---\n{prefix}" + "\n".join(thread_context)
                                    metadata["thread_message_count"] = len(thread_msgs)
                        except Exception:
                            pass  # Thread fetch is best-effort
                else:
                    content = f"(gws error: {result.stderr[:200]})"
            except FileNotFoundError:
                # gws not available in this container — try via archival
                content = "(gws CLI not available — use archival search instead)"
            except Exception as e:
                content = f"(fetch error: {str(e)[:200]})"

        elif source_type == "meeting" and fetch_hint and fetch_hint.startswith("granola:"):
            # Fetch meeting from archival
            meeting_id = fetch_hint.split(":", 1)[1]
            try:
                search_url = f"{LETTA_BASE}/v1/agents/{AGENT_ID}/archival-memory/?search={meeting_id}&limit=3"
                req = urllib.request.Request(search_url)
                with urllib.request.urlopen(req, timeout=15) as resp:
                    passages = json.loads(resp.read().decode("utf-8"))

                if isinstance(passages, list):
                    # Find the meeting passage (longest one with meeting content)
                    best = max(passages, key=lambda p: len(p.get("text", "")) if isinstance(p, dict) else 0)
                    if isinstance(best, dict):
                        content = best.get("text", "")
                        metadata = {"meeting_id": meeting_id}
            except Exception as e:
                content = f"(archival search error: {str(e)[:200]})"

        elif source_type == "slack":
            # Parse channel + thread_ts from reference_id or fetch_hint
            # Format: slack-CHANNEL_ID-MESSAGE_TS or slack-CHANNEL_ID-MSG_TS-tTHREAD_TS
            ref = fetch_hint or source_ref or ""
            import re as _re
            slack_match = _re.match(r"slack-([A-Z0-9]+)-([\d.]+)(?:-t([\d.]+))?", ref)
            if slack_match:
                channel_id = slack_match.group(1)
                message_ts = slack_match.group(2)
                thread_ts = slack_match.group(3) or message_ts

                # Prefer user token (xoxp) for broader channel access
                slack_token = os.environ.get("SLACK_MCP_XOXP_TOKEN", "") or os.environ.get("SLACK_BOT_TOKEN", "")
                if not slack_token:
                    # Sandbox may not inherit env — try reading from .env
                    try:
                        for env_path in ["/app/.env", os.path.expanduser("~/.env")]:
                            if os.path.exists(env_path):
                                with open(env_path) as ef:
                                    for eline in ef:
                                        if eline.startswith("SLACK_MCP_XOXP_TOKEN="):
                                            slack_token = eline.split("=", 1)[1].strip()
                                            break
                                        if not slack_token and eline.startswith("SLACK_BOT_TOKEN="):
                                            slack_token = eline.split("=", 1)[1].strip()
                            if slack_token:
                                break
                    except Exception:
                        pass
                if slack_token:
                    try:
                        auth_header = {"Authorization": f"Bearer {slack_token}"}
                        thread_lines = []

                        # If message is in a thread, fetch thread replies
                        if thread_ts != message_ts:
                            thread_url = (
                                f"https://slack.com/api/conversations.replies"
                                f"?channel={channel_id}&ts={thread_ts}&limit=15"
                            )
                            treq = urllib.request.Request(thread_url, headers=auth_header)
                            with urllib.request.urlopen(treq, timeout=10) as tresp:
                                tdata = json.loads(tresp.read().decode("utf-8"))
                            if tdata.get("ok") and tdata.get("messages"):
                                for tm in tdata["messages"][-15:]:
                                    thread_lines.append(
                                        f"[{tm.get('ts','')}] <@{tm.get('user','')}>: "
                                        f"{tm.get('text','')[:200]}"
                                    )

                        # Also fetch surrounding channel messages (3 before, 3 after)
                        # Before
                        before_url = (
                            f"https://slack.com/api/conversations.history"
                            f"?channel={channel_id}&latest={message_ts}"
                            f"&limit=4&inclusive=false"
                        )
                        breq = urllib.request.Request(before_url, headers=auth_header)
                        with urllib.request.urlopen(breq, timeout=10) as bresp:
                            bdata = json.loads(bresp.read().decode("utf-8"))
                        before_msgs = list(reversed(bdata.get("messages", [])[:3]))

                        # After
                        after_url = (
                            f"https://slack.com/api/conversations.history"
                            f"?channel={channel_id}&oldest={message_ts}"
                            f"&limit=4&inclusive=false"
                        )
                        areq = urllib.request.Request(after_url, headers=auth_header)
                        with urllib.request.urlopen(areq, timeout=10) as aresp:
                            adata = json.loads(aresp.read().decode("utf-8"))
                        after_msgs = adata.get("messages", [])[:3]

                        context_lines = []
                        for cm in before_msgs:
                            context_lines.append(
                                f"[before] <@{cm.get('user','')}>: {cm.get('text','')[:200]}"
                            )
                        context_lines.append(f"[THIS MESSAGE] ts={message_ts}")
                        for cm in after_msgs:
                            context_lines.append(
                                f"[after] <@{cm.get('user','')}>: {cm.get('text','')[:200]}"
                            )

                        if thread_lines:
                            content = "--- THREAD ---\n" + "\n".join(thread_lines)
                            content += "\n\n--- CHANNEL CONTEXT ---\n" + "\n".join(context_lines)
                        else:
                            content = "--- CHANNEL CONTEXT ---\n" + "\n".join(context_lines)

                        metadata = {
                            "channel_id": channel_id,
                            "thread_ts": thread_ts,
                            "thread_count": len(thread_lines),
                            "context_before": len(before_msgs),
                            "context_after": len(after_msgs),
                        }
                    except Exception as e:
                        content = f"(Slack fetch error: {str(e)[:200]})"
                else:
                    content = "(No SLACK_BOT_TOKEN available)"
            else:
                content = f"(Could not parse Slack reference: {ref[:60]})"
            metadata = metadata if content and not content.startswith("(") else {"hint": "Parse failed"}

        elif source_type == "google-docs-comment":
            # Comment content was already enriched by DriveEnricher
            # Discovery would scan comment replies — use run_gws
            content = "(Docs comment replies require run_gws — call run_gws directly)"
            metadata = {"hint": "Use run_gws to fetch comment reply chain for discovery"}

        else:
            return {"status": "error", "error_message": f"Unsupported source_type: {source_type}"}

        # Truncate very long content
        if len(content) > 5000:
            content = content[:5000] + "\n\n(truncated at 5000 chars)"

        return {
            "status": "ok",
            "source_type": source_type,
            "content": content,
            "metadata": metadata,
            "content_length": len(content),
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

def search_github_stars(
    query: Optional[str] = None,
    repo: Optional[str] = None,
    readme: Optional[bool] = None,
    limit: Optional[int] = None,
    cursor: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Search and browse your starred GitHub repositories.

    Three modes:
      1. Browse: No query/repo — returns most recently starred repos (supports cursor pagination)
      2. Search: query="keyword" — searches starred repos by name/description/topics (up to 500 stars scanned)
      3. Lookup: repo="owner/name" — fetches details for a specific repo

    Examples:
      search_github_stars()                                  — 10 most recent stars
      search_github_stars(query="mcp")                       — search stars matching "mcp"
      search_github_stars(repo="anthropics/claude-code")     — specific repo details
      search_github_stars(query="agent", readme=True)        — search with README content
      search_github_stars(cursor="abc123")                   — next page of recent stars

    Args:
        query: Keyword to search starred repos by name, description, and topics. Omit to list recent stars.
        repo: Full repo name (owner/repo) to look up a specific repo's details.
        readme: Set to True to include README.md content in results.
        limit: Max results to return (default 10, max 50). Ignored when repo is set.
        cursor: Pagination cursor from previous response's next_cursor (browse mode only, ignored in search mode).

    Returns:
        Dictionary with status, repos list, total_count, and next_cursor.
    """
    import json
    import os
    import traceback
    import urllib.request
    import urllib.error

    try:
        token = os.environ.get("GITHUB_TOKEN")
        if not token:
            return {"status": "error", "error_message": "GITHUB_TOKEN environment variable not set"}

        if limit is None:
            limit = 10
        limit = max(1, min(limit, 50))

        graphql_url = "https://api.github.com/graphql"
        readme_fragment = ""
        if readme:
            readme_fragment = """
                object(expression: "HEAD:README.md") {
                  ... on Blob { text }
                }"""

        # --- Repo lookup mode ---
        if repo:
            parts = repo.strip().split("/", 1)
            if len(parts) != 2:
                return {"status": "error", "error_message": f"Invalid repo format: {repo}. Use owner/name."}
            owner, name = parts

            gql = """
            query($owner: String!, $name: String!) {
              repository(owner: $owner, name: $name) {
                nameWithOwner
                url
                description
                primaryLanguage { name }
                stargazerCount
                repositoryTopics(first: 20) {
                  nodes { topic { name } }
                }
                README_PLACEHOLDER
              }
            }
            """.replace("README_PLACEHOLDER", readme_fragment if readme else "")

            variables = {"owner": owner, "name": name}
            payload = json.dumps({"query": gql, "variables": variables}).encode()
            req = urllib.request.Request(graphql_url, data=payload, method="POST")
            req.add_header("Authorization", f"Bearer {token}")
            req.add_header("Content-Type", "application/json")
            req.add_header("User-Agent", "letta-github-stars-tool")

            resp = urllib.request.urlopen(req, timeout=30)
            data = json.loads(resp.read().decode())

            if "errors" in data:
                return {"status": "error", "error_message": str(data["errors"])}

            r = data.get("data", {}).get("repository")
            if not r:
                return {"status": "error", "error_message": f"Repository not found: {repo}"}

            readme_text = None
            if readme:
                obj = r.get("object")
                if obj:
                    readme_text = obj.get("text")

            repo_entry = {
                "name": r.get("nameWithOwner", repo),
                "url": r.get("url", f"https://github.com/{repo}"),
                "description": r.get("description"),
                "language": (r.get("primaryLanguage") or {}).get("name"),
                "stars": r.get("stargazerCount", 0),
                "topics": [n["topic"]["name"] for n in (r.get("repositoryTopics", {}).get("nodes") or [])],
            }
            if readme:
                repo_entry["readme"] = readme_text

            return {"status": "ok", "repos": [repo_entry], "total_count": 1}

        # --- Build starred repos GraphQL query ---
        gql = """
        query($first: Int!, $after: String) {
          viewer {
            starredRepositories(first: $first, after: $after, orderBy: {field: STARRED_AT, direction: DESC}) {
              totalCount
              pageInfo { endCursor hasNextPage }
              edges {
                starredAt
                node {
                  nameWithOwner
                  url
                  description
                  primaryLanguage { name }
                  stargazerCount
                  repositoryTopics(first: 20) {
                    nodes { topic { name } }
                  }
                  README_PLACEHOLDER
                }
              }
            }
          }
        }
        """.replace("README_PLACEHOLDER", readme_fragment if readme else "")

        # --- Browse mode (no query) ---
        if not query:
            variables = {"first": limit}
            if cursor:
                variables["after"] = cursor

            payload = json.dumps({"query": gql, "variables": variables}).encode()
            req = urllib.request.Request(graphql_url, data=payload, method="POST")
            req.add_header("Authorization", f"Bearer {token}")
            req.add_header("Content-Type", "application/json")
            req.add_header("User-Agent", "letta-github-stars-tool")

            resp = urllib.request.urlopen(req, timeout=30)
            data = json.loads(resp.read().decode())

            if "errors" in data:
                return {"status": "error", "error_message": str(data["errors"])}

            starred = data.get("data", {}).get("viewer", {}).get("starredRepositories", {})
            repos = []
            for edge in (starred.get("edges") or []):
                node = edge.get("node", {})
                entry = {
                    "name": node.get("nameWithOwner"),
                    "url": node.get("url"),
                    "description": node.get("description"),
                    "language": (node.get("primaryLanguage") or {}).get("name"),
                    "stars": node.get("stargazerCount", 0),
                    "topics": [n["topic"]["name"] for n in (node.get("repositoryTopics", {}).get("nodes") or [])],
                    "starred_at": edge.get("starredAt"),
                }
                if readme:
                    obj = node.get("object")
                    text = obj.get("text") if obj else None
                    entry["readme"] = text[:2000] if text and len(text) > 2000 else text
                repos.append(entry)

            page_info = starred.get("pageInfo", {})
            next_cursor = page_info.get("endCursor") if page_info.get("hasNextPage") else None

            return {
                "status": "ok",
                "repos": repos,
                "total_count": starred.get("totalCount", 0),
                "next_cursor": next_cursor,
            }

        # --- Search mode (query set) ---
        search_lower = query.lower()
        all_repos = []
        fetch_cursor = None
        max_pages = 5  # 500 stars max

        for _ in range(max_pages):
            variables = {"first": 100}
            if fetch_cursor:
                variables["after"] = fetch_cursor

            payload = json.dumps({"query": gql, "variables": variables}).encode()
            req = urllib.request.Request(graphql_url, data=payload, method="POST")
            req.add_header("Authorization", f"Bearer {token}")
            req.add_header("Content-Type", "application/json")
            req.add_header("User-Agent", "letta-github-stars-tool")

            resp = urllib.request.urlopen(req, timeout=30)
            data = json.loads(resp.read().decode())

            if "errors" in data:
                return {"status": "error", "error_message": str(data["errors"])}

            starred = data.get("data", {}).get("viewer", {}).get("starredRepositories", {})

            for edge in (starred.get("edges") or []):
                node = edge.get("node", {})
                name = node.get("nameWithOwner") or ""
                desc = node.get("description") or ""
                topics = [n["topic"]["name"] for n in (node.get("repositoryTopics", {}).get("nodes") or [])]
                topics_str = " ".join(topics)

                searchable = f"{name} {desc} {topics_str}".lower()
                if search_lower in searchable:
                    entry = {
                        "name": name,
                        "url": node.get("url"),
                        "description": node.get("description"),
                        "language": (node.get("primaryLanguage") or {}).get("name"),
                        "stars": node.get("stargazerCount", 0),
                        "topics": topics,
                        "starred_at": edge.get("starredAt"),
                    }
                    if readme:
                        obj = node.get("object")
                        text = obj.get("text") if obj else None
                        entry["readme"] = text[:2000] if text and len(text) > 2000 else text
                    all_repos.append(entry)

            page_info = starred.get("pageInfo", {})
            if not page_info.get("hasNextPage"):
                break
            fetch_cursor = page_info.get("endCursor")

        return {
            "status": "ok",
            "repos": all_repos[:limit],
            "total_count": len(all_repos),
        }

    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = e.read().decode()[:500]
        except Exception:
            pass
        return {"status": "error", "error_message": f"GitHub API error {e.code}: {body}\n{traceback.format_exc()}"}
    except Exception as e:
        return {"status": "error", "error_message": f"{str(e)}\n{traceback.format_exc()}"}

def manage_widget_queue(action: str, task_ids: Optional[str] = None, position: Optional[int] = None) -> Dict[str, Any]:
    """
    Manage the OmniFocus timer widget queue on the laptop.

    Controls the floating timer widget's task queue — add, remove, reorder,
    or list tasks queued for focused work sessions.

    Args:
        action: Queue operation. One of: list, set, push, insert, remove, move, clear.
            list — return current queue contents
            set — replace entire queue (task_ids: comma-separated OmniFocus task IDs in priority order)
            push — append task(s) to end of queue (task_ids: comma-separated)
            insert — insert task at position (task_ids: single ID, position: 0-indexed)
            remove — remove task from queue (task_ids: single ID)
            move — move task to position (task_ids: single ID, position: 0-indexed)
            clear — empty the queue
        task_ids: Comma-separated OmniFocus task IDs. Required for set, push, insert, remove, move.
        position: Target position for insert/move (0-indexed). Required for insert, move.

    Returns:
        Dictionary with status and current queue state.
    """
    import subprocess
    import json
    import traceback

    try:
        LAPTOP_USER = "chaddorsey"
        LAPTOP_HOST = "100.95.213.46"
        QUEUE_SCRIPT = "~/Dropbox/dev/omnifocus-timer/widget-queue.sh"

        valid_actions = ("list", "set", "push", "insert", "remove", "move", "clear")
        if not action or action not in valid_actions:
            return {"status": "error", "error_message": f"Invalid action: {action}. Must be one of: {', '.join(valid_actions)}"}

        # Build the remote command
        cmd_parts = [QUEUE_SCRIPT, action]
        if action == "set" and task_ids:
            for tid in task_ids.split(","):
                tid = tid.strip()
                if tid:
                    cmd_parts.append(tid)
        elif action == "push" and task_ids:
            for tid in task_ids.split(","):
                tid = tid.strip()
                if tid:
                    cmd_parts.append(tid)
        elif action == "insert":
            if position is None:
                return {"status": "error", "error_message": "position is required for insert"}
            if not task_ids:
                return {"status": "error", "error_message": "task_ids is required for insert"}
            cmd_parts.append(str(position))
            cmd_parts.append(task_ids.strip())
        elif action == "remove":
            if not task_ids:
                return {"status": "error", "error_message": "task_ids is required for remove"}
            cmd_parts.append(task_ids.strip())
        elif action == "move":
            if not task_ids:
                return {"status": "error", "error_message": "task_ids is required for move"}
            if position is None:
                return {"status": "error", "error_message": "position is required for move"}
            cmd_parts.append(task_ids.strip())
            cmd_parts.append(str(position))

        remote_cmd = " ".join(cmd_parts)
        ssh_cmd = [
            "ssh", "-o", "StrictHostKeyChecking=no", "-o", "ConnectTimeout=5",
            f"{LAPTOP_USER}@{LAPTOP_HOST}",
            remote_cmd,
        ]

        result = subprocess.run(ssh_cmd, capture_output=True, text=True, timeout=15)

        if result.returncode != 0:
            return {"status": "error", "error_message": f"SSH failed (exit {result.returncode}): {result.stderr.strip()[:500]}"}

        output = result.stdout.strip()
        try:
            return json.loads(output)
        except json.JSONDecodeError:
            return {"status": "ok", "raw_output": output}

    except Exception as e:
        return {"status": "error", "error_message": f"{str(e)}\n{traceback.format_exc()}"}

def run_twitter(command: str, params: Optional[str] = None) -> Dict[str, Any]:
    """
    Interact with Twitter — read feeds, search, manage lists, bookmark tweets.

    Use command="schema" to see all available commands and their parameters.
    Use command="schema <name>" to see details for a specific command.

    Quick start:
      command="feed"                         -- Your home timeline
      command="user"    params='{"handle":"elonmusk","count":10}'  -- Someone's tweets
      command="search"  params='{"q":"AI agents"}'                 -- Search
      command="lists"                        -- Your Twitter lists (owned + followed)
      command="list-tweets" params='{"list_id":"123"}'  -- Tweets from a list
      command="curators"                     -- Top Twitter curators
      command="schema"                       -- List all commands

    Args:
        command: Command name or "schema" for discovery (REQUIRED)
        params: Optional JSON string of parameters (e.g. '{"count": 10}')

    Returns:
        Dictionary with status and the API response.
    """
    import json
    import traceback
    import urllib.request
    import urllib.parse

    # ENDPOINTS must be inside function body (Letta extracts function source only)
    ENDPOINTS = {
        # --- Read ---
        "feed": {
            "method": "GET",
            "path": "/twitter/feed",
            "description": "Your home timeline (paginated)",
            "params": {"count": "int (default 20)", "cursor": "str (optional, for next page)"},
