        },
        "bookmarks": {
            "method": "GET",
            "path": "/twitter/bookmarks",
            "description": "Your bookmarked tweets (paginated)",
            "params": {"count": "int (default 20)", "cursor": "str (optional, for next page)"},
        },
        "search": {
            "method": "GET",
            "path": "/twitter/search",
            "description": "Search tweets (paginated)",
            "params": {"q": "str (required)", "count": "int (default 20)", "cursor": "str (optional, for next page)"},
        },
        "tweet": {
            "method": "GET",
            "path": "/twitter/tweet/{tweet_id}",
            "description": "A tweet and its replies",
            "params": {"tweet_id": "str (required, in path)"},
        },
        "lists": {
            "method": "GET",
            "path": "/twitter/lists",
            "description": "Your owned and followed Twitter lists (id, name, member_count)",
            "params": {},
        },
        "list-members": {
            "method": "GET",
            "path": "/twitter/list/{list_id}/members",
            "description": "Members of a Twitter list (paginated)",
            "params": {"list_id": "str (required, in path)", "count": "int (default 100)", "cursor": "str (optional, for next page)"},
        },
        "list-tweets": {
            "method": "GET",
            "path": "/twitter/list/{list_id}/tweets",
            "description": "Recent tweets from a list timeline (paginated). Response includes next_cursor — pass it back as cursor to get the next page.",
            "params": {"list_id": "str (required, in path)", "count": "int (default 20)", "cursor": "str (optional, for pagination)"},
        },
        "curators": {
            "method": "GET",
            "path": "/twitter/curators",
            "description": "Top Twitter curators by retweeter overlap score",
            "params": {"top_k": "int (default 50)"},
        },
        "status": {
            "method": "GET",
            "path": "/twitter/status",
            "description": "Twitter ingestion progress and fetch status",
            "params": {},
        },
        # --- Write ---
        "bookmark": {
            "method": "POST",
            "path": "/twitter/bookmark/{tweet_id}",
            "description": "Bookmark a tweet (NOTE: currently blocked by Twitter — returns 404. Use list-add to save tweets to a list instead)",
            "params": {"tweet_id": "str (required, in path)"},
        },
        "list-add": {
            "method": "POST",
            "path": "/twitter/list-add",
            "description": "Add a user to a Twitter list",
            "params": {"list_id": "str (required)", "handle": "str (required)"},
        },
        "list-remove": {
            "method": "POST",
            "path": "/twitter/list-remove",
            "description": "Remove a user from a Twitter list",
            "params": {"list_id": "str (required)", "handle": "str (required)"},
        },
        "list-create": {
            "method": "POST",
            "path": "/twitter/list/create",
            "description": "Create a new Twitter list",
            "params": {"name": "str (required)", "description": "str (optional)", "private": "bool (default true)"},
        },
    }

    try:
        clean = command.strip().strip("/")

        # Schema discovery
        if clean == "schema":
            groups = {"read": [], "write": [], "pipeline": []}
            for name, meta in ENDPOINTS.items():
                if meta["method"] == "GET":
                    group = "read"
                elif name in ("run", "score"):
                    group = "pipeline"
                else:
                    group = "write"
                groups[group].append(
                    {"command": name, "description": meta["description"]}
                )
            return {"status": "ok", "result": groups}

        if clean.startswith("schema "):
            target = clean.split(" ", 1)[1].strip()
            if target in ENDPOINTS:
                meta = ENDPOINTS[target]
                return {"status": "ok", "result": {
                    "command": target,
                    "method": meta["method"],
                    "description": meta["description"],
                    "params": meta["params"] or "(none)",
                }}
            return {"status": "error", "error_message": f"Unknown command: {target}. Use command='schema' to list all."}

        # Resolve endpoint
        meta = ENDPOINTS.get(clean)
        if not meta:
            return {"status": "error", "error_message": f"Unknown command: {clean}. Use command='schema' to list all."}

        base_url = "http://curator-radar:5145/v1"

        query_params = {}
        if params:
            query_params = json.loads(params)

        # Normalize common param aliases
        ALIASES = {"id": "tweet_id", "list": "list_id", "user": "handle", "query": "q"}
        for alias, canonical in ALIASES.items():
            if alias in query_params and canonical not in query_params:
                query_params[canonical] = query_params.pop(alias)

        # Build URL, substituting path parameters
        path = meta["path"]
        path_params = {}
        for key in list(query_params.keys()):
            placeholder = "{" + key + "}"
            if placeholder in path:
                path = path.replace(placeholder, str(query_params.pop(key)))
                path_params[key] = True

        url = f"{base_url}{path}"

        if meta["method"] == "GET" and query_params:
            url += "?" + urllib.parse.urlencode(query_params)

        req = urllib.request.Request(url, method=meta["method"])
        req.add_header("Content-Type", "application/json")

        resp = urllib.request.urlopen(req, timeout=60)
        data = json.loads(resp.read().decode())

        return {"status": "ok", "result": data}

    except Exception as e:
        return {"status": "error", "error_message": f"{str(e)}\n{traceback.format_exc()}"}

def search_agent_archival(target_agent_id: str, query: str, search_mode: Optional[str] = None, limit: Optional[int] = None) -> Dict[str, Any]:
    """
    Search another agent's archival memory. Returns passages matching the query.

    Use this to access knowledge stored in other agents' archives. Key archives:
      - docs-and-transcripts agent (agent-398b4f6c-6afa-493f-8063-897c6b171a0d): Meeting notes and transcripts. Passages tagged with date:YYYY-MM, participant:name, type:1on1/small-group/team, id:meeting-uuid.
      - tasks agent (agent-dd15479e-6543-400e-8463-b2a48b13cd4a): Extracted task source references.
      - pulse agent (agent-2ed14ef4-6289-453a-ae27-290b6ed196b8): Slack monitoring observations.

    Args:
        target_agent_id: The agent whose archival memory to search. Use the full agent ID.
        query: Search query. Use "schema" to get the archive's self-description with tag vocabulary, passage format, and example queries. For semantic mode use natural language like "budget discussion". For text mode use exact substrings or tag patterns like "date:2025-04" or "id:f2d5b455" or "participant:leslie".
        search_mode: How to search. "semantic" for meaning match. "text" for exact substring (good for dates, IDs, names, tags). "auto" tries semantic first then text fallback. Default "auto".
        limit: Max results to return. Default 10, max 100.

    Returns:
        Dictionary with matching passages including text, tags, and metadata.
    """
    import json
    import os
    import traceback
    import urllib.request
    import urllib.error

    try:
        LETTA_BASE = os.environ.get("LETTA_BASE_URL", "http://localhost:8283")

        if not target_agent_id or not query:
            return {"status": "error", "error_message": "target_agent_id and query are required"}

        mode = (search_mode or "auto").lower()
        if mode not in ("semantic", "text", "auto"):
            return {"status": "error", "error_message": "search_mode must be semantic, text, or auto"}

        search_limit = min(limit or 10, 100)
        base_url = f"{LETTA_BASE}/v1/agents/{target_agent_id}/archival-memory"

        # Schema query — return the archive's self-description
        if query.strip().lower() == "schema":
            mode = "text"
            query = "ARCHIVE SCHEMA:"
            search_limit = 1

        quoted = urllib.request.quote(query)

        # Build URL based on mode
        if mode == "text":
            urls_to_try = [f"{base_url}?search={quoted}&limit={search_limit}"]
        elif mode == "semantic":
            urls_to_try = [f"{base_url}?query={quoted}&limit={search_limit}"]
        else:
            urls_to_try = [
                f"{base_url}?query={quoted}&limit={search_limit}",
                f"{base_url}?search={quoted}&limit={search_limit}",
            ]

        passages = []
        used_mode = mode

        for url_idx, fetch_url in enumerate(urls_to_try):
            for attempt in range(3):
                req = urllib.request.Request(fetch_url, method="GET")
                try:
                    with urllib.request.urlopen(req, timeout=15) as resp:
                        data = json.loads(resp.read().decode("utf-8"))
                    break
                except urllib.error.HTTPError as he:
                    if he.code in (301, 302, 307, 308):
                        fetch_url = he.headers.get("Location", "")
                        continue
                    raise
            else:
                data = []

            if isinstance(data, list):
                for p in data:
                    passages.append({
                        "text": p.get("text", "")[:2000],
                        "tags": p.get("tags", []),
                        "archive_id": p.get("archive_id", ""),
                        "id": p.get("id", ""),
                    })

            if passages:
                used_mode = "semantic" if url_idx == 0 and mode == "auto" else mode
                break
            elif mode == "auto" and url_idx == 0:
                used_mode = "text_fallback"

        return {
            "status": "ok",
            "count": len(passages),
            "search_mode": used_mode,
            "target_agent_id": target_agent_id,
            "query": query,
            "passages": passages,
        }

    except Exception as e:
        return {"status": "error", "error_message": f"{str(e)}\n{traceback.format_exc()}"}

def explore_document_entities(
    file_id: str,
) -> Dict[str, Any]:
    """
    Show all entities and relationships extracted from a document.

    Use this tool to understand what entities (people, organizations,
    projects, topics) were identified in a document and how they
    relate to each other.

    Args:
        file_id: Google Drive file ID or URL of the document to explore.
                 Accepts URLs like https://docs.google.com/document/d/FILE_ID/edit

    Returns:
        Dictionary with entities found in the document and their
        relationships to other entities.
    """
    import os
    import re
    import traceback
    import requests

    try:
        # Parse URL to file ID if needed (inline - Letta can't access module-level helpers)
        file_id = file_id.strip()
        match = re.search(r"/d/([a-zA-Z0-9_-]+)", file_id)
        if match:
            file_id = match.group(1)
        else:
            match = re.search(r"[?&]id=([a-zA-Z0-9_-]+)", file_id)
            if match:
                file_id = match.group(1)

        # Get service URL from environment or use default
        base_url = os.environ.get("DRIVE_RAG_SERVICE_URL", "http://drive-rag-service:8000")

        # Make request
        response = requests.get(
            f"{base_url}/v1/entities/document/{file_id}",
            timeout=60,
        )

        if response.status_code == 404:
            return {
                "status": "error",
                "error_message": f"Document {file_id} not found or has no extracted entities",
            }

        if response.status_code != 200:
            return {
                "status": "error",
                "error_message": f"Failed to get document entities: {response.text}",
            }

        data = response.json()

        if data.get("status") == "error":
            return {
                "status": "error",
                "error_message": data.get("error", "Unknown error"),
            }

        return {
            "status": "ok",
            "file_id": file_id,
            "entities": data.get("entities", {}),
            "relationships": data.get("relationships", {}),
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

