def get_drive_file_info(drive_url: str) -> str:
    """
    Get document or folder title and metadata from a Google Drive URL.

    Extracts the file ID from a Google Drive URL and retrieves file/folder information
    including title, owner, creation date, modification date, sharing status, etc.
    Works for both files and folders.

    Args:
        drive_url: Google Drive URL in any format:
                   - https://docs.google.com/document/d/FILE_ID/edit
                   - https://drive.google.com/file/d/FILE_ID/view
                   - https://drive.google.com/drive/folders/FILE_ID
                   - https://drive.google.com/open?id=FILE_ID
                   - etc.

    Returns:
        str: JSON string with file/folder metadata or error message

    Example:
        get_drive_file_info("https://docs.google.com/document/d/1abc123xyz/edit")
        # Returns: {"title": "Document Name", "owner": "user@example.com", ...}

        get_drive_file_info("https://drive.google.com/drive/folders/1abc123xyz")
        # Returns: {"title": "Folder Name", "mime_type": "application/vnd.google-apps.folder", ...}
    """
    import re
    import subprocess
    import json
    from datetime import datetime

    try:
        # Extract file ID from various Google Drive URL formats
        file_id = None

        # Pattern 1: /folders/FILE_ID (for folder URLs)
        match = re.search(r'/folders/([a-zA-Z0-9_-]+)', drive_url)
        if match:
            file_id = match.group(1)

        # Pattern 2: /d/FILE_ID/ or /file/d/FILE_ID/ (for file/document URLs)
        if not file_id:
            match = re.search(r'/d/([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 3: ?id=FILE_ID
        if not file_id:
            match = re.search(r'[?&]id=([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 4: FILE_ID directly (if URL is just the ID)
        if not file_id:
            if re.match(r'^[a-zA-Z0-9_-]+$', drive_url):
                file_id = drive_url

        if not file_id:
            return json.dumps({
                "error": "Could not extract file ID from URL",
                "url": drive_url,
                "message": "Please provide a valid Google Drive URL (e.g., https://docs.google.com/document/d/FILE_ID/edit)"
            }, indent=2)

        # Query Drive API via gws CLI
        _cmd = ["gws"] + "drive files get".split()
        _cmd.extend(["--params", json.dumps({
            "fileId": file_id,
            "fields": "id,name,mimeType,createdTime,modifiedTime,owners,shared,webViewLink,webContentLink,size,permissions,capabilities,description,starred,trashed",
            "supportsAllDrives": True,
        })])
        _cmd.extend(["--format", "json"])
        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)

        if _r.returncode != 0:
            _err = _r.stderr or ""
            if "404" in _err or "notFound" in _err:
                return json.dumps({
                    "error": "File not found",
                    "file_id": file_id,
                    "message": "The file does not exist or has been deleted. You may not have access to this file."
                }, indent=2)
            elif "403" in _err or "forbidden" in _err.lower():
                return json.dumps({
                    "error": "Access denied",
                    "file_id": file_id,
                    "message": "You do not have permission to access this file. The file may not be shared with you."
                }, indent=2)
            else:
                return json.dumps({
                    "error": f"Drive API error",
                    "file_id": file_id,
                    "message": _err[:500] if _err else f"gws exit {_r.returncode}"
                }, indent=2)

        file = json.loads(_r.stdout) if _r.stdout.strip() else {}

        # Format response
        owners = file.get("owners", [])
        owner_emails = [owner.get("emailAddress", "unknown") for owner in owners]
        owner_names = [owner.get("displayName", "unknown") for owner in owners]

        mime_type = file.get("mimeType", "unknown")
        is_folder = mime_type == "application/vnd.google-apps.folder"

        result = {
            "success": True,
            "file_id": file.get("id"),
            "title": file.get("name", "(untitled)"),
            "mime_type": mime_type,
            "is_folder": is_folder,
            "created_time": file.get("createdTime"),
            "modified_time": file.get("modifiedTime"),
            "owners": owner_emails,
            "owner_names": owner_names,
            "shared": file.get("shared", False),
            "web_view_link": file.get("webViewLink", ""),
            "web_content_link": file.get("webContentLink", ""),
            "size_bytes": file.get("size"),
            "description": file.get("description", ""),
            "starred": file.get("starred", False),
            "trashed": file.get("trashed", False),
            "capabilities": file.get("capabilities", {}),
        }

        # Format dates for readability
        if result["created_time"]:
            try:
                created_dt = datetime.fromisoformat(result["created_time"].replace('Z', '+00:00'))
                result["created_date"] = created_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        if result["modified_time"]:
            try:
                modified_dt = datetime.fromisoformat(result["modified_time"].replace('Z', '+00:00'))
                result["modified_date"] = modified_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        # Format size
        if result["size_bytes"]:
            size = int(result["size_bytes"])
            if size < 1024:
                result["size"] = f"{size} bytes"
            elif size < 1024 * 1024:
                result["size"] = f"{size / 1024:.1f} KB"
            else:
                result["size"] = f"{size / (1024 * 1024):.1f} MB"

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error processing URL: {str(e)}",
            "url": drive_url
        }, indent=2)

def list_participants() -> Dict[str, Any]:
    """
    List all known participants from meeting transcripts.

    Use this to discover available participant names for filtering.
    Returns a list of participant tags sorted by frequency.

    Args:
        None

    Returns:
        Dictionary with list of participants and their meeting counts.
    """
    import os
    import requests
    import traceback
    from collections import Counter

    try:
        letta_base_url = os.environ.get("LETTA_BASE_URL", "http://localhost:8283")
        agent_id = os.environ.get("GRANOLA_AGENT_ID", "agent-398b4f6c-6afa-493f-8063-897c6b171a0d")

        url = f"{letta_base_url}/v1/agents/{agent_id}/archival-memory"
        response = requests.get(url, params={"limit": 500}, timeout=30)
        response.raise_for_status()

        passages = response.json()

        participant_counts = Counter()
        org_counts = Counter()
        date_counts = Counter()

        for passage in passages:
            for tag in passage.get("tags", []):
                if tag.startswith("participant:"):
                    participant_counts[tag] += 1
                elif tag.startswith("org:"):
                    org_counts[tag] += 1
                elif tag.startswith("date:"):
                    date_counts[tag] += 1

        return {
            "status": "ok",
            "participants": [
                {"name": p.replace("participant:", ""), "count": c}
                for p, c in participant_counts.most_common(50)
            ],
            "organizations": [
                {"name": o.replace("org:", ""), "count": c}
                for o, c in org_counts.most_common(20)
            ],
            "date_months": [
                {"month": d.replace("date:", ""), "count": c}
                for d, c in sorted(date_counts.items(), reverse=True)
            ]
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to list participants: {str(e)}\n{traceback.format_exc()}"
        }

def get_document_events(doc_ids: List[str], days: int = 7) -> Dict[str, Any]:
    """
    Get individual events (timeline) for specific documents.

    Returns a detailed timeline of who did what and when on specific documents.
    Use this for audit trails or understanding the sequence of activity.
    For aggregated counts, use search_drive_activity instead.

    Args:
        doc_ids: List of document IDs to query
        days: Number of days to look back (default: 7)

    Returns:
        Dict with events list (time, actor, action) and summary counts per document

    Example:
        # Get timeline for a specific document
        get_document_events(doc_ids=["1abc...xyz"])
        # Returns: {"status": "ok", "data": {"documents": [{"doc_id": "...", "events": [...]}]}}
    """
    # Imports inside function (Letta compliance)
    import subprocess
    import json
    import time
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60

    try:
        # Calculate date range
        end_date = datetime.now()
        start_date_dt = end_date - timedelta(days=days)

        start_time = start_date_dt.strftime("%Y-%m-%dT00:00:00Z")
        end_time = end_date.strftime("%Y-%m-%dT23:59:59Z")

        # Query Admin Reports API via gws CLI with pagination
        activities = []
        next_page_token = None
        MAX_PAGES = 15
        pages_fetched = 0

        while pages_fetched < MAX_PAGES:
            _params = {
                "userKey": "all",
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}"
                }
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            activities.extend(_data.get("items", []))
            pages_fetched += 1
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        # Filter activities for specified documents
        doc_activities = {}
        doc_id_set = set(doc_ids)

        for doc_id in doc_ids:
            doc_activities[doc_id] = {
                "doc_id": doc_id,
                "events": [],
                "summary": {
                    "edit_count": 0,
                    "view_count": 0,
                    "share_count": 0,
                    "comment_count": 0,
                },
            }

        for activity in activities:
            for event in activity.get("events", []):
                for param in event.get("parameters", []):
                    if param.get("name") == "doc_id":
                        doc_id = param.get("value")
                        if doc_id in doc_id_set:
                            event_name = event.get("name", "unknown")
                            doc_activities[doc_id]["events"].append({
                                "time": activity.get("id", {}).get("time"),
                                "actor": activity.get("actor", {}).get("email", "(unknown)"),
                                "action": event_name,
                            })

                            if event_name == "edit":
                                doc_activities[doc_id]["summary"]["edit_count"] += 1
                            elif event_name == "view":
                                doc_activities[doc_id]["summary"]["view_count"] += 1
                            elif event_name in ["change_user_access", "change_acl_editors"]:
                                doc_activities[doc_id]["summary"]["share_count"] += 1
                            elif event_name in ["create_comment", "resolve_comment"]:
                                doc_activities[doc_id]["summary"]["comment_count"] += 1

        # Sort events by time for each document
        for doc in doc_activities.values():
            doc["events"].sort(key=lambda x: x["time"] or "", reverse=True)

        return {
            "status": "ok",
            "data": {
                "documents": list(doc_activities.values()),
                "period_days": days,
                "truncated": pages_fetched >= MAX_PAGES,
            }
        }

    except Exception as e:
        import traceback
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error getting document events: {str(e)}\n{traceback.format_exc()}"
        }

def process_drive_task_queue(max_entries: int = 10) -> Dict[str, Any]:
    """
    Process queued drive comment tasks and extract them.

    Reads the queued_tasks_from_drive memory block. For each raw entry:
    1. Calls Drive API to get file metadata (type, title)
    2. Calls Drive API to get comment metadata (author, text, quoted passage)
    3. Retrieves surrounding context based on document type
    4. Replaces the raw entry in the block with an enriched version

    After this tool returns, review the [enriched] entries in the
    queued_tasks_from_drive block and extract tasks using
    add_extracted_tasks. Then remove the processed entries from the block.

    For entries with marker_type "explicit", the task_hint IS the task
    description - use it directly. For "pointer" markers, expand the hint
    using the comment and document context. For entries without markers,
    compose a task from the comment text.

    Args:
        max_entries: Maximum entries to process per call (1-20, default 10).

    Returns:
        Dictionary with status, count processed, and per-entry details.
    """
    import os
    import re
    import json
    import subprocess
    import traceback
    import pytz
    import urllib.request
    import urllib.error

    try:
        LETTA_BASE = os.getenv("LETTA_BASE_URL", "http://localhost:8283")
        AGENT_ID = os.getenv("LETTA_AGENT_ID")
        QUEUE_BLOCK_LABEL = "queued_tasks_from_drive"
        OWNER_EMAIL = "cdorsey@concord.org"
        GWS_TIMEOUT = 15

        if max_entries is None or max_entries < 1:
            max_entries = 10
        if max_entries > 20:
            max_entries = 20

        # ── Get queue block ──
        if not AGENT_ID:
            return {"status": "error", "error_message": "LETTA_AGENT_ID not set"}

        agent_url = f"{LETTA_BASE}/v1/agents/{AGENT_ID}"
        agent_req = urllib.request.Request(agent_url, method="GET")
        with urllib.request.urlopen(agent_req, timeout=10) as resp:
            agent_data = json.loads(resp.read().decode("utf-8"))

        blocks = agent_data.get("memory", {}).get("blocks", [])
        queue_block = None
        for block in blocks:
            if block.get("label") == QUEUE_BLOCK_LABEL:
                queue_block = block
                break

        if not queue_block:
            return {
                "status": "error",
                "error_message": f"Block '{QUEUE_BLOCK_LABEL}' not found on this agent.",
            }

        queue_block_id = queue_block["id"]
        block_value = queue_block.get("value", "")

        # ── Parse entries ──
        raw_entries = [e.strip() for e in block_value.split("---") if e.strip()]
        entries = [
            e for e in raw_entries
            if e and not e.startswith("#") and "comment_id:" in e
        ]

        if not entries:
            return {
                "status": "ok",
                "message": "No entries to process.",
                "processed": 0,
                "details": [],
            }

        entries = entries[:max_entries]
        processed = []
        errors = []

        for entry_text in entries:
            try:
                # Parse entry fields
                fields = {}
                for line in entry_text.split("\n"):
                    line = line.strip()
                    if not line:
                        continue
                    if line.startswith("[queued:"):
                        # Parse header line for comment_id and doc_id
                        m = re.search(r"comment_id:\s*(\S+)", line)
                        if m:
                            fields["comment_id"] = m.group(1)
                        m = re.search(r"doc_id:\s*(\S+)", line)
                        if m:
                            fields["doc_id"] = m.group(1)
                        continue
                    if line.startswith("[FROM:"):
                        continue  # Skip foreign trigger annotation line
                    if ":" in line:
                        key, _, val = line.partition(":")
                        fields[key.strip()] = val.strip()

                doc_id = fields.get("doc_id", "")
                comment_id = fields.get("comment_id", "")
                marker_type = fields.get("marker_type")
                task_hint = fields.get("task_hint")
                context = fields.get("context")
                notes = fields.get("notes")
                triggered_by = fields.get("triggered_by", "")

                if not doc_id:
                    errors.append({"entry": entry_text[:50], "error": "no doc_id"})
                    continue

                # ── Drive API: file metadata ──
                try:
                    _cmd = ["gws"] + "drive files get".split()
                    _cmd.extend(["--params", json.dumps({
                        "fileId": doc_id,
                        "fields": "id,name,mimeType,webViewLink",
                    })])
                    _cmd.extend(["--format", "json"])
                    _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
                    if _r.returncode != 0:
                        raise RuntimeError(_r.stderr[:500] if _r.stderr else f"gws exit {_r.returncode}")
                    file_meta = json.loads(_r.stdout) if _r.stdout.strip() else {}
                except Exception as api_err:
                    errors.append({
                        "doc_id": doc_id,
                        "error": f"files.get failed: {str(api_err)}",
                    })
                    continue

                doc_title = file_meta.get("name", fields.get("doc_title", ""))
                mime_type = file_meta.get("mimeType", "")

                # Map mime type to doc_type
                mime_to_type = {
                    "application/vnd.google-apps.document": "document",
                    "application/vnd.google-apps.spreadsheet": "spreadsheet",
                    "application/vnd.google-apps.presentation": "presentation",
                }
                doc_type = mime_to_type.get(mime_type, "document")

                # ── Drive API: comment metadata ──
                comment_text = ""
                comment_author = ""
                comment_author_email = ""
                quoted_passage = ""
                comment_date = ""

                if comment_id:
                    try:
                        _cmd = ["gws"] + "drive comments get".split()
                        _cmd.extend(["--params", json.dumps({
                            "fileId": doc_id,
                            "commentId": comment_id,
                            "fields": "content,author,quotedFileContent,createdTime,resolved",
                        })])
                        _cmd.extend(["--format", "json"])
                        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
                        if _r.returncode != 0:
                            raise RuntimeError(_r.stderr[:500] if _r.stderr else f"gws exit {_r.returncode}")
                        comment_data = json.loads(_r.stdout) if _r.stdout.strip() else {}
                        comment_text = comment_data.get("content", "")
                        author = comment_data.get("author", {})
                        comment_author = author.get("displayName", "")
                        comment_author_email = author.get("emailAddress", "")
                        quoted_fc = comment_data.get("quotedFileContent", {})
                        quoted_passage = quoted_fc.get("value", "")
                        comment_date = comment_data.get("createdTime", "")
                    except Exception:
                        pass  # Enrichment is best-effort

                # ── Surrounding context (by doc type) ──
                surrounding_context = ""
                if quoted_passage and doc_type == "document":
                    try:
                        _cmd = ["gws"] + "docs documents get".split()
                        _cmd.extend(["--params", json.dumps({
                            "documentId": doc_id,
                        })])
                        _cmd.extend(["--format", "json"])
                        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
                        if _r.returncode != 0:
                            raise RuntimeError(_r.stderr[:500] if _r.stderr else f"gws exit {_r.returncode}")
                        doc_data = json.loads(_r.stdout) if _r.stdout.strip() else {}
                        body_content = doc_data.get("body", {}).get("content", [])
                        paragraphs = []
                        for element in body_content:
                            paragraph = element.get("paragraph", {})
                            if paragraph:
                                text_runs = paragraph.get("elements", [])
                                para_text = "".join(
                                    tr.get("textRun", {}).get("content", "")
                                    for tr in text_runs
                                )
                                if para_text.strip():
                                    paragraphs.append(para_text.strip())

                        # Find paragraph containing quoted passage
                        target_idx = None
                        for idx, p in enumerate(paragraphs):
                            if quoted_passage in p:
                                target_idx = idx
                                break
                        if target_idx is not None:
                            start = max(0, target_idx - 3)
                            end = min(len(paragraphs), target_idx + 4)
                            context_paras = paragraphs[start:end]
                            marked = []
                            for p in context_paras:
                                if quoted_passage in p:
                                    marked.append(f">> {p} <<")
                                else:
                                    marked.append(p)
                            surrounding_context = "\n".join(marked)
                    except Exception:
                        pass  # Context retrieval is best-effort

                elif quoted_passage and doc_type == "spreadsheet":
                    try:
                        _cmd = ["gws"] + "sheets spreadsheets get".split()
                        _cmd.extend(["--params", json.dumps({
                            "spreadsheetId": doc_id,
                            "fields": "sheets.data.rowData.values.formattedValue",
                        })])
                        _cmd.extend(["--format", "json"])
                        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
                        if _r.returncode != 0:
                            raise RuntimeError(_r.stderr[:500] if _r.stderr else f"gws exit {_r.returncode}")
                        sheet_data = json.loads(_r.stdout) if _r.stdout.strip() else {}
                        all_cells = []
                        for sheet in sheet_data.get("sheets", []):
                            for grid_data in sheet.get("data", []):
                                for row in grid_data.get("rowData", []):
                                    row_vals = []
                                    for cell in row.get("values", []):
                                        row_vals.append(
                                            cell.get("formattedValue", "")
                                        )
                                    if any(row_vals):
                                        all_cells.append(" | ".join(row_vals))
                        for idx, row_text in enumerate(all_cells):
                            if quoted_passage in row_text:
                                start = max(0, idx - 2)
                                end = min(len(all_cells), idx + 3)
                                surrounding_context = "\n".join(all_cells[start:end])
                                break
                    except Exception:
                        pass

                elif quoted_passage and doc_type == "presentation":
                    try:
                        _cmd = ["gws"] + "slides presentations get".split()
                        _cmd.extend(["--params", json.dumps({
                            "presentationId": doc_id,
                            "fields": "slides.pageElements.shape.text.textElements.textRun.content",
                        })])
                        _cmd.extend(["--format", "json"])
                        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
                        if _r.returncode != 0:
                            raise RuntimeError(_r.stderr[:500] if _r.stderr else f"gws exit {_r.returncode}")
                        pres_data = json.loads(_r.stdout) if _r.stdout.strip() else {}
                        for slide in pres_data.get("slides", []):
                            slide_text_parts = []
                            for element in slide.get("pageElements", []):
                                shape = element.get("shape", {})
                                text_obj = shape.get("text", {})
                                for te in text_obj.get("textElements", []):
                                    tr = te.get("textRun", {})
                                    content = tr.get("content", "")
                                    if content.strip():
                                        slide_text_parts.append(content.strip())
                            slide_text = "\n".join(slide_text_parts)
                            if quoted_passage in slide_text:
                                surrounding_context = slide_text
                                break
                    except Exception:
                        pass

                # ── Build doc link ──
                type_slug = {
                    "document": "document",
                    "spreadsheet": "spreadsheets",
                    "presentation": "presentation",
                }.get(doc_type, "document")
                doc_link = f"https://docs.google.com/{type_slug}/d/{doc_id}/edit"
                if comment_id:
                    doc_link += f"?disco={comment_id}"

                # ── Determine from_person ──
                from_person = comment_author
                if comment_author_email:
                    from_person = f"{comment_author} ({comment_author_email})"
                if not from_person:
                    from_person = triggered_by

                # ── Build enriched entry for block ──
                tz = pytz.timezone("America/New_York")
                from datetime import datetime
                enrich_ts = datetime.now(tz).strftime("%Y-%m-%d %H:%M")
                enriched_lines = [
                    (
                        f"[enriched: {enrich_ts}] "
                        f"comment_id: {comment_id} "
                        f"| doc_id: {doc_id}"
                    ),
                    f"doc_title: {doc_title}",
                    f"doc_type: {doc_type}",
                    f"doc_link: {doc_link}",
                    f"comment_author: {from_person}",
                ]
                if triggered_by:
                    enriched_lines.append(f"triggered_by: {triggered_by}")
                if triggered_by and triggered_by.lower() != OWNER_EMAIL.lower():
                    enriched_lines.append(f"[FROM: {triggered_by}]")
                if comment_date:
                    enriched_lines.append(f"comment_date: {comment_date}")
                if comment_text:
                    enriched_lines.append(f"comment_text: {comment_text[:300]}")
                if quoted_passage:
                    enriched_lines.append(f"quoted_passage: {quoted_passage[:200]}")
                if surrounding_context:
                    enriched_lines.append(
                        f"surrounding_context: {surrounding_context[:500]}"
                    )
                if marker_type:
                    enriched_lines.append(f"marker_type: {marker_type}")
                if task_hint:
                    enriched_lines.append(f"task_hint: {task_hint}")
                if context:
                    enriched_lines.append(f"context: {context}")
                if notes and not marker_type:
                    enriched_lines.append(f"notes: {notes}")
                raw_urls = fields.get("urls", "")
                if raw_urls:
                    enriched_lines.append(f"urls: {raw_urls}")
                enriched_lines.append("trigger: docs-comment-action-item")

                processed.append({
                    "doc_id": doc_id,
                    "comment_id": comment_id,
                    "doc_title": doc_title,
                    "marker_type": marker_type,
                    "enriched_entry": "\n".join(enriched_lines),
                })

            except Exception as entry_err:
                errors.append({
                    "entry": entry_text[:80],
                    "error": str(entry_err),
                })

        # ── Replace raw entries with enriched versions in block ──
        if processed:
            block_url = f"{LETTA_BASE}/v1/blocks/{queue_block_id}"
            block_req = urllib.request.Request(block_url, method="GET")
            with urllib.request.urlopen(block_req, timeout=10) as resp:
                block_data = json.loads(resp.read().decode("utf-8"))
            current_value = block_data.get("value", "")

            # Build lookup of enriched replacements
            enriched_lookup = {}
            for p in processed:
                key = (p["doc_id"], p["comment_id"])
                enriched_lookup[key] = p["enriched_entry"]

            new_parts = []
            for part in current_value.split("---"):
                part_stripped = part.strip()
                if not part_stripped:
                    continue
                replaced = False
                for (did, cid), enriched in enriched_lookup.items():
                    if (
                        did in part_stripped
                        and (not cid or cid in part_stripped)
                        and "[enriched:" not in part_stripped
                    ):
                        new_parts.append(enriched)
                        replaced = True
                        break
                if not replaced:
                    new_parts.append(part_stripped)

            if new_parts:
                new_value = "\n---\n".join(new_parts) + "\n---"
            else:
                new_value = ""

            update_data = json.dumps({"value": new_value}).encode("utf-8")
            update_req = urllib.request.Request(
                block_url,
                data=update_data,
                headers={"Content-Type": "application/json"},
                method="PATCH",
            )
            urllib.request.urlopen(update_req, timeout=10)

        result = {
            "status": "ok",
            "message": f"Enriched {len(processed)} entry(s). Review enriched entries in queued_tasks_from_drive and extract tasks using add_extracted_tasks, then remove processed entries from the block.",
            "processed": len(processed),
            "details": [
                {
                    "doc_title": p["doc_title"],
                    "marker_type": p["marker_type"],
                }
                for p in processed
            ],
        }
        if errors:
            result["errors"] = errors

        return result

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

