def collect_daily_personal_activity(date: Optional[str] = None) -> str:
    """
    Collect your personal Drive activity for a specific date.

    Queries Drive API for files you own or have access to, then queries
    Drive Activity API for activity on those files. Detects activity patterns.

    Args:
        date: Date in YYYY-MM-DD format. If provided, queries exactly that date
              (including weekends). If not provided, defaults to last workday.

    Returns:
        str: JSON string containing your personal activity data with patterns
    """
    import subprocess
    import json
    import time
    import os
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60
    MY_EMAIL = os.getenv("MY_EMAIL", "cdorsey@concord.org")

    try:
        # Determine target date
        if date:
            # User provided a specific date - use it exactly as requested
            target_date = datetime.strptime(date, "%Y-%m-%d")
            date_str = target_date.strftime("%Y-%m-%d")
        else:
            # No date provided - default to last workday (inline)
            target_date = datetime.now() - timedelta(days=1)
            while target_date.weekday() >= 5:
                target_date -= timedelta(days=1)
            date_str = target_date.strftime("%Y-%m-%d")

        # Use Admin Reports API filtered by your email - much faster than querying all files
        start_time = f"{date_str}T00:00:00Z"
        end_time = f"{date_str}T23:59:59Z"

        # Query Admin Reports API via gws CLI with pagination
        all_activities = []
        next_page_token = None

        while True:
            _params = {
                "userKey": MY_EMAIL,
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return json.dumps({
                    "error": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}",
                    "type": "error"
                })
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            all_activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        activities = all_activities

        # Analyze your activity
        my_documents = {}
        total_edits = 0
        total_views = 0
        doc_ids_to_fetch = set()

        for activity in activities:
            for event in activity.get("events", []):
                event_name = event.get("name", "unknown")

                doc_id = None
                doc_title = "(untitled)"
                owner = None

                for param in event.get("parameters", []):
                    param_name = param.get("name")
                    param_value = param.get("value")

                    if param_name == "doc_id":
                        doc_id = param_value
                    elif param_name == "doc_title":
                        doc_title = param_value
                    elif param_name == "owner":
                        owner = param_value

                if doc_id:
                    if doc_id not in my_documents:
                        my_documents[doc_id] = {
                            "doc_id": doc_id,
                            "title": doc_title,
                            "owner": owner,
                            "link": "",
                            "edit_count": 0,
                            "view_count": 0,
                            "total_engagement": 0,
                        }
                        doc_ids_to_fetch.add(doc_id)

                    if event_name == "edit":
                        my_documents[doc_id]["edit_count"] += 1
                        total_edits += 1
                    elif event_name == "view":
                        my_documents[doc_id]["view_count"] += 1
                        total_views += 1

                    my_documents[doc_id]["total_engagement"] = (
                        my_documents[doc_id]["edit_count"] + my_documents[doc_id]["view_count"]
                    )

        # Only fetch links for top 50 documents
        top_doc_ids = sorted(
            doc_ids_to_fetch,
            key=lambda x: my_documents[x]["total_engagement"],
            reverse=True
        )[:50]

        # Fetch links and check accessibility via gws
        for doc_id in top_doc_ids:
            _cmd = ["gws"] + "drive files get".split()
            _cmd.extend(["--params", json.dumps({
                "fileId": doc_id,
                "fields": "id,name,webViewLink,shared,capabilities",
                "supportsAllDrives": True,
            })])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)
            if _r.returncode != 0:
                _err = _r.stderr or ""
                if "404" in _err or "notFound" in _err:
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                    my_documents[doc_id]["access_error"] = "deleted"
                elif "403" in _err or "forbidden" in _err.lower():
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                    my_documents[doc_id]["access_error"] = "no_access"
                else:
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                continue
            try:
                file = json.loads(_r.stdout) if _r.stdout.strip() else {}
            except Exception:
                my_documents[doc_id]["is_accessible"] = False
                my_documents[doc_id]["link"] = ""
                continue
            if file:
                my_documents[doc_id]["link"] = file.get("webViewLink", "")
                my_documents[doc_id]["is_accessible"] = True
                my_documents[doc_id]["is_shared"] = file.get("shared", False)
                if file.get("name") and not my_documents[doc_id]["title"]:
                    my_documents[doc_id]["title"] = file.get("name")

        # Sort by engagement and format titles
        top_documents = sorted(
            my_documents.values(),
            key=lambda x: x["total_engagement"],
            reverse=True
        )[:20]

        # Format display titles based on accessibility
        for doc in top_documents:
            title = doc.get("title", "(untitled)")
            is_accessible = doc.get("is_accessible", False)
            access_error = doc.get("access_error", "")

            if not is_accessible:
                if access_error == "deleted":
                    doc["display_title"] = f"{title} - Deleted"
                elif access_error == "no_access":
                    doc["display_title"] = f"{title} - Not shared"
                else:
                    doc["display_title"] = f"{title} - Not accessible"
            else:
                doc["display_title"] = title

        result = {
            "type": "drive_analytics_personal",
            "date": date_str,
            "is_workday": True,
            "my_activity": {
                "total_activities": len(activities),
                "total_edits": total_edits,
                "total_views": total_views,
                "documents_engaged": len(my_documents),
                "top_documents": top_documents,
                "activity_patterns": {
                    "viewed_then_stopped": [],
                    "began_editing_recently": [],
                    "started_editing_then_stopped": [],
                    "view_most_regularly": [],
                    "multiple_views_per_day": [],
                },
            },
        }

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error collecting personal activity: {str(e)}",
            "type": "error"
        })

def get_email_analytics(
    start_datetime: str,
    end_datetime: str,
    mode: str = "org",
    quartile_pin_metric: Optional[str] = None,
    special_accounts: Optional[List[str]] = None,
    output_format: str = "json"
) -> Dict[str, Any]:
    """
    Get anonymized email analytics for the organization.

    Provides privacy-preserving email activity metrics. Users are identified
    by cryptographic hashes that rotate daily at 3:00 AM Eastern.

    Args:
        start_datetime: Start of period in ISO 8601 format (e.g., "2025-12-24T09:00:00-05:00")
        end_datetime: End of period in ISO 8601 format
        mode: Analysis mode - "org" (totals), "quartile" (grouped), "individual" (per-user)
        quartile_pin_metric: For quartile mode, pin groupings to one metric:
                            "sent", "received", "ratio", or "activity"
        special_accounts: Optional list of non-staff accounts to track separately
                         (e.g., ["support@concord.org"]). These are NOT anonymized.
        output_format: "json" (default) or "csv" (only for individual mode)

    Returns:
        Dict with:
        - status: "ok" or "error"
        - data: Analytics results based on mode
        - special_accounts: Non-anonymized stats for special accounts (if provided)

    Examples:
        # Org-wide totals for last week
        get_email_analytics(start_datetime="2025-12-17T00:00:00-05:00", 
                           end_datetime="2025-12-24T00:00:00-05:00", mode="org")

        # Quartile analysis pinned by send count
        get_email_analytics(..., mode="quartile", quartile_pin_metric="sent")

        # Individual anonymized stats
        get_email_analytics(..., mode="individual")
    """
    # Imports inside function (Letta compliance - must be fully self-contained)
    import json
    import hashlib
    import subprocess
    from datetime import datetime, timedelta, date
    import pytz

    # Configuration (inlined for Letta compliance)
    _HASH_SECRET_SALT = "cc-email-analytics-v1-2025-xK9mP2qR"
    CURRENT_STAFF = frozenset([
        "emcelroy@concord.org", "kswenson@concord.org", "scytacki@concord.org",
        "phorwitz@concord.org", "hlee@concord.org", "tlord@concord.org",
        "ddamelin@concord.org", "jraiff@concord.org", "cmcintyre@concord.org",
        "wfinzer@concord.org", "kbrown@concord.org", "lbondaryk@concord.org",
        "jchao@concord.org", "apallant@concord.org", "clore@concord.org",
        "kmiller@concord.org", "kjesseneller@concord.org", "rellis@concord.org",
        "tfristoe@concord.org", "lbuoncuore@concord.org", "dkehoe@concord.org",
        "sbrau@concord.org", "dmartin@concord.org", "lstephens@concord.org",
        "mtirenin@concord.org", "awagh@concord.org", "cdorsey@concord.org",
    ])

    try:
        # Validate mode
        if mode not in ["org", "quartile", "individual"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid mode '{mode}'. Must be 'org', 'quartile', or 'individual'."
            }

        # Validate quartile_pin_metric
        if quartile_pin_metric and quartile_pin_metric not in ["sent", "received", "ratio", "activity"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid quartile_pin_metric '{quartile_pin_metric}'. Must be 'sent', 'received', 'ratio', or 'activity'."
            }

        # Validate output_format
        if output_format not in ["json", "csv"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid output_format '{output_format}'. Must be 'json' or 'csv'."
            }

        if output_format == "csv" and mode != "individual":
            return {
                "status": "error",
                "data": {},
                "error_message": "CSV output is only available for 'individual' mode."
            }

        # Validate special accounts are not in staff list
        if special_accounts:
            staff_in_special = [a for a in special_accounts if a.lower() in CURRENT_STAFF]
            if staff_in_special:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Special accounts cannot include staff members: {staff_in_special}"
                }

        # Parse datetimes
        try:
            start_dt = datetime.fromisoformat(start_datetime)
            end_dt = datetime.fromisoformat(end_datetime)
        except ValueError as e:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid datetime format. Use ISO 8601 (e.g., '2025-12-24T09:00:00-05:00'). Error: {e}"
            }

        # Check 30-day limit
        if (end_dt - start_dt).days > 30:
            return {
                "status": "error",
                "data": {},
                "error_message": "Query period cannot exceed 30 days (API limitation)."
            }

        # Ensure minimum 5-minute interval
        if (end_dt - start_dt).total_seconds() < 300:
            return {
                "status": "error",
                "data": {},
                "error_message": "Query period must be at least 5 minutes."
            }

        # Get current hash date (changes at 3AM Eastern)
        eastern = pytz.timezone('US/Eastern')
        now_eastern = datetime.now(eastern)
        if now_eastern.hour < 3:
            hash_date = (now_eastern - timedelta(days=1)).date()
        else:
            hash_date = now_eastern.date()

        # Format times for API
        start_time = start_dt.strftime("%Y-%m-%dT%H:%M:%S.000Z") if start_dt.tzinfo is None else start_dt.astimezone(pytz.UTC).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        end_time = end_dt.strftime("%Y-%m-%dT%H:%M:%S.000Z") if end_dt.tzinfo is None else end_dt.astimezone(pytz.UTC).strftime("%Y-%m-%dT%H:%M:%S.000Z")

        # Query Admin Reports API for Gmail activity via gws CLI
        GWS_TIMEOUT = 60

        activities = []
        next_page_token = None
        MAX_PAGES = 50
        pages_fetched = 0

        while pages_fetched < MAX_PAGES:
            _params = {
                "userKey": "all",
                "applicationName": "gmail",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}"
                }

            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            pages_fetched += 1
            if not next_page_token:
                break

        # Process activities - count sent/received per user
        user_stats = {}  # email -> {"sent": 0, "received": 0}
        special_stats = {}  # email -> {"sent": 0, "received": 0}
        special_set = set(a.lower() for a in (special_accounts or []))

        for activity in activities:
            actor_email = activity.get("actor", {}).get("email", "").lower()

            for event in activity.get("events", []):
                event_name = event.get("name", "")

                # Extract mail event type from nested parameters
                # Structure: parameters[].messageValue.parameter[].intValue where name="mail_event_type"
                mail_event_type = None
                for param in event.get("parameters", []):
                    if param.get("name") == "event_info":
                        msg_value = param.get("messageValue", {})
                        for p in msg_value.get("parameter", []):
                            if p.get("name") == "mail_event_type":
                                mail_event_type = p.get("intValue")
                                break
                        break

                # Determine if sent or received (1=sent, 2=received)
                is_sent = mail_event_type == "1"
                is_received = mail_event_type == "2"

                if not (is_sent or is_received):
                    continue

                # Check if special account
                if actor_email in special_set:
                    if actor_email not in special_stats:
                        special_stats[actor_email] = {"sent": 0, "received": 0}
                    if is_sent:
                        special_stats[actor_email]["sent"] += 1
                    if is_received:
                        special_stats[actor_email]["received"] += 1
                    continue

                # Check if current staff
                if actor_email not in CURRENT_STAFF:
                    continue

                # Track stats
                if actor_email not in user_stats:
                    user_stats[actor_email] = {"sent": 0, "received": 0}

                if is_sent:
                    user_stats[actor_email]["sent"] += 1
                if is_received:
                    user_stats[actor_email]["received"] += 1

        # Calculate derived metrics for each user (inlined for Letta compliance)
        user_metrics = []
        for email, stats in user_stats.items():
            sent = stats["sent"]
            received = stats["received"]
            # Inline ratio calculation
            ratio = 9999999999.0 if received == 0 else round(sent / received, 4)
            # Inline hash calculation
            hash_data = f"{email.lower()}:{hash_date}:{_HASH_SECRET_SALT}"
            user_hash = hashlib.sha256(hash_data.encode()).hexdigest()[:8]
            user_metrics.append({
                "email": email,
                "hash": user_hash,
                "sent": sent,
                "received": received,
                "ratio": ratio,
                "activity": sent + received,
            })

        # Build response based on mode
        result = {
            "status": "ok",
            "data": {
                "period": {
                    "start": start_datetime,
                    "end": end_datetime,
                },
                "hash_date": str(hash_date),
                "truncated": pages_fetched >= MAX_PAGES,
            }
        }

        if mode == "org":
            # Aggregate totals
            total_sent = sum(u["sent"] for u in user_metrics)
            total_received = sum(u["received"] for u in user_metrics)
            org_ratio = 9999999999.0 if total_received == 0 else round(total_sent / total_received, 4)
            result["data"]["org_totals"] = {
                "sent": total_sent,
                "received": total_received,
                "ratio": org_ratio,
                "activity": total_sent + total_received,
            }
            result["data"]["user_count"] = len(user_metrics)

        elif mode == "quartile":
            # Quartile analysis (inlined for Letta compliance - no nested functions)
            n = len(user_metrics)
            if n == 0:
                result["data"]["quartiles"] = {}
                result["data"]["user_count"] = 0
            else:
                metrics_list = ["sent", "received", "ratio", "activity"]

                # Calculate quartile boundaries
                q_size = n // 4
                remainder = n % 4
                q_boundaries = []
                start_idx = 0
                for i in range(4):
                    size = q_size + (1 if i < remainder else 0)
                    q_boundaries.append((start_idx, start_idx + size))
                    start_idx += size

                if quartile_pin_metric:
                    # Pinned mode - one grouping, all metrics
                    sorted_users = sorted(
                        user_metrics,
                        key=lambda x: (-x[quartile_pin_metric], x["hash"])
                    )

                    result["data"]["pinned_by"] = quartile_pin_metric
                    result["data"]["quartiles"] = {}

                    for i, (start, end) in enumerate(q_boundaries):
                        q_name = f"Q{i+1}"
                        q_users = sorted_users[start:end]
                        n_users = len(q_users)

                        q_stats = {"user_count": n_users}
                        for m in metrics_list:
                            if n_users == 0:
                                if m == "ratio":
                                    q_stats[m] = {"avg": 0}
                                else:
                                    q_stats[m] = {"count": 0, "avg": 0}
                            else:
                                values = [u[m] for u in q_users]
                                total = sum(values)
                                avg = round(total / n_users, 2)
                                if m == "ratio":
                                    q_stats[m] = {"avg": avg}
                                else:
                                    q_stats[m] = {"count": total, "avg": avg}

                        result["data"]["quartiles"][q_name] = q_stats
                else:
                    # Default mode - each metric has its own grouping
                    result["data"]["quartiles"] = {}

                    for metric in metrics_list:
                        sorted_users = sorted(
                            user_metrics,
                            key=lambda x: (-x[metric], x["hash"])
                        )

                        result["data"]["quartiles"][f"by_{metric}"] = {}

                        for i, (start, end) in enumerate(q_boundaries):
                            q_name = f"Q{i+1}"
                            q_users = sorted_users[start:end]
                            n_users = len(q_users)

                            if n_users == 0:
                                if metric == "ratio":
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": 0, "avg": 0}
                                else:
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": 0, "count": 0, "avg": 0}
                            else:
                                values = [u[metric] for u in q_users]
                                total = sum(values)
                                avg = round(total / n_users, 2)
                                if metric == "ratio":
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": n_users, "avg": avg}
                                else:
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": n_users, "count": total, "avg": avg}

                result["data"]["user_count"] = n

        elif mode == "individual":
            # Individual anonymized stats
            # Sort by hash for consistent ordering
            sorted_users = sorted(user_metrics, key=lambda x: x["hash"])

            if output_format == "csv":
                # Build CSV string
                csv_lines = ["hash,sent,received,ratio,activity"]
                for u in sorted_users:
                    csv_lines.append(f"{u['hash']},{u['sent']},{u['received']},{u['ratio']},{u['activity']}")
                result["data"]["csv"] = "\n".join(csv_lines)
            else:
                # JSON format - remove email, keep only hash
                result["data"]["users"] = [
                    {
                        "hash": u["hash"],
                        "sent": u["sent"],
                        "received": u["received"],
                        "ratio": u["ratio"],
                        "activity": u["activity"],
                    }
                    for u in sorted_users
                ]

            result["data"]["user_count"] = len(sorted_users)

        # Add special accounts if provided
        if special_accounts:
            result["special_accounts"] = [
                {
                    "account": account,
                    "sent": special_stats.get(account.lower(), {}).get("sent", 0),
                    "received": special_stats.get(account.lower(), {}).get("received", 0),
                }
                for account in special_accounts
            ]

        return result

    except Exception as e:
        import traceback
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error in email analytics: {str(e)}\n{traceback.format_exc()}"
        }

def get_drive_file_info(drive_url: str) -> str:
    """
    Get document or folder title and metadata from a Google Drive URL.

    Extracts the file ID from a Google Drive URL and retrieves file/folder information
    including title, owner, creation date, modification date, sharing status, etc.
    Works for both files and folders.

    Args:
        drive_url: Google Drive URL in any format:
                   - https://docs.google.com/document/d/FILE_ID/edit
                   - https://drive.google.com/file/d/FILE_ID/view
                   - https://drive.google.com/drive/folders/FILE_ID
                   - https://drive.google.com/open?id=FILE_ID
                   - etc.

    Returns:
        str: JSON string with file/folder metadata or error message

    Example:
        get_drive_file_info("https://docs.google.com/document/d/1abc123xyz/edit")
        # Returns: {"title": "Document Name", "owner": "user@example.com", ...}

        get_drive_file_info("https://drive.google.com/drive/folders/1abc123xyz")
        # Returns: {"title": "Folder Name", "mime_type": "application/vnd.google-apps.folder", ...}
    """
    import re
    import subprocess
    import json
    from datetime import datetime

    try:
        # Extract file ID from various Google Drive URL formats
        file_id = None

        # Pattern 1: /folders/FILE_ID (for folder URLs)
        match = re.search(r'/folders/([a-zA-Z0-9_-]+)', drive_url)
        if match:
            file_id = match.group(1)

        # Pattern 2: /d/FILE_ID/ or /file/d/FILE_ID/ (for file/document URLs)
        if not file_id:
            match = re.search(r'/d/([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 3: ?id=FILE_ID
        if not file_id:
            match = re.search(r'[?&]id=([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 4: FILE_ID directly (if URL is just the ID)
        if not file_id:
            if re.match(r'^[a-zA-Z0-9_-]+$', drive_url):
                file_id = drive_url

        if not file_id:
            return json.dumps({
                "error": "Could not extract file ID from URL",
                "url": drive_url,
                "message": "Please provide a valid Google Drive URL (e.g., https://docs.google.com/document/d/FILE_ID/edit)"
            }, indent=2)

        # Query Drive API via gws CLI
        _cmd = ["gws"] + "drive files get".split()
        _cmd.extend(["--params", json.dumps({
            "fileId": file_id,
            "fields": "id,name,mimeType,createdTime,modifiedTime,owners,shared,webViewLink,webContentLink,size,permissions,capabilities,description,starred,trashed",
            "supportsAllDrives": True,
        })])
        _cmd.extend(["--format", "json"])
        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)

        if _r.returncode != 0:
            _err = _r.stderr or ""
            if "404" in _err or "notFound" in _err:
                return json.dumps({
                    "error": "File not found",
                    "file_id": file_id,
                    "message": "The file does not exist or has been deleted. You may not have access to this file."
                }, indent=2)
            elif "403" in _err or "forbidden" in _err.lower():
                return json.dumps({
                    "error": "Access denied",
                    "file_id": file_id,
                    "message": "You do not have permission to access this file. The file may not be shared with you."
                }, indent=2)
            else:
                return json.dumps({
                    "error": f"Drive API error",
                    "file_id": file_id,
                    "message": _err[:500] if _err else f"gws exit {_r.returncode}"
                }, indent=2)

        file = json.loads(_r.stdout) if _r.stdout.strip() else {}

        # Format response
        owners = file.get("owners", [])
        owner_emails = [owner.get("emailAddress", "unknown") for owner in owners]
        owner_names = [owner.get("displayName", "unknown") for owner in owners]

        mime_type = file.get("mimeType", "unknown")
        is_folder = mime_type == "application/vnd.google-apps.folder"

        result = {
            "success": True,
            "file_id": file.get("id"),
            "title": file.get("name", "(untitled)"),
            "mime_type": mime_type,
            "is_folder": is_folder,
            "created_time": file.get("createdTime"),
            "modified_time": file.get("modifiedTime"),
            "owners": owner_emails,
            "owner_names": owner_names,
            "shared": file.get("shared", False),
            "web_view_link": file.get("webViewLink", ""),
            "web_content_link": file.get("webContentLink", ""),
            "size_bytes": file.get("size"),
            "description": file.get("description", ""),
            "starred": file.get("starred", False),
            "trashed": file.get("trashed", False),
            "capabilities": file.get("capabilities", {}),
        }

        # Format dates for readability
        if result["created_time"]:
            try:
                created_dt = datetime.fromisoformat(result["created_time"].replace('Z', '+00:00'))
                result["created_date"] = created_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        if result["modified_time"]:
            try:
                modified_dt = datetime.fromisoformat(result["modified_time"].replace('Z', '+00:00'))
                result["modified_date"] = modified_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        # Format size
        if result["size_bytes"]:
            size = int(result["size_bytes"])
            if size < 1024:
                result["size"] = f"{size} bytes"
            elif size < 1024 * 1024:
                result["size"] = f"{size / 1024:.1f} KB"
            else:
                result["size"] = f"{size / (1024 * 1024):.1f} MB"

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error processing URL: {str(e)}",
            "url": drive_url
        }, indent=2)

def collect_daily_workspace_activity(date: Optional[str] = None) -> str:
    """
    Collect workspace-wide Drive activity for a specific date.

    Queries Admin Reports API for all Drive activity on the specified date,
    aggregates by activity type, document, and user, and returns top-five lists.

    IMPORTANT: Always pass the 'date' parameter when the user requests data for a specific date.
    For example, if the user asks for November 10, 2025, call this function with date='2025-11-10'.

    Args:
        date: Date in YYYY-MM-DD format (e.g., '2025-11-10'). REQUIRED when user requests a specific date.
              If provided, queries exactly that date (including weekends).
              If not provided, defaults to last workday (which may not be what the user wants).

    Returns:
        str: JSON string containing workspace activity data with top-five lists. The JSON includes
             a 'date' field showing which date was actually queried.
    """
    import subprocess
    import json
    import time
    import os
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60

    try:
        # Determine target date
        if date:
            # User provided a specific date - use it exactly as requested
            try:
                target_date = datetime.strptime(date, "%Y-%m-%d")
                date_str = target_date.strftime("%Y-%m-%d")
            except ValueError as e:
                return json.dumps({
                    "error": f"Invalid date format: '{date}'. Expected YYYY-MM-DD format (e.g., '2025-11-10'). Error: {str(e)}",
                    "type": "error"
                })
        else:
            # No date provided - default to last workday (inline _get_last_workday)
            target_date = datetime.now() - timedelta(days=1)
            while target_date.weekday() >= 5:
                target_date -= timedelta(days=1)
            date_str = target_date.strftime("%Y-%m-%d")

        # Note: We query the exact date requested, even if it's a weekend
        # The API will return whatever data exists for that date
        start_time = f"{date_str}T00:00:00Z"
        end_time = f"{date_str}T23:59:59Z"

        # Query Admin Reports API via gws CLI with pagination
        all_activities = []
        next_page_token = None

        while True:
            _params = {
                "userKey": "all",
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return json.dumps({
                    "error": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}",
                    "type": "error"
                })
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            all_activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        activities = all_activities

        # Analyze activities
        activity_types = {}
        actors = set()
        documents = {}

        # Track by category for top-five lists
        edit_counts = {}
        share_counts = {}
        comment_counts = {}
        view_counts = {}
        user_counts = {}

        for activity in activities:
            actor_email = activity.get("actor", {}).get("email", "(unknown)")
            actors.add(actor_email)
            user_counts[actor_email] = user_counts.get(actor_email, 0) + 1

            for event in activity.get("events", []):
                event_name = event.get("name", "unknown")
                activity_types[event_name] = activity_types.get(event_name, 0) + 1

                # Extract document info
                doc_id = None
                doc_title = "(untitled)"
                owner = None

                for param in event.get("parameters", []):
                    param_name = param.get("name")
                    param_value = param.get("value")

                    if param_name == "doc_id":
                        doc_id = param_value
                    elif param_name == "doc_title":
                        doc_title = param_value
                    elif param_name == "owner":
                        owner = param_value

                if doc_id:
                    if doc_id not in documents:
                        documents[doc_id] = {
                            "doc_id": doc_id,
                            "title": doc_title,
                            "owner": owner,
                            "edit_count": 0,
                            "share_count": 0,
                            "comment_count": 0,
                            "view_count": 0,
                            "link": "",  # Will be populated if accessible
                            "is_accessible": False,  # Will be checked later
                            "is_shared": False,  # Will be checked later
                            "access_error": "",  # Will be set if not accessible
                        }

                    # Categorize by event type
                    if event_name == "edit":
                        documents[doc_id]["edit_count"] += 1
                        edit_counts[doc_id] = edit_counts.get(doc_id, 0) + 1
                    elif event_name in ["change_user_access", "change_acl_editors",
                                       "change_document_visibility", "change_document_access_scope"]:
                        documents[doc_id]["share_count"] += 1
                        share_counts[doc_id] = share_counts.get(doc_id, 0) + 1
                    elif event_name in ["create_comment", "resolve_comment", "delete_comment", "edit_comment"]:
                        documents[doc_id]["comment_count"] += 1
                        comment_counts[doc_id] = comment_counts.get(doc_id, 0) + 1
                    elif event_name == "view":
                        documents[doc_id]["view_count"] += 1
                        view_counts[doc_id] = view_counts.get(doc_id, 0) + 1

        # Fetch links and check accessibility for top documents
        # Only check top 25 documents to avoid too many API calls
        top_doc_ids = sorted(
            list(documents.keys()),
            key=lambda x: (
                documents[x].get("edit_count", 0) +
                documents[x].get("view_count", 0) +
                documents[x].get("share_count", 0) +
                documents[x].get("comment_count", 0)
            ),
            reverse=True
        )[:25]

        # Check accessibility and fetch links for top documents via gws
        for doc_id in top_doc_ids:
            _cmd = ["gws"] + "drive files get".split()
            _cmd.extend(["--params", json.dumps({
                "fileId": doc_id,
                "fields": "id,name,webViewLink,shared,capabilities",
                "supportsAllDrives": True,
            })])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)
            if _r.returncode != 0:
                _err = _r.stderr or ""
                if "404" in _err or "notFound" in _err:
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                    documents[doc_id]["access_error"] = "deleted"
                elif "403" in _err or "forbidden" in _err.lower():
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                    documents[doc_id]["access_error"] = "no_access"
                else:
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                continue
            try:
                file = json.loads(_r.stdout) if _r.stdout.strip() else {}
            except Exception:
                documents[doc_id]["is_accessible"] = False
                documents[doc_id]["link"] = ""
                continue
            if file:
                documents[doc_id]["link"] = file.get("webViewLink", "")
                documents[doc_id]["is_accessible"] = True
                documents[doc_id]["is_shared"] = file.get("shared", False)
                if file.get("name") and not documents[doc_id].get("title"):
                    documents[doc_id]["title"] = file.get("name")

        # Generate top-five lists (inlined - no nested def for Letta compliance)
        top_edited = []
        for doc_id, cnt in sorted(edit_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_edited.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_shared = []
        for doc_id, cnt in sorted(share_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_shared.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_commented = []
        for doc_id, cnt in sorted(comment_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_commented.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_viewed = []
        for doc_id, cnt in sorted(view_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_viewed.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        # Top active users
        top_users = sorted(user_counts.items(), key=lambda x: x[1], reverse=True)[:5]
        top_active_users = [{"email": email, "activity_count": count} for email, count in top_users]

        result = {
            "type": "drive_analytics_daily",
            "date": date_str,
            "is_workday": target_date.weekday() < 5,
            "date_requested": date if date else None,  # Show what was requested vs what was used
            "summary": {
                "total_activities": len(activities),
                "unique_users": len(actors),
                "unique_documents": len(documents),
            },
            "top_activity_types": [
                {"type": k, "count": v}
                for k, v in sorted(activity_types.items(), key=lambda x: x[1], reverse=True)
            ],
            "top_five": {
                "most_edited": top_edited,
                "most_shared": top_shared,
                "most_commented": top_commented,
                "most_viewed": top_viewed,
                "most_active_users": top_active_users,
            },
        }

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error collecting workspace activity: {str(e)}",
            "type": "error"
        })

def get_document_events(doc_ids: List[str], days: int = 7) -> Dict[str, Any]:
    """
    Get individual events (timeline) for specific documents.

    Returns a detailed timeline of who did what and when on specific documents.
    Use this for audit trails or understanding the sequence of activity.
    For aggregated counts, use search_drive_activity instead.

    Args:
        doc_ids: List of document IDs to query
        days: Number of days to look back (default: 7)

    Returns:
        Dict with events list (time, actor, action) and summary counts per document

    Example:
        # Get timeline for a specific document
        get_document_events(doc_ids=["1abc...xyz"])
        # Returns: {"status": "ok", "data": {"documents": [{"doc_id": "...", "events": [...]}]}}
    """
    # Imports inside function (Letta compliance)
    import subprocess
    import json
    import time
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60

    try:
        # Calculate date range
        end_date = datetime.now()
        start_date_dt = end_date - timedelta(days=days)

        start_time = start_date_dt.strftime("%Y-%m-%dT00:00:00Z")
        end_time = end_date.strftime("%Y-%m-%dT23:59:59Z")

        # Query Admin Reports API via gws CLI with pagination
        activities = []
        next_page_token = None
        MAX_PAGES = 15
        pages_fetched = 0

        while pages_fetched < MAX_PAGES:
            _params = {
                "userKey": "all",
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}"
                }
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            activities.extend(_data.get("items", []))
            pages_fetched += 1
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        # Filter activities for specified documents
        doc_activities = {}
        doc_id_set = set(doc_ids)

        for doc_id in doc_ids:
            doc_activities[doc_id] = {
                "doc_id": doc_id,
                "events": [],
                "summary": {
                    "edit_count": 0,
                    "view_count": 0,
                    "share_count": 0,
                    "comment_count": 0,
                },
            }

        for activity in activities:
            for event in activity.get("events", []):
                for param in event.get("parameters", []):
                    if param.get("name") == "doc_id":
                        doc_id = param.get("value")
                        if doc_id in doc_id_set:
                            event_name = event.get("name", "unknown")
                            doc_activities[doc_id]["events"].append({
                                "time": activity.get("id", {}).get("time"),
                                "actor": activity.get("actor", {}).get("email", "(unknown)"),
                                "action": event_name,
                            })

                            if event_name == "edit":
                                doc_activities[doc_id]["summary"]["edit_count"] += 1
                            elif event_name == "view":
                                doc_activities[doc_id]["summary"]["view_count"] += 1
                            elif event_name in ["change_user_access", "change_acl_editors"]:
                                doc_activities[doc_id]["summary"]["share_count"] += 1
                            elif event_name in ["create_comment", "resolve_comment"]:
                                doc_activities[doc_id]["summary"]["comment_count"] += 1

        # Sort events by time for each document
        for doc in doc_activities.values():
            doc["events"].sort(key=lambda x: x["time"] or "", reverse=True)

        return {
            "status": "ok",
            "data": {
                "documents": list(doc_activities.values()),
                "period_days": days,
                "truncated": pages_fetched >= MAX_PAGES,
            }
        }

    except Exception as e:
        import traceback
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error getting document events: {str(e)}\n{traceback.format_exc()}"
        }

def find_user_blocks(
    user_id: str,
    scope: Optional[str] = None
) -> Dict[str, Any]:
    """
    Discover all memory blocks for a user via naming convention.

    This tool is called by the agent to find blocks belonging to a specific user.
    Blocks are identified by naming convention: {category}_{user_id} or
    {agent_name}_{category}_{user_id}_{purpose}.

    Args:
        user_id: The user identifier (e.g., Slack user ID like "U12345678")
        scope: Filter scope - "all" (default), "cross_agent", or "agent_specific".
               "all" returns all blocks matching user_id.
               "cross_agent" returns only blocks WITHOUT agent name prefix (shared).
               "agent_specific" returns only blocks WITH agent name prefix.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - blocks: List of dicts with block info {id, label, value_preview}
        - count: Number of blocks found
        - error_message: Error message if status is "error"

    Example:
        >>> find_user_blocks(user_id="U12345678", scope="all")
        {
            "status": "ok",
            "blocks": [
                {"id": "block-abc", "label": "preferences_U12345678", "value_preview": "Prefers morning..."},
                {"id": "block-def", "label": "calendar_U12345678", "value_preview": "Calendar synced..."}
            ],
            "count": 2
        }
    """
    # IMPORTS FIRST - inside function for Letta tool extraction
    import os
    import re
    import traceback

    try:
        from letta_client import Letta
    except ImportError:
        try:
            from letta import Letta
        except ImportError:
            Letta = None

    # TRY-EXCEPT WRAPPER
    try:
        # SET DEFAULTS
        if scope is None:
            scope = "all"

        # CONFIGURATION - inside function for Letta tool extraction
        agent_name = os.getenv("AGENT_NAME", "meeting_scheduler")
        letta_base_url = os.getenv("LETTA_BASE_URL", "http://localhost:8283")
        letta_agent_id = os.getenv(
            "LETTA_AGENT_ID",
            os.getenv("SCHEDULER_AGENT_ID", "agent-892a2d58-b9f6-4baf-84f3-c431fe46487d")
        )

        # INPUT VALIDATION
        if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": f"Invalid user_id format: {user_id}. Must be alphanumeric with underscores/hyphens."
            }

        if scope not in ("all", "cross_agent", "agent_specific"):
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": f"Invalid scope: {scope}. Must be 'all', 'cross_agent', or 'agent_specific'."
            }

        # GET AGENT BLOCKS (inline, no helper function)
        if Letta is None:
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": "Letta client not available"
            }

        client = Letta(base_url=letta_base_url)
        agent = client.agents.retrieve(agent_id=letta_agent_id)
        all_blocks = agent.memory.blocks if agent.memory else []

        # FILTER BY USER_ID IN LABEL
        # Match patterns: {category}_{user_id} or {prefix}_{user_id}_{suffix}
        user_blocks = []
        for block in all_blocks:
            label = getattr(block, 'label', '') or ''
            # Check if user_id appears in label (either as suffix or in middle)
            if f"_{user_id}" in label or f"_{user_id}_" in label or label.endswith(f"_{user_id}"):
                user_blocks.append(block)

        # APPLY SCOPE FILTERING
        agent_prefix = f"{agent_name}_"

        if scope == "cross_agent":
            # Exclude blocks that start with agent name
            user_blocks = [b for b in user_blocks if not (getattr(b, 'label', '') or '').startswith(agent_prefix)]
        elif scope == "agent_specific":
            # Include only blocks that start with agent name
            user_blocks = [b for b in user_blocks if (getattr(b, 'label', '') or '').startswith(agent_prefix)]
        # scope == "all" returns everything matching user_id

        # FORMAT RESPONSE WITH VALUE PREVIEW
        result_blocks = []
        for block in user_blocks:
            value = getattr(block, 'value', '') or ''
            preview = value[:100] + "..." if len(value) > 100 else value
            result_blocks.append({
                "id": block.id,
                "label": getattr(block, 'label', ''),
                "value_preview": preview
            })

        return {
            "status": "ok",
            "blocks": result_blocks,
            "count": len(result_blocks)
        }

    except Exception as e:
        return {
            "status": "error",
            "blocks": [],
            "count": 0,
            "error_message": f"Failed to find user blocks: {str(e)}\n{traceback.format_exc()}"
        }

def extract_document_entities(
    file_id: str,
) -> Dict[str, Any]:
    """
    Extract entities from a document and add them to the knowledge graph.

    Use this tool to trigger entity extraction for a specific document.
    This will identify people, organizations, projects, and topics
    mentioned in the document and add them to the knowledge graph
    for cross-document queries.

    Args:
        file_id: Google Drive file ID or URL of the document to process.
                 Accepts URLs like https://docs.google.com/document/d/FILE_ID/edit

    Returns:
        Dictionary with extraction status and episode UUID.
    """
    import os
    import re
    import traceback
    import requests

    try:
        # Parse URL to file ID if needed (inline - Letta can't access module-level helpers)
        file_id = file_id.strip()
        match = re.search(r"/d/([a-zA-Z0-9_-]+)", file_id)
        if match:
            file_id = match.group(1)
        else:
            match = re.search(r"[?&]id=([a-zA-Z0-9_-]+)", file_id)
            if match:
                file_id = match.group(1)

        # Get service URL from environment or use default
        base_url = os.environ.get("DRIVE_RAG_SERVICE_URL", "http://drive-rag-service:8000")

        # Make request
        response = requests.post(
            f"{base_url}/v1/entities/extract/{file_id}",
            timeout=120,  # Entity extraction can take time
        )

        if response.status_code == 400:
            return {
                "status": "error",
                "error_message": f"Cannot extract entities: {response.json().get('detail', response.text)}",
            }

        if response.status_code != 200:
            return {
                "status": "error",
                "error_message": f"Failed to extract entities: {response.text}",
            }

        data = response.json()

        if data.get("status") == "error":
            return {
                "status": "error",
                "error_message": data.get("error", "Unknown error"),
            }

        return {
            "status": "ok",
            "file_id": file_id,
            "episode_uuid": data.get("episode_uuid"),
            "message": "Entity extraction queued. Entities will be available shortly.",
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

def create_user_memory_block(
    user_id: str,
    category: str,
    value: str,
    purpose: Optional[str] = None,
    agent_specific: Optional[bool] = None
) -> Dict[str, Any]:
    """
    Create a new memory block for emergent user preferences.

    This tool is called by the agent when it learns something new about a user
    that should be persisted. The block is created with a naming convention
    that enables later discovery via find_user_blocks.

    Naming conventions:
    - Cross-agent: {category}_{user_id}[_{purpose}]
    - Agent-specific: {agent_name}_{category}_{user_id}[_{purpose}]

    Args:
        user_id: The user identifier (e.g., Slack user ID like "U12345678")
        category: Block category (e.g., "preferences", "calendar", "context")
        value: Initial block content (max 2000 characters)
        purpose: Optional specific purpose (e.g., "meeting_duration", "timezone")
        agent_specific: If True, prefix with agent name (only this agent sees it). Default: False.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - block_id: ID of created block (if successful)
        - label: Label of created block (if successful)
        - error_message: Error message if status is "error"

    Example:
        >>> create_user_memory_block(
        ...     user_id="U12345678",
        ...     category="preferences",
        ...     value="Prefers 30 minute meetings in the morning",
        ...     purpose="meeting_duration"
        ... )
        {"status": "ok", "block_id": "block-abc123", "label": "preferences_U12345678_meeting_duration"}
    """
    # IMPORTS FIRST - inside function for Letta tool extraction
    import os
    import re
    import traceback

    try:
        from letta_client import Letta
    except ImportError:
        try:
            from letta import Letta
        except ImportError:
            Letta = None

    # TRY-EXCEPT WRAPPER
    try:
        # SET DEFAULTS
        if agent_specific is None:
            agent_specific = False

        # CONFIGURATION - inside function for Letta tool extraction
        agent_name = os.getenv("AGENT_NAME", "meeting_scheduler")
        letta_base_url = os.getenv("LETTA_BASE_URL", "http://localhost:8283")
        letta_agent_id = os.getenv(
            "LETTA_AGENT_ID",
            os.getenv("SCHEDULER_AGENT_ID", "agent-892a2d58-b9f6-4baf-84f3-c431fe46487d")
        )

        # INPUT VALIDATION
        if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
            return {
                "status": "error",
                "error_message": f"Invalid user_id format: {user_id}. Must be alphanumeric with underscores/hyphens."
            }

        if not re.match(r'^[a-zA-Z0-9_-]+$', category):
            return {
                "status": "error",
                "error_message": f"Invalid category format: {category}. Must be alphanumeric with underscores/hyphens."
            }

        if purpose and not re.match(r'^[a-zA-Z0-9_-]+$', purpose):
            return {
                "status": "error",
                "error_message": f"Invalid purpose format: {purpose}. Must be alphanumeric with underscores/hyphens."
            }

        if len(value) > 2000:
            return {
                "status": "error",
                "error_message": f"Block value too long ({len(value)} chars). Maximum is 2000 characters."
            }

        # BUILD LABEL BASED ON NAMING CONVENTION
        if agent_specific:
            label = f"{agent_name}_{category}_{user_id}"
        else:
            label = f"{category}_{user_id}"

        if purpose:
            label += f"_{purpose}"

        # Normalize label
        label = label.lower().replace(" ", "_")

        if len(label) > 200:
            return {
                "status": "error",
                "error_message": f"Block label too long ({len(label)} chars). Maximum is 200 characters."
            }

        # GET LETTA CLIENT (inline, no helper function)
        if Letta is None:
            return {
                "status": "error",
                "error_message": "Letta client not available. Check LETTA_BASE_URL configuration."
            }

        client = Letta(base_url=letta_base_url)

        # CREATE THE BLOCK
        description = f"{category} for {user_id}"
        if purpose:
            description += f": {purpose}"

        block = client.blocks.create(
            label=label,
            value=value,
            description=description,
            limit=2000
        )

        # ATTACH BLOCK TO AGENT
        client.agents.blocks.attach(
            agent_id=letta_agent_id,
            block_id=block.id
        )

        return {
            "status": "ok",
            "block_id": block.id,
            "label": label
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to create block: {str(e)}\n{traceback.format_exc()}"
        }

