def explore_document_entities(
    file_id: str,
) -> Dict[str, Any]:
    """
    Show all entities and relationships extracted from a document.

    Use this tool to understand what entities (people, organizations,
    projects, topics) were identified in a document and how they
    relate to each other.

    Args:
        file_id: Google Drive file ID or URL of the document to explore.
                 Accepts URLs like https://docs.google.com/document/d/FILE_ID/edit

    Returns:
        Dictionary with entities found in the document and their
        relationships to other entities.
    """
    import os
    import re
    import traceback
    import requests

    try:
        # Parse URL to file ID if needed (inline - Letta can't access module-level helpers)
        file_id = file_id.strip()
        match = re.search(r"/d/([a-zA-Z0-9_-]+)", file_id)
        if match:
            file_id = match.group(1)
        else:
            match = re.search(r"[?&]id=([a-zA-Z0-9_-]+)", file_id)
            if match:
                file_id = match.group(1)

        # Get service URL from environment or use default
        base_url = os.environ.get("DRIVE_RAG_SERVICE_URL", "http://drive-rag-service:8000")

        # Make request
        response = requests.get(
            f"{base_url}/v1/entities/document/{file_id}",
            timeout=60,
        )

        if response.status_code == 404:
            return {
                "status": "error",
                "error_message": f"Document {file_id} not found or has no extracted entities",
            }

        if response.status_code != 200:
            return {
                "status": "error",
                "error_message": f"Failed to get document entities: {response.text}",
            }

        data = response.json()

        if data.get("status") == "error":
            return {
                "status": "error",
                "error_message": data.get("error", "Unknown error"),
            }

        return {
            "status": "ok",
            "file_id": file_id,
            "entities": data.get("entities", {}),
            "relationships": data.get("relationships", {}),
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

def send_message_to_agent(
    sender_agent_id: str,
    recipient_agent_id: str,
    message: str
) -> str:
    """
    Send a message to another Letta agent in the same org and return the API response.

    This tool rebuilds send_message_to_agent_and_wait_for_reply as send_message_to_agent
    with compatibility for v1 agents. The implementation flow is the same except the
    system message sent to the recipient agent has been updated to return an assistant
    message instead of using the deprecated send_message tool.

    Args:
        sender_agent_id: The ID of the agent that is sending the message (you).
        recipient_agent_id: The ID of the target agent to receive the message.
        message: The message content.

    Returns:
        A JSON string containing the replies received from the recipient agent.
        Format: {"replies": [list of reply strings], "status": "ok" or "error", "error": "error message if any"}
    """
    # Import required modules (needed when Letta generates wrapper code)
    import os
    import requests
    import json

    letta_api_key = os.environ.get("LETTA_API_KEY")
    letta_base_url = os.environ.get("LETTA_BASE_URL", "http://localhost:8283")

    # Construct the API endpoint
    api_url = f"{letta_base_url}/v1/agents/{recipient_agent_id}/messages"

    # Prepare the request payload
    # The system message includes instructions for the recipient agent to respond
    # using assistant messages instead of the deprecated send_message tool
    payload = {
        "messages": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": (
                            f"[Incoming message from external Letta agent {sender_agent_id} - "
                            f"to reply to the requesting agent, simply send an assistant message "
                            f"with your response. The system will relay the message to the sender. "
                            f"send_message tool is now deprecated.] {message}"
                        )
                    }
                ]
            }
        ]
    }

    # Prepare headers
    # For self-hosted Letta, API key may not be required when calling from within the network
    headers = {
        "Content-Type": "application/json"
    }

    # Add Authorization header only if API key is available
    if letta_api_key:
        headers["Authorization"] = f"Bearer {letta_api_key}"

    try:
        # Make the POST request
        response = requests.post(
            api_url,
            headers=headers,
            json=payload,
            timeout=60  # 60 second timeout for agent responses
        )

        # Check for HTTP errors
        response.raise_for_status()

        # Parse the response
        data = response.json()
        messages = data.get('messages', [])

        # Extract assistant messages (replies from the recipient agent)
        replies = []
        for m in messages:
            if isinstance(m, dict):
                # Check if this is an assistant message
                if m.get('message_type') == 'assistant_message' and m.get('content'):
                    # Extract text content from assistant message
                    content = m.get('content')
                    if isinstance(content, str):
                        replies.append(content)
                    elif isinstance(content, list):
                        # Handle structured content (list of content blocks)
                        for block in content:
                            if isinstance(block, dict) and block.get('type') == 'text':
                                replies.append(block.get('text', ''))
                    elif isinstance(content, dict):
                        # Handle dict content
                        if content.get('type') == 'text':
                            replies.append(content.get('text', ''))

        # Return results as JSON string
        return json.dumps({
            "status": "ok",
            "replies": replies,
            "num_replies": len(replies)
        }, indent=2)

    except requests.exceptions.RequestException as e:
        error_msg = f"HTTP request failed: {str(e)}"
        if hasattr(e, 'response') and e.response is not None:
            try:
                error_detail = e.response.json()
                error_msg += f" - {json.dumps(error_detail)}"
            except:
                error_msg += f" - Status: {e.response.status_code}"

        return json.dumps({
            "status": "error",
            "error": error_msg,
            "replies": []
        })

    except json.JSONDecodeError as e:
        return json.dumps({
            "status": "error",
            "error": f"Failed to parse response JSON: {str(e)}",
            "replies": []
        })

    except Exception as e:
        return json.dumps({
            "status": "error",
            "error": f"Unexpected error: {str(e)}",
            "replies": []
        })

def check_credential_status() -> Dict[str, Any]:
    """
    Check the authentication status of all streaming service credentials.

    This tool checks which services have credentials configured and whether
    they appear to be valid. Useful for the sleeptime agent to know which
    services can be polled.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - services: Dict mapping service names to their credential status
        - configured_count: Number of services with credentials
        - error_message: Error message if status is "error"
    """
    # IMPORTS FIRST
    import traceback
    import requests
    import logging

    logger = logging.getLogger(__name__)

    services = ['max', 'hulu', 'disney', 'apple', 'netflix', 'prime']

    try:
        poller_url = "http://watch-history-service:5127"
        service_status = {}
        configured_count = 0

        for service in services:
            try:
                response = requests.get(
                    f"{poller_url}/credentials/{service}",
                    timeout=10
                )
                if response.status_code == 200:
                    data = response.json()
                    service_status[service] = {
                        'configured': data.get('configured', False),
                        'keys': data.get('keys', [])
                    }
                    if data.get('configured'):
                        configured_count += 1
                else:
                    service_status[service] = {
                        'configured': False,
                        'error': f"HTTP {response.status_code}"
                    }
            except Exception as e:
                service_status[service] = {
                    'configured': False,
                    'error': str(e)
                }

        return {
            'status': 'ok',
            'services': service_status,
            'configured_count': configured_count,
            'total_services': len(services)
        }

    except Exception as e:
        logger.error(f"Error checking credentials: {e}")
        return {
            'status': 'error',
            'services': {},
            'configured_count': 0,
            'error_message': f"Error: {str(e)}\n{traceback.format_exc()}"
        }

def poll_watchlists(
    service: Optional[str] = None,
    username: Optional[str] = None
) -> Dict[str, Any]:
    """
    Poll streaming services for watchlist/My List and automatically save to database.

    This tool fetches the user's saved watchlists from streaming services
    and AUTOMATICALLY saves entries to the database. Just report the results.
    (Netflix My List, Prime Watchlist, etc.) and saves them to the database.
    Use this to keep track of what the user wants to watch.

    Args:
        service: Specific service to poll. Options: 'netflix', 'prime', 
                 'disney', 'apple'. Leave empty to poll all services.
        username: The user to associate watchlists with. Defaults to 'chad'.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - services: Dict of service -> {count, saved}
        - total_items: Total items found across all services
    """
    import traceback
    import requests
    import logging

    logger = logging.getLogger(__name__)

    try:
        # Normalize empty strings to None
        if username is None or username == '':
            username = 'chad'
        if service == '':
            service = None

        watch_history_url = "http://watch-history-service:5127"

        if service:
            # Poll single service
            response = requests.post(
                f"{watch_history_url}/watchlist/{service}",
                json={'username': username},
                timeout=120
            )
            response.raise_for_status()
            data = response.json()

            return {
                'status': 'ok',
                'services': {
                    service: {
                        'count': data.get('count', 0),
                        'saved': data.get('saved', 0)
                    }
                },
                'total_items': data.get('count', 0)
            }
        else:
            # Poll all services
            response = requests.post(
                f"{watch_history_url}/watchlist/all",
                json={'username': username},
                timeout=300
            )
            response.raise_for_status()
            data = response.json()

            services_summary = {}
            for svc, info in data.get('services', {}).items():
                services_summary[svc] = {
                    'count': info.get('count', 0),
                    'saved': info.get('saved', 0)
                }

            return {
                'status': 'ok',
                'services': services_summary,
                'total_items': data.get('total', 0)
            }

    except Exception as e:
        logger.error(f"Error polling watchlists: {e}")
        return {
            'status': 'error',
            'services': {},
            'total_items': 0,
            'error_message': f"Error: {str(e)}\n{traceback.format_exc()}"
        }

