def get_slack_channels(
    channel: Optional[str] = None,
    types: Optional[str] = None,
    exclude_archived: Optional[bool] = True,
    include_members: Optional[bool] = False,
    limit: Optional[int] = 500
) -> Dict[str, Any]:
    """
    Get Slack channel information - list all channels, get specific channel details, or resolve channel names.

    When channel parameter is provided, returns single channel (or multiple if comma-separated).
    When channel parameter is omitted, returns list of all channels.

    Args:
        channel: Channel ID(s) or name(s) (e.g., "C1234567890", "#random", or "#general,#random").
                 Can be a single channel or comma-separated list. If omitted, returns list of all channels.
        types: Filter channel types when listing. Comma-separated: "public_channel,private_channel,mpim,im".
               Default: all types.
        exclude_archived: Exclude archived channels when listing. Default: True.
        include_members: Include member list for single channel. Default: False.
        limit: Maximum number of channels to return when listing. Default: 500.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - data: Channel data (single channel object, list of channels, or array for multiple channels)
        - error_message: Error message if status is "error"
    """
    # Imports inside function at the very beginning
    import os
    import traceback
    import json
    import urllib.request
    import urllib.parse
    from datetime import datetime

    # Wrap entire function in try-except
    try:
        # Get token
        TOKEN = os.getenv("SLACK_MCP_XOXP_TOKEN", "")
        if not TOKEN:
            return {
                "status": "error",
                "data": {},
                "error_message": "SLACK_MCP_XOXP_TOKEN not set in environment"
            }

        # Normalize channel parameter - handle both single value and list
        channel_list = []
        is_single = False
        is_multiple = False

        if channel is not None:
            if isinstance(channel, str):
                channel_list = [channel]
                is_single = True
            elif isinstance(channel, list):
                channel_list = channel
                is_multiple = len(channel) > 1
                is_single = len(channel) == 1
            else:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"channel parameter must be string or list, got {type(channel)}"
                }

        # Set defaults
        if limit is None:
            limit = 500
        if exclude_archived is None:
            exclude_archived = True
        if include_members is None:
            include_members = False

        # If channel(s) specified, get specific channel(s)
        if channel_list:
            resolved_channels = []
            for ch in channel_list:
                # Inline channel resolution logic
                resolved_id = ch
                if not ch.startswith(("C", "G", "D", "mpdm-")):
                    # Need to resolve name to ID
                    channel_name = ch.lstrip("#")
                    try:
                        url = "https://slack.com/api/conversations.list"
                        params = {"limit": "1000", "exclude_archived": "true"}
                        query_string = urllib.parse.urlencode(params)
                        req = urllib.request.Request(
                            f"{url}?{query_string}",
                            headers={"Authorization": f"Bearer {TOKEN}"}
                        )
                        with urllib.request.urlopen(req, timeout=30) as r:
                            data = json.loads(r.read().decode('utf-8'))
                            if data.get("ok"):
                                found = False
                                for ch_item in data.get("channels", []):
                                    if ch_item.get("name") == channel_name:
                                        resolved_id = ch_item.get("id")
                                        found = True
                                        break
                                if not found:
                                    resolved_id = ch
                    except Exception:
                        resolved_id = ch
                else:
                    resolved_id = ch.lstrip("#")

                # Get channel info (inline)
                try:
                    url = "https://slack.com/api/conversations.info"
                    params = {"channel": resolved_id}
                    if include_members:
                        params["include_num_members"] = "true"
                    query_string = urllib.parse.urlencode(params)
                    req = urllib.request.Request(
                        f"{url}?{query_string}",
                        headers={"Authorization": f"Bearer {TOKEN}"}
                    )
                    with urllib.request.urlopen(req, timeout=30) as r:
                        data = json.loads(r.read().decode('utf-8'))
                        if not data.get("ok"):
                            if is_single:
                                return {
                                    "status": "error",
                                    "data": {},
                                    "error_message": f"Error getting channel {ch}: {data.get('error', 'Unknown error')}"
                                }
                            continue

                        channel_data = data.get("channel", {})

                        # Format response (inline)
                        ch_info = {
                            "id": channel_data.get("id"),
                            "name": channel_data.get("name"),
                            "is_channel": channel_data.get("is_channel", False),
                            "is_group": channel_data.get("is_group", False),
                            "is_im": channel_data.get("is_im", False),
                            "is_mpim": channel_data.get("is_mpim", False),
                            "is_private": channel_data.get("is_private", False),
                            "is_archived": channel_data.get("is_archived", False),
                            "created": channel_data.get("created"),
                            "creator": channel_data.get("creator"),
                            "topic": channel_data.get("topic", {}).get("value", ""),
                            "purpose": channel_data.get("purpose", {}).get("value", ""),
                            "num_members": channel_data.get("num_members")
                        }

                        # Get members if requested (inline)
                        if include_members:
                            members = []
                            try:
                                members_url = "https://slack.com/api/conversations.members"
                                members_params = {"channel": resolved_id, "limit": "1000"}
                                members_query = urllib.parse.urlencode(members_params)
                                members_req = urllib.request.Request(
                                    f"{members_url}?{members_query}",
                                    headers={"Authorization": f"Bearer {TOKEN}"}
                                )
                                with urllib.request.urlopen(members_req, timeout=30) as mr:
                                    members_data = json.loads(mr.read().decode('utf-8'))
                                    if members_data.get("ok"):
                                        members = members_data.get("members", [])
                            except Exception:
                                pass
                            ch_info["members"] = members

                        resolved_channels.append(ch_info)
                except Exception as e:
                    if is_single:
                        return {
                            "status": "error",
                            "data": {},
                            "error_message": f"Error getting channel {ch}: {str(e)}"
                        }
                    continue

            # Return appropriate structure
            if is_single:
                return {
                    "status": "ok",
                    "data": {
                        "channel": resolved_channels[0] if resolved_channels else {}
                    }
                }
            else:
                return {
                    "status": "ok",
                    "data": {
                        "channels": resolved_channels
                    }
                }

        # Otherwise, list all channels
        url = "https://slack.com/api/conversations.list"
        params = {"limit": str(limit)}
        if exclude_archived:
            params["exclude_archived"] = "true"

        # Handle types filter
        if types:
            type_list = [t.strip() for t in types.split(",")]
            params["types"] = ",".join(type_list)

        query_string = urllib.parse.urlencode(params)
        req = urllib.request.Request(
            f"{url}?{query_string}",
            headers={"Authorization": f"Bearer {TOKEN}"}
        )

        with urllib.request.urlopen(req, timeout=30) as r:
            data = json.loads(r.read().decode('utf-8'))

            if not data.get("ok"):
                return {
                    "status": "error",
                    "data": {},
                    "error_message": data.get("error", "Unknown Slack API error")
                }

            channels = data.get("channels", [])

            # Format channels (inline)
            formatted_channels = []
            for ch in channels:
                formatted_channels.append({
                    "id": ch.get("id"),
                    "name": ch.get("name"),
                    "is_channel": ch.get("is_channel", False),
                    "is_group": ch.get("is_group", False),
                    "is_im": ch.get("is_im", False),
                    "is_mpim": ch.get("is_mpim", False),
                    "is_private": ch.get("is_private", False),
                    "is_archived": ch.get("is_archived", False),
                    "created": ch.get("created"),
                    "creator": ch.get("creator"),
                    "topic": ch.get("topic", {}).get("value", ""),
                    "purpose": ch.get("purpose", {}).get("value", ""),
                    "num_members": ch.get("num_members")
                })

            return {
                "status": "ok",
                "data": {
                    "channels": formatted_channels,
                    "total": len(formatted_channels)
                }
            }

    except Exception as e:
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error: {str(e)}\n{traceback.format_exc()}"
        }

def get_slack_users(
    user: Optional[str] = None,
    include_deleted: Optional[bool] = False,
    limit: Optional[int] = 1000
) -> Dict[str, Any]:
    """
    Get Slack user information - list all users, get specific user details, or resolve usernames.

    When user parameter is provided, returns single user (or multiple if comma-separated).
    When user parameter is omitted, returns list of all users.

    Args:
        user: User ID(s) or username(s) (e.g., "U1234567890", "sue", or "sue,dan").
              Can be a single user or comma-separated list. If omitted, returns list of all users.
        include_deleted: Include deleted users when listing. Default: False.
        limit: Maximum number of users to return when listing. Default: 1000.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - data: User data (single user object, list of users, or array for multiple users)
        - error_message: Error message if status is "error"
    """
    # Imports inside function at the very beginning
    import os
    import traceback
    import json
    import urllib.request
    import urllib.parse
    from datetime import datetime

    # Wrap entire function in try-except
    try:
        # Get token
        TOKEN = os.getenv("SLACK_MCP_XOXP_TOKEN", "")
        if not TOKEN:
            return {
                "status": "error",
                "data": {},
                "error_message": "SLACK_MCP_XOXP_TOKEN not set in environment"
            }

        # Normalize user parameter - handle single value, comma-separated, or list (for backward compatibility)
        user_list = []
        is_single = False
        is_multiple = False

        if user is not None:
            if isinstance(user, str):
                # Single user or comma-separated
                if ',' in user:
                    user_list = [u.strip() for u in user.split(',')]
                    is_multiple = True
                else:
                    user_list = [user]
                    is_single = True
            elif isinstance(user, list):
                # Support list for backward compatibility (though Letta schema only allows str)
                user_list = user
                is_multiple = len(user) > 1
                is_single = len(user) == 1
            else:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"user parameter must be string or list, got {type(user)}"
                }

        # Set defaults
        if limit is None:
            limit = 1000
        if include_deleted is None:
            include_deleted = False

        # If user(s) specified, get specific user(s)
        if user_list:
            resolved_users = []
            # Get full user list once to resolve usernames/emails to IDs (more efficient)
            all_users_map = {}  # Map username -> user_data
            all_users_by_email = {}  # Map email -> user_data
            try:
                url = "https://slack.com/api/users.list"
                params = {"limit": "1000"}
                query_string = urllib.parse.urlencode(params)
                req = urllib.request.Request(
                    f"{url}?{query_string}",
                    headers={"Authorization": f"Bearer {TOKEN}"}
                )
                with urllib.request.urlopen(req, timeout=30) as r:
                    data = json.loads(r.read().decode('utf-8'))
                    if data.get("ok"):
                        for user_item in data.get("members", []):
                            user_id = user_item.get("id")
                            username = user_item.get("name", "")
                            profile = user_item.get("profile", {})
                            email = profile.get("email", "")

                            if username:
                                all_users_map[username] = user_item
                            if user_id:
                                all_users_map[user_id] = user_item
                            if email:
                                all_users_by_email[email] = user_item
            except Exception:
                pass

            for u in user_list:
                # Resolve username/email/userID to user item
                user_item = None
                if u.startswith("U"):
                    # It's a user ID
                    if u in all_users_map:
                        user_item = all_users_map[u]
                elif "@" in u:
                    # It's an email address
                    if u in all_users_by_email:
                        user_item = all_users_by_email[u]
                else:
                    # It's a username
                    if u in all_users_map:
                        user_item = all_users_map[u]

                # If not found in cache, try users.info API (for user IDs only)
                if not user_item and u.startswith("U"):
                    try:
                        url = "https://slack.com/api/users.info"
                        params = {"user": u}
                        query_string = urllib.parse.urlencode(params)
                        req = urllib.request.Request(
                            f"{url}?{query_string}",
                            headers={"Authorization": f"Bearer {TOKEN}"}
                        )
                        with urllib.request.urlopen(req, timeout=30) as r:
                            data = json.loads(r.read().decode('utf-8'))
                            if data.get("ok"):
                                user_item = data.get("user")
                    except Exception:
                        pass

                if not user_item:
                    if is_single:
                        return {
                            "status": "error",
                            "data": {},
                            "error_message": f"User not found: {u}"
                        }
                    continue

                # Process user data
                user_data = user_item
                profile = user_data.get("profile", {})

                # Format response (inline)
                user_info = {
                    "id": user_data.get("id"),
                    "name": user_data.get("name"),
                    "username": user_data.get("name"),
                    "real_name": profile.get("real_name", ""),
                    "display_name": profile.get("display_name", ""),
                    "email": profile.get("email", ""),
                    "image_24": profile.get("image_24", ""),
                    "image_32": profile.get("image_32", ""),
                    "image_48": profile.get("image_48", ""),
                    "image_72": profile.get("image_72", ""),
                    "image_192": profile.get("image_192", ""),
                    "image_512": profile.get("image_512", ""),
                    "status_text": profile.get("status_text", ""),
                    "status_emoji": profile.get("status_emoji", ""),
                    "is_admin": user_data.get("is_admin", False),
                    "is_owner": user_data.get("is_owner", False),
                    "is_bot": user_data.get("is_bot", False),
                    "deleted": user_data.get("deleted", False),
                    "tz": user_data.get("tz"),
                    "tz_label": user_data.get("tz_label"),
                    "tz_offset": user_data.get("tz_offset")
                }

                resolved_users.append(user_info)

            # Return appropriate structure
            if is_single:
                return {
                    "status": "ok",
                    "data": {
                        "user": resolved_users[0] if resolved_users else {}
                    }
                }
            else:
                return {
                    "status": "ok",
                    "data": {
                        "users": resolved_users
                    }
                }

        # Otherwise, list all users
        url = "https://slack.com/api/users.list"
        params = {"limit": str(limit)}
        if include_deleted:
            params["include_deleted"] = "true"

        query_string = urllib.parse.urlencode(params)
        req = urllib.request.Request(
            f"{url}?{query_string}",
            headers={"Authorization": f"Bearer {TOKEN}"}
        )

        with urllib.request.urlopen(req, timeout=30) as r:
            data = json.loads(r.read().decode('utf-8'))

            if not data.get("ok"):
                return {
                    "status": "error",
                    "data": {},
                    "error_message": data.get("error", "Unknown Slack API error")
                }

            members = data.get("members", [])

            # Filter deleted if not requested
            if not include_deleted:
                members = [m for m in members if not m.get("deleted", False)]

            # Format users (inline)
            formatted_users = []
            for member in members:
                profile = member.get("profile", {})
                formatted_users.append({
                    "id": member.get("id"),
                    "name": member.get("name"),
                    "username": member.get("name"),
                    "real_name": profile.get("real_name", ""),
                    "display_name": profile.get("display_name", ""),
                    "email": profile.get("email", ""),
                    "image_24": profile.get("image_24", ""),
                    "image_32": profile.get("image_32", ""),
                    "image_48": profile.get("image_48", ""),
                    "image_72": profile.get("image_72", ""),
                    "image_192": profile.get("image_192", ""),
                    "image_512": profile.get("image_512", ""),
                    "status_text": profile.get("status_text", ""),
                    "status_emoji": profile.get("status_emoji", ""),
                    "is_admin": member.get("is_admin", False),
                    "is_owner": member.get("is_owner", False),
                    "is_bot": member.get("is_bot", False),
                    "deleted": member.get("deleted", False),
                    "tz": member.get("tz"),
                    "tz_label": member.get("tz_label"),
                    "tz_offset": member.get("tz_offset")
                })

            return {
                "status": "ok",
                "data": {
                    "users": formatted_users,
                    "total": len(formatted_users)
                }
            }

    except Exception as e:
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error: {str(e)}\n{traceback.format_exc()}"
        }

def collect_daily_personal_activity(date: Optional[str] = None) -> str:
    """
    Collect your personal Drive activity for a specific date.

    Queries Drive API for files you own or have access to, then queries
    Drive Activity API for activity on those files. Detects activity patterns.

    Args:
        date: Date in YYYY-MM-DD format. If provided, queries exactly that date
              (including weekends). If not provided, defaults to last workday.

    Returns:
        str: JSON string containing your personal activity data with patterns
    """
    import subprocess
    import json
    import time
    import os
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60
    MY_EMAIL = os.getenv("MY_EMAIL", "cdorsey@concord.org")

    try:
        # Determine target date
        if date:
            # User provided a specific date - use it exactly as requested
            target_date = datetime.strptime(date, "%Y-%m-%d")
            date_str = target_date.strftime("%Y-%m-%d")
        else:
            # No date provided - default to last workday (inline)
            target_date = datetime.now() - timedelta(days=1)
            while target_date.weekday() >= 5:
                target_date -= timedelta(days=1)
            date_str = target_date.strftime("%Y-%m-%d")

        # Use Admin Reports API filtered by your email - much faster than querying all files
        start_time = f"{date_str}T00:00:00Z"
        end_time = f"{date_str}T23:59:59Z"

        # Query Admin Reports API via gws CLI with pagination
        all_activities = []
        next_page_token = None

        while True:
            _params = {
                "userKey": MY_EMAIL,
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return json.dumps({
                    "error": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}",
                    "type": "error"
                })
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            all_activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        activities = all_activities

        # Analyze your activity
        my_documents = {}
        total_edits = 0
        total_views = 0
        doc_ids_to_fetch = set()

        for activity in activities:
            for event in activity.get("events", []):
                event_name = event.get("name", "unknown")

                doc_id = None
                doc_title = "(untitled)"
                owner = None

                for param in event.get("parameters", []):
                    param_name = param.get("name")
                    param_value = param.get("value")

                    if param_name == "doc_id":
                        doc_id = param_value
                    elif param_name == "doc_title":
                        doc_title = param_value
                    elif param_name == "owner":
                        owner = param_value

                if doc_id:
                    if doc_id not in my_documents:
                        my_documents[doc_id] = {
                            "doc_id": doc_id,
                            "title": doc_title,
                            "owner": owner,
                            "link": "",
                            "edit_count": 0,
                            "view_count": 0,
                            "total_engagement": 0,
                        }
                        doc_ids_to_fetch.add(doc_id)

                    if event_name == "edit":
                        my_documents[doc_id]["edit_count"] += 1
                        total_edits += 1
                    elif event_name == "view":
                        my_documents[doc_id]["view_count"] += 1
                        total_views += 1

                    my_documents[doc_id]["total_engagement"] = (
                        my_documents[doc_id]["edit_count"] + my_documents[doc_id]["view_count"]
                    )

        # Only fetch links for top 50 documents
        top_doc_ids = sorted(
            doc_ids_to_fetch,
            key=lambda x: my_documents[x]["total_engagement"],
            reverse=True
        )[:50]

        # Fetch links and check accessibility via gws
        for doc_id in top_doc_ids:
            _cmd = ["gws"] + "drive files get".split()
            _cmd.extend(["--params", json.dumps({
                "fileId": doc_id,
                "fields": "id,name,webViewLink,shared,capabilities",
                "supportsAllDrives": True,
            })])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)
            if _r.returncode != 0:
                _err = _r.stderr or ""
                if "404" in _err or "notFound" in _err:
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                    my_documents[doc_id]["access_error"] = "deleted"
                elif "403" in _err or "forbidden" in _err.lower():
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                    my_documents[doc_id]["access_error"] = "no_access"
                else:
                    my_documents[doc_id]["is_accessible"] = False
                    my_documents[doc_id]["link"] = ""
                continue
            try:
                file = json.loads(_r.stdout) if _r.stdout.strip() else {}
            except Exception:
                my_documents[doc_id]["is_accessible"] = False
                my_documents[doc_id]["link"] = ""
                continue
            if file:
                my_documents[doc_id]["link"] = file.get("webViewLink", "")
                my_documents[doc_id]["is_accessible"] = True
                my_documents[doc_id]["is_shared"] = file.get("shared", False)
                if file.get("name") and not my_documents[doc_id]["title"]:
                    my_documents[doc_id]["title"] = file.get("name")

        # Sort by engagement and format titles
        top_documents = sorted(
            my_documents.values(),
            key=lambda x: x["total_engagement"],
            reverse=True
        )[:20]

        # Format display titles based on accessibility
        for doc in top_documents:
            title = doc.get("title", "(untitled)")
            is_accessible = doc.get("is_accessible", False)
            access_error = doc.get("access_error", "")

            if not is_accessible:
                if access_error == "deleted":
                    doc["display_title"] = f"{title} - Deleted"
                elif access_error == "no_access":
                    doc["display_title"] = f"{title} - Not shared"
                else:
                    doc["display_title"] = f"{title} - Not accessible"
            else:
                doc["display_title"] = title

        result = {
            "type": "drive_analytics_personal",
            "date": date_str,
            "is_workday": True,
            "my_activity": {
                "total_activities": len(activities),
                "total_edits": total_edits,
                "total_views": total_views,
                "documents_engaged": len(my_documents),
                "top_documents": top_documents,
                "activity_patterns": {
                    "viewed_then_stopped": [],
                    "began_editing_recently": [],
                    "started_editing_then_stopped": [],
                    "view_most_regularly": [],
                    "multiple_views_per_day": [],
                },
            },
        }

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error collecting personal activity: {str(e)}",
            "type": "error"
        })

def collect_daily_workspace_activity(date: Optional[str] = None) -> str:
    """
    Collect workspace-wide Drive activity for a specific date.

    Queries Admin Reports API for all Drive activity on the specified date,
    aggregates by activity type, document, and user, and returns top-five lists.

    IMPORTANT: Always pass the 'date' parameter when the user requests data for a specific date.
    For example, if the user asks for November 10, 2025, call this function with date='2025-11-10'.

    Args:
        date: Date in YYYY-MM-DD format (e.g., '2025-11-10'). REQUIRED when user requests a specific date.
              If provided, queries exactly that date (including weekends).
              If not provided, defaults to last workday (which may not be what the user wants).

    Returns:
        str: JSON string containing workspace activity data with top-five lists. The JSON includes
             a 'date' field showing which date was actually queried.
    """
    import subprocess
    import json
    import time
    import os
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60

    try:
        # Determine target date
        if date:
            # User provided a specific date - use it exactly as requested
            try:
                target_date = datetime.strptime(date, "%Y-%m-%d")
                date_str = target_date.strftime("%Y-%m-%d")
            except ValueError as e:
                return json.dumps({
                    "error": f"Invalid date format: '{date}'. Expected YYYY-MM-DD format (e.g., '2025-11-10'). Error: {str(e)}",
                    "type": "error"
                })
        else:
            # No date provided - default to last workday (inline _get_last_workday)
            target_date = datetime.now() - timedelta(days=1)
            while target_date.weekday() >= 5:
                target_date -= timedelta(days=1)
            date_str = target_date.strftime("%Y-%m-%d")

        # Note: We query the exact date requested, even if it's a weekend
        # The API will return whatever data exists for that date
        start_time = f"{date_str}T00:00:00Z"
        end_time = f"{date_str}T23:59:59Z"

        # Query Admin Reports API via gws CLI with pagination
        all_activities = []
        next_page_token = None

        while True:
            _params = {
                "userKey": "all",
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return json.dumps({
                    "error": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}",
                    "type": "error"
                })
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            all_activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        activities = all_activities

        # Analyze activities
        activity_types = {}
        actors = set()
        documents = {}

        # Track by category for top-five lists
        edit_counts = {}
        share_counts = {}
        comment_counts = {}
        view_counts = {}
        user_counts = {}

        for activity in activities:
            actor_email = activity.get("actor", {}).get("email", "(unknown)")
            actors.add(actor_email)
            user_counts[actor_email] = user_counts.get(actor_email, 0) + 1

            for event in activity.get("events", []):
                event_name = event.get("name", "unknown")
                activity_types[event_name] = activity_types.get(event_name, 0) + 1

                # Extract document info
                doc_id = None
                doc_title = "(untitled)"
                owner = None

                for param in event.get("parameters", []):
                    param_name = param.get("name")
                    param_value = param.get("value")

                    if param_name == "doc_id":
                        doc_id = param_value
                    elif param_name == "doc_title":
                        doc_title = param_value
                    elif param_name == "owner":
                        owner = param_value

                if doc_id:
                    if doc_id not in documents:
                        documents[doc_id] = {
                            "doc_id": doc_id,
                            "title": doc_title,
                            "owner": owner,
                            "edit_count": 0,
                            "share_count": 0,
                            "comment_count": 0,
                            "view_count": 0,
                            "link": "",  # Will be populated if accessible
                            "is_accessible": False,  # Will be checked later
                            "is_shared": False,  # Will be checked later
                            "access_error": "",  # Will be set if not accessible
                        }

                    # Categorize by event type
                    if event_name == "edit":
                        documents[doc_id]["edit_count"] += 1
                        edit_counts[doc_id] = edit_counts.get(doc_id, 0) + 1
                    elif event_name in ["change_user_access", "change_acl_editors",
                                       "change_document_visibility", "change_document_access_scope"]:
                        documents[doc_id]["share_count"] += 1
                        share_counts[doc_id] = share_counts.get(doc_id, 0) + 1
                    elif event_name in ["create_comment", "resolve_comment", "delete_comment", "edit_comment"]:
                        documents[doc_id]["comment_count"] += 1
                        comment_counts[doc_id] = comment_counts.get(doc_id, 0) + 1
                    elif event_name == "view":
                        documents[doc_id]["view_count"] += 1
                        view_counts[doc_id] = view_counts.get(doc_id, 0) + 1

        # Fetch links and check accessibility for top documents
        # Only check top 25 documents to avoid too many API calls
        top_doc_ids = sorted(
            list(documents.keys()),
            key=lambda x: (
                documents[x].get("edit_count", 0) +
                documents[x].get("view_count", 0) +
                documents[x].get("share_count", 0) +
                documents[x].get("comment_count", 0)
            ),
            reverse=True
        )[:25]

        # Check accessibility and fetch links for top documents via gws
        for doc_id in top_doc_ids:
            _cmd = ["gws"] + "drive files get".split()
            _cmd.extend(["--params", json.dumps({
                "fileId": doc_id,
                "fields": "id,name,webViewLink,shared,capabilities",
                "supportsAllDrives": True,
            })])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)
            if _r.returncode != 0:
                _err = _r.stderr or ""
                if "404" in _err or "notFound" in _err:
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                    documents[doc_id]["access_error"] = "deleted"
                elif "403" in _err or "forbidden" in _err.lower():
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                    documents[doc_id]["access_error"] = "no_access"
                else:
                    documents[doc_id]["is_accessible"] = False
                    documents[doc_id]["link"] = ""
                continue
            try:
                file = json.loads(_r.stdout) if _r.stdout.strip() else {}
            except Exception:
                documents[doc_id]["is_accessible"] = False
                documents[doc_id]["link"] = ""
                continue
            if file:
                documents[doc_id]["link"] = file.get("webViewLink", "")
                documents[doc_id]["is_accessible"] = True
                documents[doc_id]["is_shared"] = file.get("shared", False)
                if file.get("name") and not documents[doc_id].get("title"):
                    documents[doc_id]["title"] = file.get("name")

        # Generate top-five lists (inlined - no nested def for Letta compliance)
        top_edited = []
        for doc_id, cnt in sorted(edit_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_edited.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_shared = []
        for doc_id, cnt in sorted(share_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_shared.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_commented = []
        for doc_id, cnt in sorted(comment_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_commented.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        top_viewed = []
        for doc_id, cnt in sorted(view_counts.items(), key=lambda x: x[1], reverse=True)[:5]:
            doc_info = documents.get(doc_id, {})
            title = doc_info.get("title", "(untitled)")
            is_accessible = doc_info.get("is_accessible", False)
            access_error = doc_info.get("access_error", "")
            if not is_accessible:
                if access_error == "deleted":
                    display_title = f"{title} - Deleted"
                elif access_error == "no_access":
                    display_title = f"{title} - Not shared"
                else:
                    display_title = f"{title} - Not accessible"
            else:
                display_title = title
            top_viewed.append({
                "doc_id": doc_id, "title": title, "display_title": display_title,
                "owner": doc_info.get("owner", "(unknown)"), "count": cnt,
                "link": doc_info.get("link", "") if is_accessible else "",
                "is_accessible": is_accessible, "is_shared": doc_info.get("is_shared", False),
            })

        # Top active users
        top_users = sorted(user_counts.items(), key=lambda x: x[1], reverse=True)[:5]
        top_active_users = [{"email": email, "activity_count": count} for email, count in top_users]

        result = {
            "type": "drive_analytics_daily",
            "date": date_str,
            "is_workday": target_date.weekday() < 5,
            "date_requested": date if date else None,  # Show what was requested vs what was used
            "summary": {
                "total_activities": len(activities),
                "unique_users": len(actors),
                "unique_documents": len(documents),
            },
            "top_activity_types": [
                {"type": k, "count": v}
                for k, v in sorted(activity_types.items(), key=lambda x: x[1], reverse=True)
            ],
            "top_five": {
                "most_edited": top_edited,
                "most_shared": top_shared,
                "most_commented": top_commented,
                "most_viewed": top_viewed,
                "most_active_users": top_active_users,
            },
        }

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error collecting workspace activity: {str(e)}",
            "type": "error"
        })

def get_email_analytics(
    start_datetime: str,
    end_datetime: str,
    mode: str = "org",
    quartile_pin_metric: Optional[str] = None,
    special_accounts: Optional[List[str]] = None,
    output_format: str = "json"
) -> Dict[str, Any]:
    """
    Get anonymized email analytics for the organization.

    Provides privacy-preserving email activity metrics. Users are identified
    by cryptographic hashes that rotate daily at 3:00 AM Eastern.

    Args:
        start_datetime: Start of period in ISO 8601 format (e.g., "2025-12-24T09:00:00-05:00")
        end_datetime: End of period in ISO 8601 format
        mode: Analysis mode - "org" (totals), "quartile" (grouped), "individual" (per-user)
        quartile_pin_metric: For quartile mode, pin groupings to one metric:
                            "sent", "received", "ratio", or "activity"
        special_accounts: Optional list of non-staff accounts to track separately
                         (e.g., ["support@concord.org"]). These are NOT anonymized.
        output_format: "json" (default) or "csv" (only for individual mode)

    Returns:
        Dict with:
        - status: "ok" or "error"
        - data: Analytics results based on mode
        - special_accounts: Non-anonymized stats for special accounts (if provided)

    Examples:
        # Org-wide totals for last week
        get_email_analytics(start_datetime="2025-12-17T00:00:00-05:00", 
                           end_datetime="2025-12-24T00:00:00-05:00", mode="org")

        # Quartile analysis pinned by send count
        get_email_analytics(..., mode="quartile", quartile_pin_metric="sent")

        # Individual anonymized stats
        get_email_analytics(..., mode="individual")
    """
    # Imports inside function (Letta compliance - must be fully self-contained)
    import json
    import hashlib
    import subprocess
    from datetime import datetime, timedelta, date
    import pytz

    # Configuration (inlined for Letta compliance)
    _HASH_SECRET_SALT = "cc-email-analytics-v1-2025-xK9mP2qR"
    CURRENT_STAFF = frozenset([
        "emcelroy@concord.org", "kswenson@concord.org", "scytacki@concord.org",
        "phorwitz@concord.org", "hlee@concord.org", "tlord@concord.org",
        "ddamelin@concord.org", "jraiff@concord.org", "cmcintyre@concord.org",
        "wfinzer@concord.org", "kbrown@concord.org", "lbondaryk@concord.org",
        "jchao@concord.org", "apallant@concord.org", "clore@concord.org",
        "kmiller@concord.org", "kjesseneller@concord.org", "rellis@concord.org",
        "tfristoe@concord.org", "lbuoncuore@concord.org", "dkehoe@concord.org",
        "sbrau@concord.org", "dmartin@concord.org", "lstephens@concord.org",
        "mtirenin@concord.org", "awagh@concord.org", "cdorsey@concord.org",
    ])

    try:
        # Validate mode
        if mode not in ["org", "quartile", "individual"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid mode '{mode}'. Must be 'org', 'quartile', or 'individual'."
            }

        # Validate quartile_pin_metric
        if quartile_pin_metric and quartile_pin_metric not in ["sent", "received", "ratio", "activity"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid quartile_pin_metric '{quartile_pin_metric}'. Must be 'sent', 'received', 'ratio', or 'activity'."
            }

        # Validate output_format
        if output_format not in ["json", "csv"]:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid output_format '{output_format}'. Must be 'json' or 'csv'."
            }

        if output_format == "csv" and mode != "individual":
            return {
                "status": "error",
                "data": {},
                "error_message": "CSV output is only available for 'individual' mode."
            }

        # Validate special accounts are not in staff list
        if special_accounts:
            staff_in_special = [a for a in special_accounts if a.lower() in CURRENT_STAFF]
            if staff_in_special:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Special accounts cannot include staff members: {staff_in_special}"
                }

        # Parse datetimes
        try:
            start_dt = datetime.fromisoformat(start_datetime)
            end_dt = datetime.fromisoformat(end_datetime)
        except ValueError as e:
            return {
                "status": "error",
                "data": {},
                "error_message": f"Invalid datetime format. Use ISO 8601 (e.g., '2025-12-24T09:00:00-05:00'). Error: {e}"
            }

        # Check 30-day limit
        if (end_dt - start_dt).days > 30:
            return {
                "status": "error",
                "data": {},
                "error_message": "Query period cannot exceed 30 days (API limitation)."
            }

        # Ensure minimum 5-minute interval
        if (end_dt - start_dt).total_seconds() < 300:
            return {
                "status": "error",
                "data": {},
                "error_message": "Query period must be at least 5 minutes."
            }

        # Get current hash date (changes at 3AM Eastern)
        eastern = pytz.timezone('US/Eastern')
        now_eastern = datetime.now(eastern)
        if now_eastern.hour < 3:
            hash_date = (now_eastern - timedelta(days=1)).date()
        else:
            hash_date = now_eastern.date()

        # Format times for API
        start_time = start_dt.strftime("%Y-%m-%dT%H:%M:%S.000Z") if start_dt.tzinfo is None else start_dt.astimezone(pytz.UTC).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        end_time = end_dt.strftime("%Y-%m-%dT%H:%M:%S.000Z") if end_dt.tzinfo is None else end_dt.astimezone(pytz.UTC).strftime("%Y-%m-%dT%H:%M:%S.000Z")

        # Query Admin Reports API for Gmail activity via gws CLI
        GWS_TIMEOUT = 60

        activities = []
        next_page_token = None
        MAX_PAGES = 50
        pages_fetched = 0

        while pages_fetched < MAX_PAGES:
            _params = {
                "userKey": "all",
                "applicationName": "gmail",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}"
                }

            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            activities.extend(_data.get("items", []))
            next_page_token = _data.get("nextPageToken")
            pages_fetched += 1
            if not next_page_token:
                break

        # Process activities - count sent/received per user
        user_stats = {}  # email -> {"sent": 0, "received": 0}
        special_stats = {}  # email -> {"sent": 0, "received": 0}
        special_set = set(a.lower() for a in (special_accounts or []))

        for activity in activities:
            actor_email = activity.get("actor", {}).get("email", "").lower()

            for event in activity.get("events", []):
                event_name = event.get("name", "")

                # Extract mail event type from nested parameters
                # Structure: parameters[].messageValue.parameter[].intValue where name="mail_event_type"
                mail_event_type = None
                for param in event.get("parameters", []):
                    if param.get("name") == "event_info":
                        msg_value = param.get("messageValue", {})
                        for p in msg_value.get("parameter", []):
                            if p.get("name") == "mail_event_type":
                                mail_event_type = p.get("intValue")
                                break
                        break

                # Determine if sent or received (1=sent, 2=received)
                is_sent = mail_event_type == "1"
                is_received = mail_event_type == "2"

                if not (is_sent or is_received):
                    continue

                # Check if special account
                if actor_email in special_set:
                    if actor_email not in special_stats:
                        special_stats[actor_email] = {"sent": 0, "received": 0}
                    if is_sent:
                        special_stats[actor_email]["sent"] += 1
                    if is_received:
                        special_stats[actor_email]["received"] += 1
                    continue

                # Check if current staff
                if actor_email not in CURRENT_STAFF:
                    continue

                # Track stats
                if actor_email not in user_stats:
                    user_stats[actor_email] = {"sent": 0, "received": 0}

                if is_sent:
                    user_stats[actor_email]["sent"] += 1
                if is_received:
                    user_stats[actor_email]["received"] += 1

        # Calculate derived metrics for each user (inlined for Letta compliance)
        user_metrics = []
        for email, stats in user_stats.items():
            sent = stats["sent"]
            received = stats["received"]
            # Inline ratio calculation
            ratio = 9999999999.0 if received == 0 else round(sent / received, 4)
            # Inline hash calculation
            hash_data = f"{email.lower()}:{hash_date}:{_HASH_SECRET_SALT}"
            user_hash = hashlib.sha256(hash_data.encode()).hexdigest()[:8]
            user_metrics.append({
                "email": email,
                "hash": user_hash,
                "sent": sent,
                "received": received,
                "ratio": ratio,
                "activity": sent + received,
            })

        # Build response based on mode
        result = {
            "status": "ok",
            "data": {
                "period": {
                    "start": start_datetime,
                    "end": end_datetime,
                },
                "hash_date": str(hash_date),
                "truncated": pages_fetched >= MAX_PAGES,
            }
        }

        if mode == "org":
            # Aggregate totals
            total_sent = sum(u["sent"] for u in user_metrics)
            total_received = sum(u["received"] for u in user_metrics)
            org_ratio = 9999999999.0 if total_received == 0 else round(total_sent / total_received, 4)
            result["data"]["org_totals"] = {
                "sent": total_sent,
                "received": total_received,
                "ratio": org_ratio,
                "activity": total_sent + total_received,
            }
            result["data"]["user_count"] = len(user_metrics)

        elif mode == "quartile":
            # Quartile analysis (inlined for Letta compliance - no nested functions)
            n = len(user_metrics)
            if n == 0:
                result["data"]["quartiles"] = {}
                result["data"]["user_count"] = 0
            else:
                metrics_list = ["sent", "received", "ratio", "activity"]

                # Calculate quartile boundaries
                q_size = n // 4
                remainder = n % 4
                q_boundaries = []
                start_idx = 0
                for i in range(4):
                    size = q_size + (1 if i < remainder else 0)
                    q_boundaries.append((start_idx, start_idx + size))
                    start_idx += size

                if quartile_pin_metric:
                    # Pinned mode - one grouping, all metrics
                    sorted_users = sorted(
                        user_metrics,
                        key=lambda x: (-x[quartile_pin_metric], x["hash"])
                    )

                    result["data"]["pinned_by"] = quartile_pin_metric
                    result["data"]["quartiles"] = {}

                    for i, (start, end) in enumerate(q_boundaries):
                        q_name = f"Q{i+1}"
                        q_users = sorted_users[start:end]
                        n_users = len(q_users)

                        q_stats = {"user_count": n_users}
                        for m in metrics_list:
                            if n_users == 0:
                                if m == "ratio":
                                    q_stats[m] = {"avg": 0}
                                else:
                                    q_stats[m] = {"count": 0, "avg": 0}
                            else:
                                values = [u[m] for u in q_users]
                                total = sum(values)
                                avg = round(total / n_users, 2)
                                if m == "ratio":
                                    q_stats[m] = {"avg": avg}
                                else:
                                    q_stats[m] = {"count": total, "avg": avg}

                        result["data"]["quartiles"][q_name] = q_stats
                else:
                    # Default mode - each metric has its own grouping
                    result["data"]["quartiles"] = {}

                    for metric in metrics_list:
                        sorted_users = sorted(
                            user_metrics,
                            key=lambda x: (-x[metric], x["hash"])
                        )

                        result["data"]["quartiles"][f"by_{metric}"] = {}

                        for i, (start, end) in enumerate(q_boundaries):
                            q_name = f"Q{i+1}"
                            q_users = sorted_users[start:end]
                            n_users = len(q_users)

                            if n_users == 0:
                                if metric == "ratio":
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": 0, "avg": 0}
                                else:
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": 0, "count": 0, "avg": 0}
                            else:
                                values = [u[metric] for u in q_users]
                                total = sum(values)
                                avg = round(total / n_users, 2)
                                if metric == "ratio":
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": n_users, "avg": avg}
                                else:
                                    result["data"]["quartiles"][f"by_{metric}"][q_name] = {"user_count": n_users, "count": total, "avg": avg}

                result["data"]["user_count"] = n

        elif mode == "individual":
            # Individual anonymized stats
            # Sort by hash for consistent ordering
            sorted_users = sorted(user_metrics, key=lambda x: x["hash"])

            if output_format == "csv":
                # Build CSV string
                csv_lines = ["hash,sent,received,ratio,activity"]
                for u in sorted_users:
                    csv_lines.append(f"{u['hash']},{u['sent']},{u['received']},{u['ratio']},{u['activity']}")
                result["data"]["csv"] = "\n".join(csv_lines)
            else:
                # JSON format - remove email, keep only hash
                result["data"]["users"] = [
                    {
                        "hash": u["hash"],
                        "sent": u["sent"],
                        "received": u["received"],
                        "ratio": u["ratio"],
                        "activity": u["activity"],
                    }
                    for u in sorted_users
                ]

            result["data"]["user_count"] = len(sorted_users)

        # Add special accounts if provided
        if special_accounts:
            result["special_accounts"] = [
                {
                    "account": account,
                    "sent": special_stats.get(account.lower(), {}).get("sent", 0),
                    "received": special_stats.get(account.lower(), {}).get("received", 0),
                }
                for account in special_accounts
            ]

        return result

    except Exception as e:
        import traceback
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error in email analytics: {str(e)}\n{traceback.format_exc()}"
        }

def get_drive_file_info(drive_url: str) -> str:
    """
    Get document or folder title and metadata from a Google Drive URL.

    Extracts the file ID from a Google Drive URL and retrieves file/folder information
    including title, owner, creation date, modification date, sharing status, etc.
    Works for both files and folders.

    Args:
        drive_url: Google Drive URL in any format:
                   - https://docs.google.com/document/d/FILE_ID/edit
                   - https://drive.google.com/file/d/FILE_ID/view
                   - https://drive.google.com/drive/folders/FILE_ID
                   - https://drive.google.com/open?id=FILE_ID
                   - etc.

    Returns:
        str: JSON string with file/folder metadata or error message

    Example:
        get_drive_file_info("https://docs.google.com/document/d/1abc123xyz/edit")
        # Returns: {"title": "Document Name", "owner": "user@example.com", ...}

        get_drive_file_info("https://drive.google.com/drive/folders/1abc123xyz")
        # Returns: {"title": "Folder Name", "mime_type": "application/vnd.google-apps.folder", ...}
    """
    import re
    import subprocess
    import json
    from datetime import datetime

    try:
        # Extract file ID from various Google Drive URL formats
        file_id = None

        # Pattern 1: /folders/FILE_ID (for folder URLs)
        match = re.search(r'/folders/([a-zA-Z0-9_-]+)', drive_url)
        if match:
            file_id = match.group(1)

        # Pattern 2: /d/FILE_ID/ or /file/d/FILE_ID/ (for file/document URLs)
        if not file_id:
            match = re.search(r'/d/([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 3: ?id=FILE_ID
        if not file_id:
            match = re.search(r'[?&]id=([a-zA-Z0-9_-]+)', drive_url)
            if match:
                file_id = match.group(1)

        # Pattern 4: FILE_ID directly (if URL is just the ID)
        if not file_id:
            if re.match(r'^[a-zA-Z0-9_-]+$', drive_url):
                file_id = drive_url

        if not file_id:
            return json.dumps({
                "error": "Could not extract file ID from URL",
                "url": drive_url,
                "message": "Please provide a valid Google Drive URL (e.g., https://docs.google.com/document/d/FILE_ID/edit)"
            }, indent=2)

        # Query Drive API via gws CLI
        _cmd = ["gws"] + "drive files get".split()
        _cmd.extend(["--params", json.dumps({
            "fileId": file_id,
            "fields": "id,name,mimeType,createdTime,modifiedTime,owners,shared,webViewLink,webContentLink,size,permissions,capabilities,description,starred,trashed",
            "supportsAllDrives": True,
        })])
        _cmd.extend(["--format", "json"])
        _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=15)

        if _r.returncode != 0:
            _err = _r.stderr or ""
            if "404" in _err or "notFound" in _err:
                return json.dumps({
                    "error": "File not found",
                    "file_id": file_id,
                    "message": "The file does not exist or has been deleted. You may not have access to this file."
                }, indent=2)
            elif "403" in _err or "forbidden" in _err.lower():
                return json.dumps({
                    "error": "Access denied",
                    "file_id": file_id,
                    "message": "You do not have permission to access this file. The file may not be shared with you."
                }, indent=2)
            else:
                return json.dumps({
                    "error": f"Drive API error",
                    "file_id": file_id,
                    "message": _err[:500] if _err else f"gws exit {_r.returncode}"
                }, indent=2)

        file = json.loads(_r.stdout) if _r.stdout.strip() else {}

        # Format response
        owners = file.get("owners", [])
        owner_emails = [owner.get("emailAddress", "unknown") for owner in owners]
        owner_names = [owner.get("displayName", "unknown") for owner in owners]

        mime_type = file.get("mimeType", "unknown")
        is_folder = mime_type == "application/vnd.google-apps.folder"

        result = {
            "success": True,
            "file_id": file.get("id"),
            "title": file.get("name", "(untitled)"),
            "mime_type": mime_type,
            "is_folder": is_folder,
            "created_time": file.get("createdTime"),
            "modified_time": file.get("modifiedTime"),
            "owners": owner_emails,
            "owner_names": owner_names,
            "shared": file.get("shared", False),
            "web_view_link": file.get("webViewLink", ""),
            "web_content_link": file.get("webContentLink", ""),
            "size_bytes": file.get("size"),
            "description": file.get("description", ""),
            "starred": file.get("starred", False),
            "trashed": file.get("trashed", False),
            "capabilities": file.get("capabilities", {}),
        }

        # Format dates for readability
        if result["created_time"]:
            try:
                created_dt = datetime.fromisoformat(result["created_time"].replace('Z', '+00:00'))
                result["created_date"] = created_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        if result["modified_time"]:
            try:
                modified_dt = datetime.fromisoformat(result["modified_time"].replace('Z', '+00:00'))
                result["modified_date"] = modified_dt.strftime("%Y-%m-%d %H:%M:%S")
            except Exception:
                pass

        # Format size
        if result["size_bytes"]:
            size = int(result["size_bytes"])
            if size < 1024:
                result["size"] = f"{size} bytes"
            elif size < 1024 * 1024:
                result["size"] = f"{size / 1024:.1f} KB"
            else:
                result["size"] = f"{size / (1024 * 1024):.1f} MB"

        return json.dumps(result, indent=2)

    except Exception as e:
        return json.dumps({
            "error": f"Error processing URL: {str(e)}",
            "url": drive_url
        }, indent=2)

def search_slack_messages(
    query: Optional[str] = None,
    user: Optional[str] = None,
    channel: Optional[str] = None,
    saved_only: Optional[bool] = False,
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    count: Optional[int] = 20,
    sort: Optional[str] = "score",
    sort_by: Optional[str] = None,
    min_reactions: Optional[str] = None,
    min_reply_count: Optional[str] = None,
    only_thread_parents: Optional[str] = None,
    has_reactions: Optional[str] = None,
    is_dm: Optional[str] = None
) -> Dict[str, Any]:
    """
    Search for messages across the entire Slack workspace, or retrieve saved/bookmarked items.

    When saved_only=True, returns items you've saved for later (starred/bookmarked).
    When query is omitted or empty, returns recent messages across workspace.
    Supports filtering by user(s) and/or channel(s) using Slack's query syntax.

    Query Syntax: "term1 term2" (AND), "term1 OR term2", "NOT term", '"exact phrase"', "prefix*" (wildcard), "@username" (mentions).

    @-Mentions: Use "@username" in query to find messages mentioning a user. Combine with filters as needed.

    Automatic Handling: OR queries with user/channel filters are automatically split into separate
    searches and combined (Slack API treats OR as AND when filters present).

    Known Limitation: Prefix wildcards "*term" match literal, not wildcard. Use "term*" instead.

    Args:
        query: Search query string. Supports @username for mentions. When saved_only=True, filters saved items by query. Default: None.
        user: User ID(s) or username(s) (e.g., "sue" or "sue,dan"). Use usernames for efficiency. Default: None.
        channel: Channel ID(s) or name(s) (e.g., "#random" or "#general,#random"). Use names for efficiency. Default: None.
        saved_only: When True, returns only saved/bookmarked items instead of searching all messages. Default: False.
        start_date: Start date in YYYY-MM-DD format or ISO 8601 datetime. Default: None.
        end_date: End date in YYYY-MM-DD format or ISO 8601 datetime. Default: None.
        count: Maximum number of messages to return. Default: 20, max: 100.
        sort: Sort order: "score" (default) or "timestamp".
        sort_by: Additional sort criteria. Default: None.
        min_reactions: Filter messages with at least N reactions. Default: None.
        min_reply_count: Filter messages with at least N replies. Default: None.
        only_thread_parents: Return only messages that have replies. Default: False.
        has_reactions: Return only messages with reactions. Default: False.
        is_dm: Search only in direct messages. Default: False. Use with user filter for specific DM conversations.

    Returns:
        Dictionary with status, data (messages array and metadata), and error_message if applicable.
    """
    # Imports inside function at the very beginning
    import os
    import traceback
    import json
    import urllib.request
    import urllib.parse
    from datetime import datetime, timezone
    import re

    # Wrap entire function in try-except
    try:
        # Get token
        TOKEN = os.getenv("SLACK_MCP_XOXP_TOKEN", "")
        if not TOKEN:
            return {
                "status": "error",
                "data": {},
                "error_message": "SLACK_MCP_XOXP_TOKEN not set in environment"
            }

        # Set defaults and handle type conversions (Letta passes null as string "None" or actual None)
        if count is None:
            count = 20
        if sort is None:
            sort = "score"

        # Convert string bool params (workaround for Letta Optional[bool] null handling)
        # Inline conversion - no nested def allowed by Letta
        if only_thread_parents is None or only_thread_parents == "":
            only_thread_parents = False
        elif isinstance(only_thread_parents, bool):
            pass  # Already bool
        elif isinstance(only_thread_parents, str):
            only_thread_parents = only_thread_parents.lower() in ("true", "1", "yes")
        else:
            only_thread_parents = False

        if has_reactions is None or has_reactions == "":
            has_reactions = False
        elif isinstance(has_reactions, bool):
            pass  # Already bool
        elif isinstance(has_reactions, str):
            has_reactions = has_reactions.lower() in ("true", "1", "yes")
        else:
            has_reactions = False

        if is_dm is None or is_dm == "":
            is_dm = False
        elif isinstance(is_dm, bool):
            pass  # Already bool
        elif isinstance(is_dm, str):
            is_dm = is_dm.lower() in ("true", "1", "yes")
        else:
            is_dm = False

        # Convert string int params (workaround for Letta Optional[int] null handling)
        if min_reactions is None or min_reactions == "":
            min_reactions = None
        else:
            try:
                min_reactions = int(min_reactions)
            except (ValueError, TypeError):
                min_reactions = None

        if min_reply_count is None or min_reply_count == "":
            min_reply_count = None
        else:
            try:
                min_reply_count = int(min_reply_count)
            except (ValueError, TypeError):
                min_reply_count = None

        # Limit max
        if count > 100:
            count = 100

        # Handle saved_only parameter conversion (same pattern as other booleans)
        if saved_only is None or saved_only == "":
            saved_only = False
        elif isinstance(saved_only, bool):
            pass  # Already bool
        elif isinstance(saved_only, str):
            saved_only = saved_only.lower() in ("true", "1", "yes")
        else:
            saved_only = False

        # SAVED ITEMS PATH: Prepend is:saved to query and use search.messages
        # This uses the existing search:read scope (no stars:read needed)
        if saved_only:
            saved_prefix = "is:saved"
            if query:
                query = f"{saved_prefix} {query}"
            else:
                query = saved_prefix

        # SEARCH PATH: Build search query with user/channel filters (inline logic)
        search_query_parts = []

        # NOTE: We'll add the query text AFTER building filters
        # Only use "*" fallback if there are NO filters at all
        # (The "*" can interfere with filter-only searches)

        # Handle user filter (support multiple users with OR syntax) - inline
        if user:
            if isinstance(user, str):
                # Single user or comma-separated
                if ',' in user:
                    user_list = [u.strip() for u in user.split(',')]
                else:
                    user_list = [user]
            elif isinstance(user, list):
                # Support list for backward compatibility (though Letta schema only allows str)
                user_list = user
            else:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"user parameter must be string or list, got {type(user)}"
                }

            # Build user filters (use OR syntax for multiple)
            # Resolve user IDs to usernames for search queries (Slack search works better with usernames)
            user_filters = []
            user_cache_for_search = {}

            # First pass: collect all user IDs that need resolution
            user_ids_to_resolve = []
            for u in user_list:
                if u.startswith("U"):
                    user_ids_to_resolve.append(u)

            # Resolve user IDs to usernames
            if user_ids_to_resolve:
                try:
                    url = "https://slack.com/api/users.list"
                    params = {"limit": "1000"}
                    query_string = urllib.parse.urlencode(params)
                    req = urllib.request.Request(
                        f"{url}?{query_string}",
                        headers={"Authorization": f"Bearer {TOKEN}"}
                    )
                    with urllib.request.urlopen(req, timeout=30) as ur:
                        user_data = json.loads(ur.read().decode('utf-8'))
                        if user_data.get("ok"):
                            for user_item in user_data.get("members", []):
                                user_id = user_item.get("id")
                                if user_id in user_ids_to_resolve:
                                    user_cache_for_search[user_id] = user_item.get("name", "")
                except Exception:
                    pass

            # Build filters using usernames when available, otherwise use the provided value
            for u in user_list:
                if u.startswith("U") and u in user_cache_for_search:
                    # Use resolved username
                    user_filters.append(f"from:{user_cache_for_search[u]}")
                else:
                    # Use as-is (username or unresolved ID)
                    user_filters.append(f"from:{u}")

            if len(user_filters) == 1:
                search_query_parts.insert(0, user_filters[0])
            else:
                # Slack search API doesn't support parentheses around OR clauses
                # Use "from:user1 OR from:user2" instead of "(from:user1 OR from:user2)"
                user_query = " OR ".join(user_filters)
                search_query_parts.insert(0, user_query)

        # Handle channel filter (support multiple channels with OR syntax) - inline
        if channel:
            if isinstance(channel, str):
                # Single channel or comma-separated
                if ',' in channel:
                    channel_list = [ch.strip() for ch in channel.split(',')]
                else:
                    channel_list = [channel]
            elif isinstance(channel, list):
                # Support list for backward compatibility (though Letta schema only allows str)
                channel_list = channel
            else:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"channel parameter must be string or list, got {type(channel)}"
                }

            # Build channel filters (resolve IDs to names - Slack search requires channel names, not IDs)
            # DM channels need special handling - use "dm:username" syntax instead of "in:channel"
            channel_filters = []
            channel_id_to_name_cache = {}
            dm_channel_to_username_cache = {}  # For DM channels: channel_id -> username

            # First pass: separate DM channels from regular channels
            regular_channel_ids = []
            dm_channel_ids = []
            for ch in channel_list:
                channel_name = ch.lstrip("#")
                if channel_name.startswith("D"):
                    # DM channel - needs special handling
                    dm_channel_ids.append(channel_name)
                elif channel_name.startswith(("C", "G", "mpdm-")):
                    regular_channel_ids.append(channel_name)

            # Resolve regular channel IDs to names
            if regular_channel_ids:
                try:
                    url = "https://slack.com/api/conversations.list"
                    params = {"limit": "1000", "exclude_archived": "false"}
                    query_string = urllib.parse.urlencode(params)
                    req = urllib.request.Request(
                        f"{url}?{query_string}",
                        headers={"Authorization": f"Bearer {TOKEN}"}
                    )
                    with urllib.request.urlopen(req, timeout=30) as cr:
                        channel_data = json.loads(cr.read().decode('utf-8'))
                        if channel_data.get("ok"):
                            for ch_item in channel_data.get("channels", []):
                                ch_id = ch_item.get("id")
                                ch_name = ch_item.get("name", "")
                                if ch_id in regular_channel_ids and ch_name:
                                    channel_id_to_name_cache[ch_id] = ch_name

                    # Also try conversations.info for each ID individually (in case it's a private channel not in list)
                    for ch_id in regular_channel_ids:
                        if ch_id not in channel_id_to_name_cache:
                            try:
                                info_url = "https://slack.com/api/conversations.info"
                                info_params = {"channel": ch_id}
                                info_query = urllib.parse.urlencode(info_params)
                                info_req = urllib.request.Request(
                                    f"{info_url}?{info_query}",
                                    headers={"Authorization": f"Bearer {TOKEN}"}
                                )
                                with urllib.request.urlopen(info_req, timeout=30) as ir:
                                    info_data = json.loads(ir.read().decode('utf-8'))
                                    if info_data.get("ok"):
                                        ch_info = info_data.get("channel", {})
                                        ch_name = ch_info.get("name", "")
                                        if ch_name:
                                            channel_id_to_name_cache[ch_id] = ch_name
                            except Exception:
                                pass
                except Exception:
                    pass

            # Resolve DM channel IDs to usernames (for dm:username syntax)
            if dm_channel_ids:
                # First get user info for resolving user IDs to usernames
                user_id_to_name = {}
                try:
                    url = "https://slack.com/api/users.list"
                    params = {"limit": "1000"}
                    query_string = urllib.parse.urlencode(params)
                    req = urllib.request.Request(
                        f"{url}?{query_string}",
                        headers={"Authorization": f"Bearer {TOKEN}"}
                    )
                    with urllib.request.urlopen(req, timeout=30) as ur:
                        user_data = json.loads(ur.read().decode('utf-8'))
                        if user_data.get("ok"):
                            for user_item in user_data.get("members", []):
                                user_id_to_name[user_item.get("id")] = user_item.get("name", "")
                except Exception:
                    pass

                # Get user ID for each DM channel
                for dm_id in dm_channel_ids:
                    try:
                        info_url = "https://slack.com/api/conversations.info"
                        info_params = {"channel": dm_id}
                        info_query = urllib.parse.urlencode(info_params)
                        info_req = urllib.request.Request(
                            f"{info_url}?{info_query}",
                            headers={"Authorization": f"Bearer {TOKEN}"}
                        )
                        with urllib.request.urlopen(info_req, timeout=30) as ir:
                            info_data = json.loads(ir.read().decode('utf-8'))
                            if info_data.get("ok"):
                                ch_info = info_data.get("channel", {})
                                # DM channels have a "user" field with the other user's ID
                                dm_user_id = ch_info.get("user", "")
                                if dm_user_id and dm_user_id in user_id_to_name:
                                    dm_channel_to_username_cache[dm_id] = user_id_to_name[dm_user_id]
                                elif dm_user_id:
                                    # Fallback: use user ID if we can't resolve to name
                                    dm_channel_to_username_cache[dm_id] = dm_user_id
                    except Exception:
                        pass

            # Build filters using channel names (Slack search requires names, not IDs)
            for ch in channel_list:
                channel_name = ch.lstrip("#")
                if channel_name.startswith("D"):
                    # DM channel - use dm:username syntax
                    if channel_name in dm_channel_to_username_cache:
                        channel_filters.append(f"dm:{dm_channel_to_username_cache[channel_name]}")
                    else:
                        # Fallback: use is:dm (searches all DMs, less specific)
                        channel_filters.append("is:dm")
                elif channel_name.startswith(("C", "G", "mpdm-")):
                    # Regular channel - use in:channel_name syntax
                    if channel_name in channel_id_to_name_cache:
                        channel_filters.append(f"in:{channel_id_to_name_cache[channel_name]}")
                    else:
                        # Fallback: try using ID anyway (might work for some cases)
                        channel_filters.append(f"in:{channel_name}")
                else:
                    # It's already a channel name - use directly
                    channel_filters.append(f"in:{channel_name}")

            if len(channel_filters) == 1:
                search_query_parts.insert(0, channel_filters[0])
            else:
                # Slack search API doesn't support parentheses around OR clauses
                # Use "in:chan1 OR in:chan2" instead of "(in:chan1 OR in:chan2)"
                channel_query = " OR ".join(channel_filters)
                search_query_parts.insert(0, channel_query)

        # Add is:dm filter if requested (search only in direct messages)
        if is_dm:
            search_query_parts.insert(0, "is:dm")

        # Add date filters using Slack's on: syntax
        # Note: after:/before: combined returns 0 results (Slack API bug).
        # on: works reliably for single days and can be repeated for ranges.
        if start_date or end_date:
            from datetime import timedelta
            try:
                start_str = (start_date.split('T')[0] if start_date and 'T' in start_date
                             else start_date) if start_date else None
                end_str = (end_date.split('T')[0] if end_date and 'T' in end_date
                           else end_date) if end_date else None

                if start_str and end_str:
                    s_dt = datetime.strptime(start_str, "%Y-%m-%d")
                    e_dt = datetime.strptime(end_str, "%Y-%m-%d")
                    day_count = (e_dt - s_dt).days + 1
                    if day_count <= 31:
                        for i in range(day_count):
                            d = s_dt + timedelta(days=i)
                            search_query_parts.append(f"on:{d.strftime('%Y-%m-%d')}")
                    else:
                        search_query_parts.append(f"after:{start_str}")
                        search_query_parts.append(f"before:{(e_dt + timedelta(days=1)).strftime('%Y-%m-%d')}")
                elif start_str:
                    search_query_parts.append(f"on:{start_str}")
                elif end_str:
                    search_query_parts.append(f"on:{end_str}")
            except Exception:
                pass

        # Now add the query text (after filters are built)
        # Only use "*" fallback if there are NO filters at all
        has_filters = bool(search_query_parts)  # True if we have any from:/in:/is:dm/after:/before: filters
        if query:
            # User provided a query - add it
            search_query_parts.append(query)
        elif not has_filters:
            # No query AND no filters - need "*" to avoid Slack API error
            search_query_parts.append("*")
        # else: we have filters but no query - that's fine, filters alone work

        # Combine query parts
        final_query = " ".join(search_query_parts) if search_query_parts else ""

        # Check if we need to split OR query (workaround for Slack API limitation)
        # Slack treats "OR" as "AND" when from: or in: filters are present.
        # We split OR queries into separate searches and combine results.
        or_pattern = re.compile(r'\s+OR\s+', re.IGNORECASE)

        # Check if OR is outside quotes (inline - no nested def allowed by Letta)
        has_unquoted_or = False
        if query:
            in_quote = False
            cleaned_query = []
            for char in query:
                if char == '"':
                    in_quote = not in_quote
                elif not in_quote:
                    cleaned_query.append(char)
            has_unquoted_or = bool(or_pattern.search(''.join(cleaned_query)))

        # Split if: query has unquoted OR AND any filter is present
        needs_or_split = query and has_unquoted_or and (user or channel)

        if needs_or_split:
            # Split query into separate terms and search each
            or_terms = [term.strip() for term in or_pattern.split(query)]
            all_matches = []
            all_total = 0
            seen_message_ids = set()

            for or_term in or_terms:
                # Build query for this single term (reuse the already-built filters)
                # Extract the filter parts from search_query_parts (user and channel filters)
                term_query_parts = []
                for part in search_query_parts:
                    if part == query:
                        term_query_parts.append(or_term)
                    else:
                        term_query_parts.append(part)
                term_final_query = " ".join(term_query_parts) if term_query_parts else or_term

                # Make API call for this term
                try:
                    term_url = "https://slack.com/api/search.messages"
                    term_params = {
                        "query": term_final_query,
                        "count": str(count),
                        "sort": sort
                    }
                    term_query_string = urllib.parse.urlencode(term_params)
                    term_req = urllib.request.Request(
                        f"{term_url}?{term_query_string}",
                        headers={"Authorization": f"Bearer {TOKEN}"}
                    )
                    with urllib.request.urlopen(term_req, timeout=30) as tr:
                        term_data = json.loads(tr.read().decode('utf-8'))
                        if term_data.get("ok"):
                            term_matches = term_data.get("messages", {}).get("matches", [])
                            term_total = term_data.get("messages", {}).get("total", 0)
                            all_total += term_total

                            # Deduplicate by channel_id + ts
                            for match in term_matches:
                                match_id = f"{match.get('channel', {}).get('id', '')}_{match.get('ts', '')}"
                                if match_id not in seen_message_ids:
                                    seen_message_ids.add(match_id)
                                    all_matches.append(match)
                except Exception:
                    pass

            # Use combined results
            matches = all_matches
            total = len(all_matches)  # Use deduplicated count
            pagination = {"total_count": total, "page": 1, "per_page": count}
            final_query = f"{query} (split into {len(or_terms)} searches)"
        else:
            # Normal path: single API call
            # Build API request
            url = "https://slack.com/api/search.messages"
            params = {
                "query": final_query,
                "count": str(count),
                "sort": sort
            }

            query_string = urllib.parse.urlencode(params)
            req = urllib.request.Request(
                f"{url}?{query_string}",
                headers={"Authorization": f"Bearer {TOKEN}"}
            )

            with urllib.request.urlopen(req, timeout=30) as r:
                data = json.loads(r.read().decode('utf-8'))

                if not data.get("ok"):
                    return {
                        "status": "error",
                        "data": {},
                        "error_message": data.get("error", "Unknown Slack API error")
                    }

                matches = data.get("messages", {}).get("matches", [])
                total = data.get("messages", {}).get("total", 0)
                pagination = data.get("messages", {}).get("pagination", {})

        # Continue processing (both paths have set matches, total, pagination)
        # User cache for efficient lookups
        user_cache = {}

        # Parse dates for filtering (inline)
        start_dt = None
        end_dt = None
        if start_date:
            try:
                if 'T' in start_date or start_date.endswith('Z'):
                    start_dt = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
                else:
                    start_dt = datetime.strptime(start_date, "%Y-%m-%d")
                    start_dt = start_dt.replace(tzinfo=timezone.utc)
            except Exception:
                pass

        if end_date:
            try:
                if 'T' in end_date or end_date.endswith('Z'):
                    end_dt = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
                else:
                    end_dt = datetime.strptime(end_date, "%Y-%m-%d")
                    end_dt = end_dt.replace(tzinfo=timezone.utc)
                    end_dt = end_dt.replace(hour=23, minute=59, second=59)
            except Exception:
                pass

        # Get workspace URL and team ID for permalinks
        workspace_url = "https://concord-consortium.slack.com"
        team_id = None
        try:
            auth_url = "https://slack.com/api/auth.test"
            auth_req = urllib.request.Request(auth_url, headers={"Authorization": f"Bearer {TOKEN}"})
            with urllib.request.urlopen(auth_req, timeout=10) as ar:
                auth_data = json.loads(ar.read().decode('utf-8'))
                if auth_data.get("ok"):
                    url_value = auth_data.get("url", "")
                    if url_value:
                        # Normalize workspace URL - remove any existing https:// prefix and trailing slash
                        url_value = url_value.rstrip('/').replace('https://', '').replace('http://', '')
                        workspace_url = f"https://{url_value}"
                    # Get team ID for desktop deep links
                    team_id = auth_data.get("team_id") or (auth_data.get("team", {}).get("id") if isinstance(auth_data.get("team"), dict) else None)
        except Exception:
            pass

        # Normalize workspace_url to ensure it's clean (no double prefixes, no trailing slash)
        workspace_url = workspace_url.rstrip('/')
        if workspace_url.startswith('https://https://') or workspace_url.startswith('http://https://'):
            workspace_url = 'https://' + workspace_url.split('://', 1)[-1].split('://', 1)[-1]
        elif not workspace_url.startswith('https://'):
            workspace_url = f"https://{workspace_url}"

        # Process search results (inline)
        processed_messages = []
        for match in matches:
            ts = match.get("ts", "")
            user_id = match.get("user", "")
            text = match.get("text", "")

            # Filter by date if provided
            if start_dt or end_dt:
                try:
                    msg_dt = datetime.fromtimestamp(float(ts))
                    msg_dt = msg_dt.replace(tzinfo=timezone.utc)
                    if start_dt and msg_dt < start_dt:
                        continue
                    if end_dt and msg_dt > end_dt:
                        continue
                except Exception:
                    pass

            # Get user info (inline with cache)
            user_info = {"id": "", "username": "", "real_name": ""}
            if user_id:
                if user_id in user_cache:
                    user_info = user_cache[user_id]
                else:
                    try:
                        user_url = "https://slack.com/api/users.info"
                        user_params = {"user": user_id}
                        user_query = urllib.parse.urlencode(user_params)
                        user_req = urllib.request.Request(
                            f"{user_url}?{user_query}",
                            headers={"Authorization": f"Bearer {TOKEN}"}
                        )
                        with urllib.request.urlopen(user_req, timeout=30) as ur:
                            user_data = json.loads(ur.read().decode('utf-8'))
                            if user_data.get("ok"):
                                u_data = user_data.get("user", {})
                                profile = u_data.get("profile", {})
                                user_info = {
                                    "id": user_id,
                                    "username": u_data.get("name", ""),
                                    "real_name": profile.get("real_name", "")
                                }
                                user_cache[user_id] = user_info
                    except Exception:
                        pass

            # Convert timestamp
            dt = datetime.fromtimestamp(float(ts)) if ts else datetime.now()
            dt_iso = dt.isoformat() + "Z"

            # Build permalink (HTTPS) and desktop deep link (slack://)
            channel_id = match.get("channel", {}).get("id", "")
            permalink_ts = ts.replace('.', '')
            permalink = f"{workspace_url}/archives/{channel_id}/p{permalink_ts}"
            # Build app_redirect deep link for better browser compatibility
            desktop_link = None
            if team_id and channel_id:
                # Use app_redirect with the permalink URL for consistent browser behavior
                encoded_permalink = urllib.parse.quote(permalink, safe='')
                desktop_link = f"https://slack.com/app_redirect?team={team_id}&url={encoded_permalink}"

            # Extract files (inline)
            files = []
            for file_data in match.get("files", []):
                files.append({
                    "id": file_data.get("id"),
                    "name": file_data.get("name"),
                    "title": file_data.get("title"),
                    "mimetype": file_data.get("mimetype"),
                    "filetype": file_data.get("filetype"),
                    "size": file_data.get("size"),
                    "url_private_download": file_data.get("url_private_download"),
                    "created": file_data.get("created")
                })

            # Extract links (inline regex)
            links = []
            url_pattern = r'https?://[^\s<>"{}|\\^`\[\]]+'
            url_matches = re.finditer(url_pattern, text)
            for url_match in url_matches:
                url = url_match.group(0).rstrip('.,;:)!?')
                links.append({
                    "url": url,
                    "display_text": url,
                    "type": "link"
                })

            # Extract reactions (inline)
            reactions = []
            for reaction_data in match.get("reactions", []):
                reactions.append({
                    "name": reaction_data.get("name"),
                    "count": reaction_data.get("count"),
                    "users": reaction_data.get("users", [])
                })

            # Check thread info
            reply_count = match.get("reply_count", 0)
            is_thread_parent = reply_count > 0

            # Apply filters (inline)
            if only_thread_parents and not is_thread_parent:
                continue

            if min_reply_count is not None and reply_count < min_reply_count:
                continue

            reaction_count = sum(r.get("count", 0) for r in reactions)
            if min_reactions is not None and reaction_count < min_reactions:
                continue

            if has_reactions and len(reactions) == 0:
                continue

            processed_msg = {
                "ts": ts,
                "text": text,
                "user": user_id,
                "username": user_info.get("username", ""),
                "real_name": user_info.get("real_name", ""),
                "datetime": dt_iso,
                "permalink": permalink,
                "desktop_link": desktop_link,
                "channel_id": channel_id,
                "channel_name": match.get("channel", {}).get("name", ""),
                "thread_ts": match.get("thread_ts"),
                "is_thread_parent": is_thread_parent,
                "reply_count": reply_count,
                "reply_users_count": match.get("reply_users_count", 0),
                "reactions": reactions,
                "files": files,
                "links": links
            }

            # Add highlight if present
            if "highlight" in match:
                processed_msg["highlight"] = match["highlight"]

            processed_messages.append(processed_msg)

        # Apply post-search sort if requested (inline)
        if sort_by:
            if sort_by == "timestamp":
                processed_messages.sort(key=lambda m: float(m.get("ts", 0)), reverse=True)
            elif sort_by == "reactions":
                processed_messages.sort(key=lambda m: sum(r.get("count", 0) for r in m.get("reactions", [])), reverse=True)
            elif sort_by == "reply_count":
                processed_messages.sort(key=lambda m: m.get("reply_count", 0), reverse=True)

        return {
                "status": "ok",
                "data": {
                    "query": final_query,
                    "total_results": total,
                    "messages": processed_messages,
                    "pagination": pagination
                }
            }

    except Exception as e:
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error: {str(e)}\n{traceback.format_exc()}"
        }

def get_document_events(doc_ids: List[str], days: int = 7) -> Dict[str, Any]:
    """
    Get individual events (timeline) for specific documents.

    Returns a detailed timeline of who did what and when on specific documents.
    Use this for audit trails or understanding the sequence of activity.
    For aggregated counts, use search_drive_activity instead.

    Args:
        doc_ids: List of document IDs to query
        days: Number of days to look back (default: 7)

    Returns:
        Dict with events list (time, actor, action) and summary counts per document

    Example:
        # Get timeline for a specific document
        get_document_events(doc_ids=["1abc...xyz"])
        # Returns: {"status": "ok", "data": {"documents": [{"doc_id": "...", "events": [...]}]}}
    """
    # Imports inside function (Letta compliance)
    import subprocess
    import json
    import time
    from datetime import datetime, timedelta

    GWS_TIMEOUT = 60

    try:
        # Calculate date range
        end_date = datetime.now()
        start_date_dt = end_date - timedelta(days=days)

        start_time = start_date_dt.strftime("%Y-%m-%dT00:00:00Z")
        end_time = end_date.strftime("%Y-%m-%dT23:59:59Z")

        # Query Admin Reports API via gws CLI with pagination
        activities = []
        next_page_token = None
        MAX_PAGES = 15
        pages_fetched = 0

        while pages_fetched < MAX_PAGES:
            _params = {
                "userKey": "all",
                "applicationName": "drive",
                "startTime": start_time,
                "endTime": end_time,
                "maxResults": 1000,
            }
            if next_page_token:
                _params["pageToken"] = next_page_token

            _cmd = ["gws"] + "admin-reports activities list".split()
            _cmd.extend(["--params", json.dumps(_params)])
            _cmd.extend(["--format", "json"])
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=GWS_TIMEOUT)
            if _r.returncode != 0:
                return {
                    "status": "error",
                    "data": {},
                    "error_message": f"Admin Reports API error: {_r.stderr[:500] if _r.stderr else f'gws exit {_r.returncode}'}"
                }
            _data = json.loads(_r.stdout) if _r.stdout.strip() else {}
            activities.extend(_data.get("items", []))
            pages_fetched += 1
            next_page_token = _data.get("nextPageToken")
            if not next_page_token:
                break
            time.sleep(0.1)

        # Filter activities for specified documents
        doc_activities = {}
        doc_id_set = set(doc_ids)

        for doc_id in doc_ids:
            doc_activities[doc_id] = {
                "doc_id": doc_id,
                "events": [],
                "summary": {
                    "edit_count": 0,
                    "view_count": 0,
                    "share_count": 0,
                    "comment_count": 0,
                },
            }

        for activity in activities:
            for event in activity.get("events", []):
                for param in event.get("parameters", []):
                    if param.get("name") == "doc_id":
                        doc_id = param.get("value")
                        if doc_id in doc_id_set:
                            event_name = event.get("name", "unknown")
                            doc_activities[doc_id]["events"].append({
                                "time": activity.get("id", {}).get("time"),
                                "actor": activity.get("actor", {}).get("email", "(unknown)"),
                                "action": event_name,
                            })

                            if event_name == "edit":
                                doc_activities[doc_id]["summary"]["edit_count"] += 1
                            elif event_name == "view":
                                doc_activities[doc_id]["summary"]["view_count"] += 1
                            elif event_name in ["change_user_access", "change_acl_editors"]:
                                doc_activities[doc_id]["summary"]["share_count"] += 1
                            elif event_name in ["create_comment", "resolve_comment"]:
                                doc_activities[doc_id]["summary"]["comment_count"] += 1

        # Sort events by time for each document
        for doc in doc_activities.values():
            doc["events"].sort(key=lambda x: x["time"] or "", reverse=True)

        return {
            "status": "ok",
            "data": {
                "documents": list(doc_activities.values()),
                "period_days": days,
                "truncated": pages_fetched >= MAX_PAGES,
            }
        }

    except Exception as e:
        import traceback
        return {
            "status": "error",
            "data": {},
            "error_message": f"Error getting document events: {str(e)}\n{traceback.format_exc()}"
        }

import os
import json
import csv

def analyze_slack_analytics(file_url: str, top_n: int = 10) -> str:
    """Analyze a Slack analytics CSV file and generate summary.

    Args:
        file_url: The url_private_download from list_recent_slack_files()
        top_n: Number of top results to return (default 10)

    Returns:
        JSON with analysis results including top channels/members by various metrics

    Examples:
        # After listing files, analyze a channels file
        analyze_slack_analytics("https://files.slack.com/.../channels-2024-10-14.csv")

        # Analyze with custom top N
        analyze_slack_analytics("https://files.slack.com/.../members.csv", top_n=15)
    """
    import urllib.request
    import io

    TOKEN = os.getenv("SLACK_MCP_XOXP_TOKEN", "")
    if not TOKEN:
        return json.dumps({"error": "SLACK_MCP_XOXP_TOKEN not set"}, indent=2)

    if not file_url:
        return json.dumps({"error": "No file URL provided"}, indent=2)

    results = {
        "file_url": file_url,
        "file_type": None,
        "analysis": None,
        "errors": []
    }

    try:
        # Download the file
        req = urllib.request.Request(
            file_url,
            headers={"Authorization": f"Bearer {TOKEN}"}
        )

        with urllib.request.urlopen(req, timeout=30) as response:
            content = response.read().decode("utf-8")

        # Parse CSV
        csv_reader = csv.DictReader(io.StringIO(content))
        rows = list(csv_reader)

        if not rows:
            results["errors"].append("Empty file")
            return json.dumps(results, indent=2)

        # Detect file type based on columns
        columns = set(rows[0].keys())

        # Channels file detection - look for channel-specific metrics
        has_channel_metrics = ("Members who posted" in columns or "Members posted" in columns) and                              ("Members who viewed" in columns or "Members viewed" in columns)

        # Channels file detection and analysis
        if has_channel_metrics or "Channel" in columns or "Channel name" in columns:
            results["file_type"] = "channels"

            # Find channel column (Slack exports use "Name" for channels)
            channel_col = None
            for name in ["Channel", "Channel name", "Name", "channel", "channel_name", "name"]:
                if name in rows[0]:
                    channel_col = name
                    break

            if not channel_col:
                results["errors"].append("Could not find channel name column")
                return json.dumps(results, indent=2)

            ch_analysis = {
                "total_channels": len(rows),
                "top_by_messages_posted": [],
                "top_by_members_posted": [],
                "top_by_members_viewed": []
            }

            # Messages posted
            msg_col = None
            for name in ["Messages posted", "messages_posted", "Messages", "Messages sent"]:
                if name in rows[0]:
                    msg_col = name
                    break
            if msg_col:
                sorted_msgs = sorted(
                    rows,
                    key=lambda r: int(r.get(msg_col, "0").replace(",", "")),
                    reverse=True
                )[:top_n]
                ch_analysis["top_by_messages_posted"] = [
                    {"channel": r[channel_col], "count": int(r[msg_col].replace(",", ""))}
                    for r in sorted_msgs
                ]

            # Members posted
            posted_col = None
            for name in ["Members who posted", "Members posted", "members_posted", "Posters"]:
                if name in rows[0]:
                    posted_col = name
                    break
            if posted_col:
                sorted_posted = sorted(
                    rows,
                    key=lambda r: int(r.get(posted_col, "0").replace(",", "")),
                    reverse=True
                )[:top_n]
                ch_analysis["top_by_members_posted"] = [
                    {"channel": r[channel_col], "count": int(r[posted_col].replace(",", ""))}
                    for r in sorted_posted
                ]

            # Members viewed
            viewed_col = None
            for name in ["Members who viewed", "Members viewed", "members_viewed", "Viewers"]:
                if name in rows[0]:
                    viewed_col = name
                    break
            if viewed_col:
                sorted_viewed = sorted(
                    rows,
                    key=lambda r: int(r.get(viewed_col, "0").replace(",", "")),
                    reverse=True
                )[:top_n]
                ch_analysis["top_by_members_viewed"] = [
                    {"channel": r[channel_col], "count": int(r[viewed_col].replace(",", ""))}
                    for r in sorted_viewed
                ]

            results["analysis"] = ch_analysis

        # Members file detection and analysis
        elif "Full name" in columns or "Display name" in columns or "Member" in columns:
            results["file_type"] = "members"

            # Find name column
            name_col = None
            for name in ["Full name", "Display name", "Member", "Name", "User"]:
                if name in rows[0]:
                    name_col = name
                    break

            if not name_col:
                results["errors"].append("Could not find member name column")
                return json.dumps(results, indent=2)

            mem_analysis = {
                "total_members": len(rows),
                "top_by_messages_posted": []
            }

            # Messages posted
            msg_col = None
            for col_name in ["Messages posted", "messages_posted", "Messages"]:
                if col_name in rows[0]:
                    msg_col = col_name
                    break
            if msg_col:
                sorted_msgs = sorted(
                    rows,
                    key=lambda r: int(r.get(msg_col, "0").replace(",", "")),
                    reverse=True
                )[:top_n]
                mem_analysis["top_by_messages_posted"] = [
                    {"member": r[name_col], "count": int(r[msg_col].replace(",", ""))}
                    for r in sorted_msgs
                ]

            results["analysis"] = mem_analysis

        else:
            results["errors"].append(f"Unknown file type (columns: {list(columns)[:5]})")

    except Exception as e:
        results["errors"].append(f"Error processing file: {str(e)}")

    return json.dumps(results, indent=2)

def trigger_slack_analytics_export(analytics_type: str = "all") -> Dict[str, Any]:
    """Trigger Slack analytics CSV export via the slack-analytics-mcp-server.

    Calls the browser automation service to click "Export CSV" in Slack's admin
    analytics dashboard. The generated CSV files are delivered to Slackbot DMs
    within seconds and can then be picked up by collect_analytics_snapshot().

    Args:
        analytics_type: What to export. Options: 'channels', 'members', 'all'. Use 'all' to trigger both channels and members exports sequentially.

    Returns:
        Dictionary with status and export results.
    """
    import json
    import os
    import traceback
    import urllib.request
    import urllib.error

    try:
        EXPORT_URL = os.getenv(
            "SLACK_ANALYTICS_EXPORT_URL",
            "http://slack-analytics-mcp-server:8087/trigger-export",
        )
        REQUEST_TIMEOUT = 90

        valid_types = ("channels", "members", "all")
        if analytics_type not in valid_types:
            return {
                "status": "error",
                "error_message": f"Invalid analytics_type '{analytics_type}'. Must be one of: {', '.join(valid_types)}",
            }

        types_to_run = ["channels", "members"] if analytics_type == "all" else [analytics_type]
        results = []

        for atype in types_to_run:
            payload = json.dumps({
                "analytics_type": atype,
                "days_ago": 3,
                "date_range_days": 1,
            }).encode("utf-8")

            req = urllib.request.Request(
                EXPORT_URL,
                data=payload,
                headers={"Content-Type": "application/json"},
                method="POST",
            )

            try:
                with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT) as resp:
                    body = json.loads(resp.read().decode("utf-8"))
                    results.append({
                        "type": atype,
                        "success": body.get("success", False),
                        "message": body.get("message", ""),
                        "date_range": body.get("date_range", {}),
                    })
            except urllib.error.HTTPError as http_err:
                error_body = http_err.read().decode("utf-8", errors="replace")[:500]
                results.append({
                    "type": atype,
                    "success": False,
                    "error": f"HTTP {http_err.code}: {error_body}",
                })
            except urllib.error.URLError as url_err:
                results.append({
                    "type": atype,
                    "success": False,
                    "error": f"Connection error: {str(url_err.reason)}",
                })

        all_ok = all(r.get("success") for r in results)
        return {
            "status": "ok" if all_ok else "partial",
            "exports": results,
            "summary": f"Triggered {len([r for r in results if r.get('success')])} of {len(results)} exports successfully.",
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}",
        }

def query_curator_radar(endpoint: str, params: Optional[str] = None) -> Dict[str, Any]:
    """
    Query the Curator Radar service — discovers people with similar taste
    in GitHub repos and Twitter content, then surfaces what they're finding.

    Use endpoint="schema" to see all available endpoints and their parameters.
    Use endpoint="schema <name>" to see details for a specific endpoint.

    Quick start:
      endpoint="discoveries"                          -- What did my curators find this week?
      endpoint="curators"                             -- Who are my top curators?
      endpoint="digest"                               -- Full weekly report
      endpoint="twitter/curators"                     -- Top Twitter curators
      endpoint="schema"                               -- List all endpoints

    Args:
        endpoint: API endpoint or "schema" for discovery (REQUIRED)
        params: Optional JSON string of query parameters (e.g. '{"top_k": 10}')

    Returns:
        Dictionary with status and the API response.
    """
    import json
    import traceback
    import urllib.request
    import urllib.parse

    try:
        clean = endpoint.strip().strip("/")

        # Schema discovery
        if clean == "schema":
            groups = {"github": [], "twitter": []}
            for name, meta in ENDPOINTS.items():
                group = "twitter" if name.startswith("twitter/") else "github"
                groups[group].append(
                    {"endpoint": name, "method": meta["method"], "description": meta["description"]}
                )
            return {"status": "ok", "result": groups}

        if clean.startswith("schema "):
            target = clean.split(" ", 1)[1].strip("/")
            if target in ENDPOINTS:
                meta = ENDPOINTS[target]
                return {"status": "ok", "result": {
                    "endpoint": target,
                    "method": meta["method"],
                    "description": meta["description"],
                    "params": meta["params"] or "(none)",
                }}
            return {"status": "error", "error_message": f"Unknown endpoint: {target}. Use endpoint='schema' to list all."}

        # Resolve method from registry
        meta = ENDPOINTS.get(clean)
        if not meta:
            return {"status": "error", "error_message": f"Unknown endpoint: {clean}. Use endpoint='schema' to list all."}

        base_url = "http://curator-radar:5145/v1"
        url = f"{base_url}/{clean}"

        query_params = {}
        if params:
            query_params = json.loads(params)

        if meta["method"] == "GET" and query_params:
            url += "?" + urllib.parse.urlencode(query_params)

        req = urllib.request.Request(url, method=meta["method"])
        req.add_header("Content-Type", "application/json")

        resp = urllib.request.urlopen(req, timeout=60)
        data = json.loads(resp.read().decode())

        return {"status": "ok", "result": data}

    except Exception as e:
        return {"status": "error", "error_message": f"{str(e)}\n{traceback.format_exc()}"}

