def find_user_blocks(
    user_id: str,
    scope: Optional[str] = None
) -> Dict[str, Any]:
    """
    Discover all memory blocks for a user via naming convention.

    This tool is called by the agent to find blocks belonging to a specific user.
    Blocks are identified by naming convention: {category}_{user_id} or
    {agent_name}_{category}_{user_id}_{purpose}.

    Args:
        user_id: The user identifier (e.g., Slack user ID like "U12345678")
        scope: Filter scope - "all" (default), "cross_agent", or "agent_specific".
               "all" returns all blocks matching user_id.
               "cross_agent" returns only blocks WITHOUT agent name prefix (shared).
               "agent_specific" returns only blocks WITH agent name prefix.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - blocks: List of dicts with block info {id, label, value_preview}
        - count: Number of blocks found
        - error_message: Error message if status is "error"

    Example:
        >>> find_user_blocks(user_id="U12345678", scope="all")
        {
            "status": "ok",
            "blocks": [
                {"id": "block-abc", "label": "preferences_U12345678", "value_preview": "Prefers morning..."},
                {"id": "block-def", "label": "calendar_U12345678", "value_preview": "Calendar synced..."}
            ],
            "count": 2
        }
    """
    # IMPORTS FIRST - inside function for Letta tool extraction
    import os
    import re
    import traceback

    try:
        from letta_client import Letta
    except ImportError:
        try:
            from letta import Letta
        except ImportError:
            Letta = None

    # TRY-EXCEPT WRAPPER
    try:
        # SET DEFAULTS
        if scope is None:
            scope = "all"

        # CONFIGURATION - inside function for Letta tool extraction
        agent_name = os.getenv("AGENT_NAME", "meeting_scheduler")
        letta_base_url = os.getenv("LETTA_BASE_URL", "http://localhost:8283")
        letta_agent_id = os.getenv(
            "LETTA_AGENT_ID",
            os.getenv("SCHEDULER_AGENT_ID", "agent-892a2d58-b9f6-4baf-84f3-c431fe46487d")
        )

        # INPUT VALIDATION
        if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": f"Invalid user_id format: {user_id}. Must be alphanumeric with underscores/hyphens."
            }

        if scope not in ("all", "cross_agent", "agent_specific"):
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": f"Invalid scope: {scope}. Must be 'all', 'cross_agent', or 'agent_specific'."
            }

        # GET AGENT BLOCKS (inline, no helper function)
        if Letta is None:
            return {
                "status": "error",
                "blocks": [],
                "count": 0,
                "error_message": "Letta client not available"
            }

        client = Letta(base_url=letta_base_url)
        agent = client.agents.retrieve(agent_id=letta_agent_id)
        all_blocks = agent.memory.blocks if agent.memory else []

        # FILTER BY USER_ID IN LABEL
        # Match patterns: {category}_{user_id} or {prefix}_{user_id}_{suffix}
        user_blocks = []
        for block in all_blocks:
            label = getattr(block, 'label', '') or ''
            # Check if user_id appears in label (either as suffix or in middle)
            if f"_{user_id}" in label or f"_{user_id}_" in label or label.endswith(f"_{user_id}"):
                user_blocks.append(block)

        # APPLY SCOPE FILTERING
        agent_prefix = f"{agent_name}_"

        if scope == "cross_agent":
            # Exclude blocks that start with agent name
            user_blocks = [b for b in user_blocks if not (getattr(b, 'label', '') or '').startswith(agent_prefix)]
        elif scope == "agent_specific":
            # Include only blocks that start with agent name
            user_blocks = [b for b in user_blocks if (getattr(b, 'label', '') or '').startswith(agent_prefix)]
        # scope == "all" returns everything matching user_id

        # FORMAT RESPONSE WITH VALUE PREVIEW
        result_blocks = []
        for block in user_blocks:
            value = getattr(block, 'value', '') or ''
            preview = value[:100] + "..." if len(value) > 100 else value
            result_blocks.append({
                "id": block.id,
                "label": getattr(block, 'label', ''),
                "value_preview": preview
            })

        return {
            "status": "ok",
            "blocks": result_blocks,
            "count": len(result_blocks)
        }

    except Exception as e:
        return {
            "status": "error",
            "blocks": [],
            "count": 0,
            "error_message": f"Failed to find user blocks: {str(e)}\n{traceback.format_exc()}"
        }

def create_user_memory_block(
    user_id: str,
    category: str,
    value: str,
    purpose: Optional[str] = None,
    agent_specific: Optional[bool] = None
) -> Dict[str, Any]:
    """
    Create a new memory block for emergent user preferences.

    This tool is called by the agent when it learns something new about a user
    that should be persisted. The block is created with a naming convention
    that enables later discovery via find_user_blocks.

    Naming conventions:
    - Cross-agent: {category}_{user_id}[_{purpose}]
    - Agent-specific: {agent_name}_{category}_{user_id}[_{purpose}]

    Args:
        user_id: The user identifier (e.g., Slack user ID like "U12345678")
        category: Block category (e.g., "preferences", "calendar", "context")
        value: Initial block content (max 2000 characters)
        purpose: Optional specific purpose (e.g., "meeting_duration", "timezone")
        agent_specific: If True, prefix with agent name (only this agent sees it). Default: False.

    Returns:
        Dictionary with keys:
        - status: "ok" or "error"
        - block_id: ID of created block (if successful)
        - label: Label of created block (if successful)
        - error_message: Error message if status is "error"

    Example:
        >>> create_user_memory_block(
        ...     user_id="U12345678",
        ...     category="preferences",
        ...     value="Prefers 30 minute meetings in the morning",
        ...     purpose="meeting_duration"
        ... )
        {"status": "ok", "block_id": "block-abc123", "label": "preferences_U12345678_meeting_duration"}
    """
    # IMPORTS FIRST - inside function for Letta tool extraction
    import os
    import re
    import traceback

    try:
        from letta_client import Letta
    except ImportError:
        try:
            from letta import Letta
        except ImportError:
            Letta = None

    # TRY-EXCEPT WRAPPER
    try:
        # SET DEFAULTS
        if agent_specific is None:
            agent_specific = False

        # CONFIGURATION - inside function for Letta tool extraction
        agent_name = os.getenv("AGENT_NAME", "meeting_scheduler")
        letta_base_url = os.getenv("LETTA_BASE_URL", "http://localhost:8283")
        letta_agent_id = os.getenv(
            "LETTA_AGENT_ID",
            os.getenv("SCHEDULER_AGENT_ID", "agent-892a2d58-b9f6-4baf-84f3-c431fe46487d")
        )

        # INPUT VALIDATION
        if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
            return {
                "status": "error",
                "error_message": f"Invalid user_id format: {user_id}. Must be alphanumeric with underscores/hyphens."
            }

        if not re.match(r'^[a-zA-Z0-9_-]+$', category):
            return {
                "status": "error",
                "error_message": f"Invalid category format: {category}. Must be alphanumeric with underscores/hyphens."
            }

        if purpose and not re.match(r'^[a-zA-Z0-9_-]+$', purpose):
            return {
                "status": "error",
                "error_message": f"Invalid purpose format: {purpose}. Must be alphanumeric with underscores/hyphens."
            }

        if len(value) > 2000:
            return {
                "status": "error",
                "error_message": f"Block value too long ({len(value)} chars). Maximum is 2000 characters."
            }

        # BUILD LABEL BASED ON NAMING CONVENTION
        if agent_specific:
            label = f"{agent_name}_{category}_{user_id}"
        else:
            label = f"{category}_{user_id}"

        if purpose:
            label += f"_{purpose}"

        # Normalize label
        label = label.lower().replace(" ", "_")

        if len(label) > 200:
            return {
                "status": "error",
                "error_message": f"Block label too long ({len(label)} chars). Maximum is 200 characters."
            }

        # GET LETTA CLIENT (inline, no helper function)
        if Letta is None:
            return {
                "status": "error",
                "error_message": "Letta client not available. Check LETTA_BASE_URL configuration."
            }

        client = Letta(base_url=letta_base_url)

        # CREATE THE BLOCK
        description = f"{category} for {user_id}"
        if purpose:
            description += f": {purpose}"

        block = client.blocks.create(
            label=label,
            value=value,
            description=description,
            limit=2000
        )

        # ATTACH BLOCK TO AGENT
        client.agents.blocks.attach(
            agent_id=letta_agent_id,
            block_id=block.id
        )

        return {
            "status": "ok",
            "block_id": block.id,
            "label": label
        }

    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to create block: {str(e)}\n{traceback.format_exc()}"
        }

def coordinate_task(
    task_type: str,
    context: str,
    questions_asked: Optional[str] = None
) -> Dict[str, Any]:
    """
    Execute multi-agent coordination for a defined task type.

    Call this after gathering sufficient context through conversation.
    Available task types can be found in docs/task-types/.

    Args:
        task_type: Name of the task type (e.g., "meeting_prep", "project_status")
        context: JSON string with task-specific context gathered from conversation.
                 Example: {"meeting_identifier": "Board Meeting tomorrow 2pm",
                          "focus_areas": ["participants", "documents"]}
        questions_asked: Optional JSON array of question IDs asked before execution.
                        Example: ["which_meeting", "focus_areas"]

    Returns:
        Dictionary with:
        - status: "complete", "partial", or "error"
        - synthesis: Synthesized response text
        - findings: Dict of agent name to contribution
        - agents_completed: List of agents that contributed
        - agents_failed: List of agents that failed/timed out
        - coordination_time_ms: Total coordination time
    """
    # ALL IMPORTS INSIDE FUNCTION - required for Letta tool extraction
    import json
    import requests
    import traceback
    import os

    try:
        # Parse context JSON
        if isinstance(context, str):
            context_dict = json.loads(context)
        else:
            context_dict = context

        # Parse questions if provided
        questions = []
        if questions_asked:
            if isinstance(questions_asked, str):
                questions = json.loads(questions_asked)
            else:
                questions = questions_asked

        # Get routing handler URL from environment
        routing_handler_url = os.getenv(
            "PA_ROUTING_HANDLER_URL",
            "http://pa-routing-handler:5201"
        )

        # Get identity ID from environment or use default
        identity_id = os.getenv("CURRENT_IDENTITY_ID", "identity-default")

        # Call coordination endpoint
        response = requests.post(
            f"{routing_handler_url}/v1/coordinate",
            json={
                "identity_id": identity_id,
                "task_type": task_type,
                "context": context_dict,
                "questions_asked": questions
            },
            timeout=120  # 2 minute timeout for full coordination
        )

        if response.status_code != 200:
            return {
                "status": "error",
                "error_message": f"Coordination failed: {response.status_code} - {response.text[:500]}"
            }

        result = response.json()

        return {
            "status": result.get("status", "unknown"),
            "synthesis": result.get("synthesis", ""),
            "findings": result.get("findings", {}),
            "agents_completed": result.get("agents_completed", []),
            "agents_failed": result.get("agents_failed", []),
            "coordination_time_ms": result.get("coordination_time_ms")
        }

    except json.JSONDecodeError as e:
        return {
            "status": "error",
            "error_message": f"Invalid JSON in context: {str(e)}"
        }
    except requests.exceptions.Timeout:
        return {
            "status": "error",
            "error_message": "Coordination timed out after 120 seconds"
        }
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"{str(e)}\n{traceback.format_exc()}"
        }

